-- ########## 20261106000000_access_control_hardening.sql ##########
-- ============================================================================
-- LIORIS - ACCESS-CONTROL HARDENING (2026-11-06)
-- ============================================================================
-- Follows 20261105000000_profile_media_cross_campus_read.sql. It MUST run after every
-- migration up to and including 20261105: those files re-define several of the
-- functions / policies below (is_super_admin, is_profile_verified, the chat and
-- notification policies, admin_get_profile_contacts, resolve_takedown_request, ...),
-- and this file holds the final definitions. Everything is idempotent and guarded
-- (to_regclass / to_regprocedure / DO blocks) so a database that lacks some of the
-- objects still applies it.
--
-- WHAT THIS FIXES
--   1  anon could execute SECURITY DEFINER admin RPCs (the "NOT IN ('admin','staff')" guard is NULL for
--      anon, so it never raised). Guards fixed + schema-wide EXECUTE sweep (anon allow-list below).
--   2  Campus admins read/deleted private DMs: chat / notification / connection / block / mentorship
--      policies keyed on role='admin'. Only Super Admin keeps an override; a campus admin deletes chat
--      content only through admin_delete_chat_message when everyone involved is on their campus.
--   3  Definer RPCs that ignored campus scope now go through can_admin_campus(<campus of the row>).
--   4  Resume leak: job_applications.resume_url must live in the applicant's own folder; initial
--      status/review fields are forced; closed/expired jobs refuse applications.
--   5  Campus-wall bypass on INSERT (permissive policies ORed with the checked ones); campus_code /
--      visibility_scope are immutable for non-Super-Admins; scope_privileged_update WITH CHECK fixed.
--   6  Forged counters (likes, comments, downloads, upvotes, applications).
--   7  Notification spam / spoofing (sender forced, types + recipients + URLs constrained, rate limit).
--   8  Forced chat membership.
--   9  Anonymous listing of the avatars bucket.
--   10 Root-email Super Admin bootstrap now requires a CONFIRMED e-mail.
--   11 Takedown abuse (any account could hide any resource instantly).
--   12 Probe helpers (users_have_block, dm_channel_has_block, campus_of, is_profile_verified).
--   13 pg_temp last in search_path for SECURITY DEFINER functions.
--   14 role_permissions no longer readable by anon.
--   15 Verification evidence cannot be altered after the decision.
-- ============================================================================

BEGIN;
DO $chain$ BEGIN IF NOT EXISTS (SELECT 1 FROM public._manual_migration_log WHERE version = '20261105000000') THEN RAISE EXCEPTION 'Stopped: migration 20261105000000 has not been applied. Fix it and re-run this whole file.'; END IF; END $chain$;

DO $do$
BEGIN
  IF to_regclass('public.profiles') IS NULL THEN
    RAISE EXCEPTION 'Dependency missing: apply the base schema and earlier migrations first.';
  END IF;
END
$do$;

-- ----------------------------------------------------------------------------
-- 0. Optional-MFA hook must exist before auth_is_super_admin() refers to it
-- ----------------------------------------------------------------------------
DO $mfa$
BEGIN
  IF to_regprocedure('public.admin_aal2_ok()') IS NULL THEN
    EXECUTE $f$
      CREATE FUNCTION public.admin_aal2_ok() RETURNS boolean
      LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp
      AS 'SELECT true'
    $f$;
  END IF;
END
$mfa$;

-- ----------------------------------------------------------------------------
-- 10. auth_is_super_admin(): the root-e-mail bootstrap needs a CONFIRMED e-mail
-- ----------------------------------------------------------------------------
-- Before: the root e-mail alone (profile e-mail or JWT claim) was enough, i.e. whoever registered that
-- address before the owner did, with e-mail confirmation off or bypassed, became Super Admin. Now the
-- bootstrap arm reads auth.users and requires email_confirmed_at. Rows with admin_role = 'super_admin'
-- behave exactly as before. admin_aal2_ok() (optional MFA switch) is kept.
CREATE OR REPLACE FUNCTION public.auth_is_super_admin()
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT (
    COALESCE((
      SELECT (p.role::text = 'admin' AND p.admin_role = 'super_admin')
      FROM public.profiles p
      WHERE p.id = auth.uid()
    ), false)
    OR EXISTS (
      SELECT 1 FROM auth.users u
      WHERE u.id = auth.uid()
        AND u.email_confirmed_at IS NOT NULL
        AND LOWER(COALESCE(u.email, '')) = 'inememmanuel@gmail.com'
    )
  ) AND public.admin_aal2_ok();
$$;

-- ----------------------------------------------------------------------------
-- 12. Probe helpers: bind to the caller so they cannot be used to look arbitrary users up
-- ----------------------------------------------------------------------------
-- "Internal" = no JWT at all (SQL editor, migrations) or the service role. PostgREST always sets claims,
-- so a signed-out caller is role 'anon' and an unrelated signed-in caller is not internal.
CREATE OR REPLACE FUNCTION public.users_have_block(p_user_a uuid, p_user_b uuid)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT CASE
           WHEN auth.uid() IS NOT NULL AND auth.uid() NOT IN (COALESCE(p_user_a, auth.uid()), COALESCE(p_user_b, auth.uid()))
             THEN false
           WHEN auth.uid() IS NULL AND COALESCE(auth.role(), '') = 'anon' THEN false
           ELSE EXISTS (
             SELECT 1 FROM public.user_blocks
             WHERE (blocker_id = p_user_a AND blocked_id = p_user_b)
                OR (blocker_id = p_user_b AND blocked_id = p_user_a))
         END;
$$;

CREATE OR REPLACE FUNCTION public.dm_channel_has_block(p_channel_id uuid)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT (
           (auth.uid() IS NULL AND COALESCE(auth.role(), '') <> 'anon')
           OR EXISTS (SELECT 1 FROM public.chat_channel_members me WHERE me.channel_id = p_channel_id AND me.user_id = auth.uid())
         )
     AND EXISTS (
    SELECT 1
      FROM public.chat_channel_members a
      JOIN public.chat_channel_members b
        ON a.channel_id = b.channel_id
       AND a.user_id   <> b.user_id
      JOIN public.user_blocks ub
        ON (ub.blocker_id = a.user_id AND ub.blocked_id = b.user_id)
        OR (ub.blocker_id = b.user_id AND ub.blocked_id = a.user_id)
     WHERE a.channel_id = p_channel_id
  );
$$;

CREATE OR REPLACE FUNCTION public.dm_channel_has_block(p_channel_id uuid, p_sender_id uuid)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT (p_sender_id IS NOT DISTINCT FROM auth.uid() OR (auth.uid() IS NULL AND COALESCE(auth.role(), '') <> 'anon'))
     AND EXISTS (
        SELECT 1
        FROM public.chat_channels cc
        JOIN public.chat_channel_members other
          ON other.channel_id = cc.id AND other.user_id <> p_sender_id
        WHERE cc.id = p_channel_id
          AND cc.is_direct_message = true
          AND public.users_have_block(p_sender_id, other.user_id)
    );
$$;

-- campus_of(): a signed-in member only learns the campus of people they can already see (self, GLOBAL members,
-- members of their own campus). Everyone else resolves to NULL, which can_admin_campus() treats as "no authority".
CREATE OR REPLACE FUNCTION public.campus_of(p_user uuid)
RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_campus text;
  v_uid    uuid := auth.uid();
BEGIN
  SELECT p.campus_code INTO v_campus FROM public.profiles p WHERE p.id = p_user;
  IF v_campus IS NULL THEN RETURN NULL; END IF;
  IF v_uid IS NULL THEN
    IF COALESCE(auth.role(), '') = 'anon' THEN RETURN NULL; END IF;
    RETURN v_campus;                                   -- service role / SQL editor / migrations
  END IF;
  IF p_user = v_uid OR auth.role() = 'service_role' OR v_campus = 'GLOBAL' OR public.auth_is_super_admin() THEN RETURN v_campus; END IF;
  IF v_campus = (SELECT p2.campus_code FROM public.profiles p2 WHERE p2.id = v_uid) THEN RETURN v_campus; END IF;
  RETURN NULL;
END;
$$;

-- is_profile_verified(): the answer is only available for yourself (RLS policies and RPCs always pass
-- auth.uid()) or to internal callers; signed-out callers and other members get "false", not an oracle.
CREATE OR REPLACE FUNCTION public.is_profile_verified(p_user_id uuid)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT (
           p_user_id IS NOT DISTINCT FROM auth.uid()
           OR (auth.uid() IS NULL AND COALESCE(auth.role(), '') <> 'anon')
         )
     AND EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = p_user_id
      AND (
        p.role::text IN ('admin', 'staff')
        OR p.admin_role::text = 'super_admin'
        OR LOWER(COALESCE(p.email, '')) = 'inememmanuel@gmail.com'
        OR p.verification_status::text = 'verified'
        OR COALESCE(p.is_bot, FALSE) = TRUE
      )
      AND COALESCE(p.is_suspended, FALSE) = FALSE
  );
$$;

-- ----------------------------------------------------------------------------
-- 1 + 3. Admin RPCs: fix the NULL guard (anon) and route every check through can_admin_campus()
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.admin_get_profile_contacts(p_user_ids uuid[])
RETURNS TABLE (id uuid, full_name text, email text, role text, campus_code text, student_id_number text)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_service boolean := COALESCE(auth.role(), '') = 'service_role';
  v_role    text;
BEGIN
  IF NOT v_service THEN
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'admin_required'; END IF;
    SELECT LOWER(COALESCE(p.role::text, '')) INTO v_role FROM public.profiles p WHERE p.id = auth.uid();
    IF COALESCE(v_role, '') NOT IN ('admin', 'staff') THEN RAISE EXCEPTION 'admin_required'; END IF;
  END IF;
  IF p_user_ids IS NULL OR array_length(p_user_ids, 1) IS NULL THEN RETURN; END IF;

  RETURN QUERY
  SELECT p.id, p.full_name::text, p.email::text, p.role::text, p.campus_code::text, p.student_id_number::text
  FROM public.profiles p
  WHERE p.id = ANY (p_user_ids[1:200])
    AND (v_service OR public.auth_is_super_admin() OR public.can_admin_campus(p.campus_code));
END;
$$;

CREATE OR REPLACE FUNCTION public.admin_search_profiles(p_query text, p_limit integer DEFAULT 5)
RETURNS TABLE (id uuid, full_name text, email text, role text, campus_code text, verification_status text)
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_service boolean := COALESCE(auth.role(), '') = 'service_role';
  v_role    text;
  v_super   boolean := false;
  v_campus  text;
  v_query   text;
BEGIN
  IF NOT v_service THEN
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'admin_required'; END IF;
    SELECT LOWER(COALESCE(p.role::text, '')), UPPER(NULLIF(TRIM(p.campus_code::text), ''))
      INTO v_role, v_campus FROM public.profiles p WHERE p.id = auth.uid();
    IF COALESCE(v_role, '') NOT IN ('admin', 'staff') THEN RAISE EXCEPTION 'admin_required'; END IF;
    v_super := public.auth_is_super_admin();
    IF NOT v_super AND (v_campus IS NULL OR v_campus = 'GLOBAL') THEN RAISE EXCEPTION 'campus_assignment_required'; END IF;
  ELSE
    v_super := true;
  END IF;

  v_query := '%' || replace(replace(replace(COALESCE(TRIM(p_query), ''), '\', '\\'), '%', '\%'), '_', '\_') || '%';

  RETURN QUERY
  SELECT p.id, p.full_name::text, p.email::text, p.role::text, p.campus_code::text, p.verification_status::text
  FROM public.profiles p
  WHERE (p.full_name ILIKE v_query OR p.email ILIKE v_query)
    AND (v_super OR UPPER(COALESCE(p.campus_code::text, '')) = v_campus)
  ORDER BY p.full_name NULLS LAST, p.email
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 5), 1), 50);
END;
$$;

CREATE OR REPLACE FUNCTION public.get_admin_analytics_summary(p_days integer DEFAULT 30, p_campus_code text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_service boolean := COALESCE(auth.role(), '') = 'service_role';
  v_role text;
  v_caller_campus text;
  v_campus text;                       -- NULL = every campus
  v_since TIMESTAMPTZ;
  v_total_users INT := 0; v_real_users INT := 0; v_bot_users INT := 0; v_new_signups INT := 0;
  v_active_15m INT := 0; v_active_24h INT := 0; v_active_7d INT := 0; v_active_30d INT := 0;
  v_total_posts INT := 0; v_total_comments INT := 0; v_total_resources INT := 0; v_total_events INT := 0;
  v_total_rsvps INT := 0; v_total_poll_votes INT := 0; v_pending_verifications INT := 0;
  v_pages JSONB := '[]'::jsonb; v_features JSONB := '[]'::jsonb; v_campuses JSONB := '[]'::jsonb;
BEGIN
  IF v_service OR (auth.uid() IS NOT NULL AND public.auth_is_super_admin()) THEN
    v_campus := CASE WHEN p_campus_code IS NULL OR BTRIM(p_campus_code) = '' OR UPPER(BTRIM(p_campus_code)) = 'ALL'
                     THEN NULL ELSE BTRIM(p_campus_code) END;
  ELSE
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'admin_required'; END IF;
    SELECT LOWER(COALESCE(p.role::text, '')), NULLIF(TRIM(p.campus_code::text), '')
      INTO v_role, v_caller_campus FROM public.profiles p WHERE p.id = auth.uid();
    IF COALESCE(v_role, '') NOT IN ('admin', 'staff') THEN RAISE EXCEPTION 'admin_required'; END IF;
    IF v_caller_campus IS NULL OR v_caller_campus = 'GLOBAL' THEN RAISE EXCEPTION 'campus_assignment_required'; END IF;
    v_campus := v_caller_campus;       -- scoped callers are pinned to their own campus whatever they ask for
  END IF;

  v_since := NOW() - (LEAST(GREATEST(COALESCE(p_days, 30), 1), 365) || ' days')::INTERVAL;

  SELECT COUNT(*)::INT,
         COUNT(*) FILTER (WHERE NOT COALESCE(is_bot, false))::INT,
         COUNT(*) FILTER (WHERE COALESCE(is_bot, false))::INT,
         COUNT(*) FILTER (WHERE created_at >= v_since AND NOT COALESCE(is_bot, false))::INT,
         COUNT(*) FILTER (WHERE last_active_at >= NOW() - INTERVAL '15 minutes' AND NOT COALESCE(is_bot, false))::INT,
         COUNT(*) FILTER (WHERE last_active_at >= NOW() - INTERVAL '24 hours' AND NOT COALESCE(is_bot, false))::INT,
         COUNT(*) FILTER (WHERE last_active_at >= NOW() - INTERVAL '7 days' AND NOT COALESCE(is_bot, false))::INT,
         COUNT(*) FILTER (WHERE last_active_at >= NOW() - INTERVAL '30 days' AND NOT COALESCE(is_bot, false))::INT
    INTO v_total_users, v_real_users, v_bot_users, v_new_signups, v_active_15m, v_active_24h, v_active_7d, v_active_30d
  FROM public.profiles
  WHERE (v_campus IS NULL OR campus_code = v_campus);

  SELECT COUNT(*)::INT INTO v_total_posts FROM public.posts
  WHERE created_at >= v_since AND (v_campus IS NULL OR campus_code = v_campus);

  IF v_campus IS NOT NULL THEN
    SELECT COUNT(*)::INT INTO v_total_comments
    FROM public.post_comments c JOIN public.posts p ON p.id = c.post_id
    WHERE c.created_at >= v_since AND p.campus_code = v_campus;
  ELSE
    SELECT COUNT(*)::INT INTO v_total_comments FROM public.post_comments c WHERE c.created_at >= v_since;
  END IF;

  SELECT COUNT(*)::INT INTO v_total_resources FROM public.resources
  WHERE created_at >= v_since AND (v_campus IS NULL OR campus_code = v_campus);

  SELECT COUNT(*)::INT INTO v_total_events FROM public.events
  WHERE created_at >= v_since AND (v_campus IS NULL OR campus_code = v_campus);

  SELECT COUNT(*)::INT INTO v_total_rsvps FROM public.analytics_events
  WHERE event_type = 'feature_use' AND name = 'event_rsvp' AND created_at >= v_since
    AND (v_campus IS NULL OR campus_code = v_campus);

  SELECT COUNT(*)::INT INTO v_total_poll_votes FROM public.analytics_events
  WHERE event_type = 'feature_use' AND name = 'vote_poll' AND created_at >= v_since
    AND (v_campus IS NULL OR campus_code = v_campus);

  SELECT COUNT(*)::INT INTO v_pending_verifications FROM public.profiles
  WHERE verification_status = 'pending' AND (v_campus IS NULL OR campus_code = v_campus);

  SELECT COALESCE(JSONB_AGG(sub), '[]'::jsonb) INTO v_pages FROM (
    SELECT name, COUNT(*)::INT AS visits, COUNT(DISTINCT user_id)::INT AS unique_visitors
    FROM public.analytics_events
    WHERE event_type = 'page_view' AND created_at >= v_since AND (v_campus IS NULL OR campus_code = v_campus)
    GROUP BY name ORDER BY visits DESC LIMIT 15
  ) sub;

  SELECT COALESCE(JSONB_AGG(sub), '[]'::jsonb) INTO v_features FROM (
    SELECT name, COUNT(*)::INT AS uses, COUNT(DISTINCT user_id)::INT AS unique_users
    FROM public.analytics_events
    WHERE event_type = 'feature_use' AND name <> 'heartbeat' AND created_at >= v_since
      AND (v_campus IS NULL OR campus_code = v_campus)
    GROUP BY name ORDER BY uses DESC LIMIT 15
  ) sub;

  -- Campus breakdown: honours the requested / pinned campus (it used to list every campus to every caller).
  SELECT COALESCE(JSONB_AGG(sub), '[]'::jsonb) INTO v_campuses FROM (
    SELECT COALESCE(campus_code, 'GLOBAL') AS campus_code,
           COUNT(*)::INT AS total_members,
           COUNT(*) FILTER (WHERE NOT COALESCE(is_bot, false))::INT AS real_members,
           COUNT(*) FILTER (WHERE verification_status = 'verified' AND NOT COALESCE(is_bot, false))::INT AS verified_members,
           COUNT(*) FILTER (WHERE last_active_at >= NOW() - INTERVAL '7 days' AND NOT COALESCE(is_bot, false))::INT AS active_7d
    FROM public.profiles
    WHERE (v_campus IS NULL OR campus_code = v_campus)
    GROUP BY campus_code ORDER BY total_members DESC
  ) sub;

  RETURN JSONB_BUILD_OBJECT(
    'total_users', COALESCE(v_total_users, 0), 'real_users', COALESCE(v_real_users, 0),
    'bot_users', COALESCE(v_bot_users, 0), 'new_signups', COALESCE(v_new_signups, 0),
    'active_15m', COALESCE(v_active_15m, 0), 'active_24h', COALESCE(v_active_24h, 0),
    'active_7d', COALESCE(v_active_7d, 0), 'active_30d', COALESCE(v_active_30d, 0),
    'total_posts', COALESCE(v_total_posts, 0), 'total_comments', COALESCE(v_total_comments, 0),
    'total_resources', COALESCE(v_total_resources, 0), 'total_events', COALESCE(v_total_events, 0),
    'total_rsvps', COALESCE(v_total_rsvps, 0), 'total_poll_votes', COALESCE(v_total_poll_votes, 0),
    'pending_verifications', COALESCE(v_pending_verifications, 0),
    'most_visited_pages', v_pages, 'most_used_features', v_features, 'campus_metrics', v_campuses
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.get_scoped_admin_analytics_summary(p_days integer DEFAULT 30, p_campus_code text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_service boolean := COALESCE(auth.role(), '') = 'service_role';
  v_role    text;
  v_campus  text;
BEGIN
  IF NOT v_service THEN
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'admin_required'; END IF;
    SELECT LOWER(COALESCE(p.role::text, '')), UPPER(NULLIF(TRIM(p.campus_code::text), ''))
      INTO v_role, v_campus FROM public.profiles p WHERE p.id = auth.uid();
    IF COALESCE(v_role, '') NOT IN ('admin', 'staff') THEN RAISE EXCEPTION 'admin_required'; END IF;
    IF NOT public.auth_is_super_admin() AND (v_campus IS NULL OR v_campus = 'GLOBAL') THEN
      RAISE EXCEPTION 'campus_assignment_required';
    END IF;
  END IF;
  -- get_admin_analytics_summary() pins non-super callers to their own campus itself.
  RETURN public.get_admin_analytics_summary(
    LEAST(GREATEST(COALESCE(p_days, 30), 1), 365),
    CASE WHEN v_service OR public.auth_is_super_admin() THEN NULLIF(UPPER(TRIM(COALESCE(p_campus_code, ''))), 'ALL') ELSE v_campus END
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.admin_get_user_diagnostics(p_user_id uuid)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_service BOOLEAN := COALESCE(auth.role(), '') = 'service_role';
  v_caller_role TEXT;
  v_target_campus TEXT;
  v_muted_count INT := 0;
  v_muted_by_count INT := 0;
  v_recent_muted JSONB := '[]'::jsonb;
  v_recent_muted_by JSONB := '[]'::jsonb;
  v_alerts_total_count INT := 0;
  v_alerts_active_count INT := 0;
  v_alerts JSONB := '[]'::jsonb;
  v_prefs JSONB;
BEGIN
  IF NOT v_service THEN
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'admin_required'; END IF;
    SELECT LOWER(COALESCE(role::text, '')) INTO v_caller_role FROM public.profiles WHERE id = auth.uid();
    IF COALESCE(v_caller_role, '') NOT IN ('admin', 'staff') THEN RAISE EXCEPTION 'admin_required'; END IF;
  END IF;

  SELECT campus_code INTO v_target_campus FROM public.profiles WHERE id = p_user_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'user_not_found'; END IF;

  IF NOT v_service AND NOT public.auth_is_super_admin() AND NOT public.can_admin_campus(v_target_campus) THEN
    RAISE EXCEPTION 'admin_required';
  END IF;

  SELECT COUNT(*)::INT INTO v_muted_count FROM public.user_mutes WHERE muter_id = p_user_id;
  SELECT COUNT(*)::INT INTO v_muted_by_count FROM public.user_mutes WHERE muted_id = p_user_id;

  SELECT COALESCE(JSONB_AGG(sub), '[]'::jsonb) INTO v_recent_muted FROM (
    SELECT m.muted_id AS user_id, p.full_name, m.created_at
    FROM public.user_mutes m JOIN public.profiles p ON p.id = m.muted_id
    WHERE m.muter_id = p_user_id ORDER BY m.created_at DESC LIMIT 5
  ) sub;

  SELECT COALESCE(JSONB_AGG(sub), '[]'::jsonb) INTO v_recent_muted_by FROM (
    SELECT m.muter_id AS user_id, p.full_name, m.created_at
    FROM public.user_mutes m JOIN public.profiles p ON p.id = m.muter_id
    WHERE m.muted_id = p_user_id ORDER BY m.created_at DESC LIMIT 5
  ) sub;

  SELECT COUNT(*)::INT, COUNT(*) FILTER (WHERE is_active)::INT
    INTO v_alerts_total_count, v_alerts_active_count
  FROM public.job_alerts WHERE user_id = p_user_id;

  SELECT COALESCE(JSONB_AGG(sub), '[]'::jsonb) INTO v_alerts FROM (
    SELECT id, keywords, job_type, remote_only, campus_code, is_active, created_at, last_notified_at
    FROM public.job_alerts WHERE user_id = p_user_id ORDER BY created_at DESC
  ) sub;

  SELECT JSONB_BUILD_OBJECT(
    'has_custom_row', true, 'push_enabled', push_enabled, 'announcements_enabled', announcements_enabled,
    'events_enabled', events_enabled, 'digest_enabled', digest_enabled, 'updated_at', updated_at
  ) INTO v_prefs FROM public.notification_preferences WHERE user_id = p_user_id;

  IF v_prefs IS NULL THEN
    v_prefs := JSONB_BUILD_OBJECT('has_custom_row', false, 'push_enabled', true, 'announcements_enabled', true,
                                  'events_enabled', true, 'digest_enabled', true, 'updated_at', NULL);
  END IF;

  RETURN JSONB_BUILD_OBJECT(
    'user_id', p_user_id,
    'mutes', JSONB_BUILD_OBJECT('muted_count', v_muted_count, 'muted_by_count', v_muted_by_count,
                                'recent_muted', v_recent_muted, 'recent_muted_by', v_recent_muted_by),
    'job_alerts', JSONB_BUILD_OBJECT('total_count', v_alerts_total_count, 'active_count', v_alerts_active_count, 'alerts', v_alerts),
    'notification_preferences', v_prefs
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.admin_campus_overview()
RETURNS TABLE (
  code text, name text, short_name text, location text, primary_color text, website_url text,
  email_domains text[], is_active boolean, created_at timestamptz,
  member_count integer, verified_count integer, portal_link_count integer, active_portal_link_count integer
)
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_service boolean := COALESCE(auth.role(), '') = 'service_role';
BEGIN
  IF NOT v_service AND (auth.uid() IS NULL OR COALESCE(public.auth_profile_role(), '') <> 'admin') THEN
    RAISE EXCEPTION 'not_allowed: administrators only';
  END IF;
  RETURN QUERY
  SELECT c.code, c.name, c.short_name, c.location, c.primary_color, c.website_url,
         c.email_domains, c.is_active, c.created_at,
         (SELECT count(*)::integer FROM public.profiles p WHERE p.campus_code = c.code),
         (SELECT count(*)::integer FROM public.profiles p WHERE p.campus_code = c.code AND p.verification_status::text = 'verified'),
         (SELECT count(*)::integer FROM public.portal_links l WHERE l.campus_code = c.code),
         (SELECT count(*)::integer FROM public.portal_links l WHERE l.campus_code = c.code AND l.is_active)
  FROM public.campuses c
  WHERE v_service OR public.auth_is_super_admin() OR public.can_admin_campus(c.code)
  ORDER BY (c.code = 'GLOBAL') DESC, c.name;
END
$$;

CREATE OR REPLACE FUNCTION public.get_giving_campaign_click_count(p_campaign uuid)
RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_count integer;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_allowed: sign in first.'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.giving_campaigns c
    WHERE c.id = p_campaign
      AND (c.creator_id = auth.uid() OR public.can_admin_campus(c.campus_code))   -- GLOBAL / NULL campus = Super Admin only
  ) THEN
    RAISE EXCEPTION 'not_allowed: Only the campaign owner or an admin of its campus can see its click count.';
  END IF;
  SELECT count(*) INTO v_count FROM public.giving_campaign_clicks WHERE campaign_id = p_campaign;
  RETURN COALESCE(v_count, 0);
END;
$$;

CREATE OR REPLACE FUNCTION public.get_report_count_for_author(
  p_item_type moderation_item_type, p_item_id uuid, p_exclude_report_id uuid DEFAULT NULL
)
RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_service boolean := COALESCE(auth.role(), '') = 'service_role';
  v_caller_role TEXT;
  v_author UUID;
  v_count INTEGER;
BEGIN
  IF NOT v_service THEN
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'admin_required'; END IF;
    SELECT LOWER(COALESCE(role::text, '')) INTO v_caller_role FROM public.profiles WHERE id = auth.uid();
    IF COALESCE(v_caller_role, '') NOT IN ('admin', 'staff') THEN RAISE EXCEPTION 'admin_required'; END IF;
  END IF;

  v_author := public.resolve_moderation_item_author(p_item_type, p_item_id);
  IF v_author IS NULL THEN RETURN 0; END IF;

  -- Only for authors the caller administers (GLOBAL / unknown campus = Super Admin only).
  IF NOT v_service AND NOT public.auth_is_super_admin()
     AND NOT public.can_admin_campus((SELECT p.campus_code FROM public.profiles p WHERE p.id = v_author)) THEN
    RETURN 0;
  END IF;

  SELECT count(*) INTO v_count
  FROM public.moderation_queue mq
  WHERE (p_exclude_report_id IS NULL OR mq.id <> p_exclude_report_id)
    AND public.resolve_moderation_item_author(mq.item_type, mq.item_id) = v_author;
  RETURN COALESCE(v_count, 0);
END;
$$;

-- event_can_manage(): creator, or an admin/staff member of the EVENT's campus, or a Super Admin.
-- (It used to be "any admin, anywhere"; the same helper gates event_roster, checkin_event_attendee,
--  confirm_event_purchase, event_referral_report, get_event_payment_info and the payment-details policy.)
CREATE OR REPLACE FUNCTION public.event_can_manage(p_event uuid)
RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_creator uuid;
  v_campus  text;
BEGIN
  IF auth.uid() IS NULL THEN RETURN false; END IF;
  IF COALESCE((SELECT p.is_suspended FROM public.profiles p WHERE p.id = auth.uid()), false) THEN RETURN false; END IF;
  SELECT e.creator_id, e.campus_code INTO v_creator, v_campus FROM public.events e WHERE e.id = p_event;
  IF NOT FOUND THEN RETURN false; END IF;
  RETURN v_creator = auth.uid() OR public.can_admin_campus(v_campus);
END;
$$;

CREATE OR REPLACE FUNCTION public.can_moderate_pod(p_group uuid)
RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF auth.uid() IS NULL THEN RETURN false; END IF;
  IF COALESCE(public.pod_role(p_group) IN ('owner', 'moderator'), false) THEN RETURN true; END IF;
  RETURN public.can_admin_campus((SELECT g.campus_code FROM public.study_groups g WHERE g.id = p_group));
END;
$$;

CREATE OR REPLACE FUNCTION public.is_mentorship_participant(p_mentorship uuid)
RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_student uuid;
  v_mentor  uuid;
BEGIN
  IF auth.uid() IS NULL THEN RETURN false; END IF;
  SELECT m.student_id, m.mentor_id INTO v_student, v_mentor FROM public.mentorships m WHERE m.id = p_mentorship;
  IF NOT FOUND THEN RETURN false; END IF;
  IF auth.uid() IN (v_student, v_mentor) THEN RETURN true; END IF;
  -- the mentee is the protected party: only their campus' admin (or a Super Admin) may look in
  RETURN public.can_admin_campus((SELECT p.campus_code FROM public.profiles p WHERE p.id = v_student));
END;
$$;

CREATE OR REPLACE FUNCTION public.list_my_mentorships(p_id uuid DEFAULT NULL)
RETURNS TABLE (
  id uuid, student_id uuid, mentor_id uuid, status text, track text, level text, pitch text, goals text, cadence text,
  plan_outline text, document_url text, document_name text, decline_reason text, end_reason text,
  started_at timestamptz, ended_at timestamptz, last_activity_at timestamptz, created_at timestamptz,
  student_name text, student_avatar text, student_department text, mentor_name text, mentor_avatar text, mentor_headline text
)
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT m.id, m.student_id, m.mentor_id, m.status, m.track, m.level, m.pitch, m.goals, m.cadence, m.plan_outline,
         m.document_url, m.document_name, m.decline_reason, m.end_reason, m.started_at, m.ended_at,
         m.last_activity_at, m.created_at,
         sp.full_name, sp.avatar_url, sp.department,
         mp.full_name, mp.avatar_url, mpr.headline
  FROM public.mentorships m
  LEFT JOIN public.profiles sp ON sp.id = m.student_id
  LEFT JOIN public.profiles mp ON mp.id = m.mentor_id
  LEFT JOIN public.mentor_profiles mpr ON mpr.user_id = m.mentor_id
  WHERE auth.uid() IS NOT NULL
    AND (m.student_id = auth.uid() OR m.mentor_id = auth.uid()
         OR (p_id IS NOT NULL AND public.can_admin_campus(sp.campus_code)))
    AND (p_id IS NULL OR m.id = p_id)
  ORDER BY m.last_activity_at DESC
  LIMIT 200;
$$;

CREATE OR REPLACE FUNCTION public.end_mentorship(p_id uuid, p_action text, p_reason text DEFAULT NULL)
RETURNS public.mentorships
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_row public.mentorships;
  v_me  public.profiles%ROWTYPE;
  v_other uuid;
  v_reason text := NULLIF(btrim(COALESCE(p_reason, '')), '');
  v_is_admin boolean;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF p_action NOT IN ('withdraw', 'end', 'complete') THEN RAISE EXCEPTION 'invalid_input: unknown action'; END IF;
  IF v_reason IS NOT NULL AND char_length(v_reason) > 500 THEN RAISE EXCEPTION 'invalid_input: reason too long (500 characters max)'; END IF;

  SELECT * INTO v_row FROM public.mentorships WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found'; END IF;

  -- The mentee's campus decides (same rule as the mentorship RLS scope); NULL / GLOBAL campus = Super Admin only.
  v_is_admin := public.auth_is_super_admin()
                OR public.can_admin_campus((SELECT p.campus_code FROM public.profiles p WHERE p.id = v_row.student_id));

  IF v_uid NOT IN (v_row.student_id, v_row.mentor_id) AND NOT (v_is_admin AND p_action <> 'withdraw') THEN
    RAISE EXCEPTION 'not_allowed';
  END IF;

  v_other := CASE WHEN v_uid = v_row.student_id THEN v_row.mentor_id ELSE v_row.student_id END;
  SELECT * INTO v_me FROM public.profiles WHERE id = v_uid;

  IF p_action = 'withdraw' THEN
    IF v_uid <> v_row.student_id THEN RAISE EXCEPTION 'not_allowed: only the student can withdraw a request'; END IF;
    IF v_row.status <> 'pending' THEN RAISE EXCEPTION 'wrong_state: only a pending request can be withdrawn'; END IF;
    UPDATE public.mentorships SET status = 'withdrawn', ended_at = now(), ended_by = v_uid, last_activity_at = now(), updated_at = now()
     WHERE id = p_id RETURNING * INTO v_row;
    PERFORM public.mentorship_notify(v_other, v_uid, 'Mentorship request withdrawn',
      format('%s withdrew their mentorship request.', COALESCE(v_me.full_name, 'The student')), '/mentorship/' || p_id::text);
  ELSE
    IF v_row.status <> 'active' THEN RAISE EXCEPTION 'wrong_state: this mentorship is not active'; END IF;
    UPDATE public.mentorships
       SET status = CASE WHEN p_action = 'complete' THEN 'completed' ELSE 'ended' END,
           end_reason = v_reason, ended_at = now(), ended_by = v_uid, last_activity_at = now(), updated_at = now()
     WHERE id = p_id RETURNING * INTO v_row;
    UPDATE public.mentorship_sessions SET status = 'cancelled', updated_at = now()
     WHERE mentorship_id = p_id AND status IN ('proposed', 'confirmed');

    IF v_uid IN (v_row.student_id, v_row.mentor_id) THEN
      PERFORM public.mentorship_notify(v_other, v_uid,
        CASE WHEN p_action = 'complete' THEN 'Mentorship completed' ELSE 'Mentorship ended' END,
        CASE WHEN p_action = 'complete' THEN format('%s marked your mentorship as complete.', COALESCE(v_me.full_name, 'The other person'))
             ELSE format('%s ended your mentorship.', COALESCE(v_me.full_name, 'The other person')) END,
        '/mentorship/' || p_id::text);
    ELSE
      PERFORM public.mentorship_notify(v_row.student_id, v_uid, 'Mentorship ended by campus staff',
        format('Campus staff ended this mentorship.%s', CASE WHEN v_reason IS NOT NULL THEN ' Reason: ' || v_reason ELSE '' END),
        '/mentorship/' || p_id::text);
      PERFORM public.mentorship_notify(v_row.mentor_id, v_uid, 'Mentorship ended by campus staff',
        format('Campus staff ended this mentorship.%s', CASE WHEN v_reason IS NOT NULL THEN ' Reason: ' || v_reason ELSE '' END),
        '/mentorship/' || p_id::text);
    END IF;
  END IF;

  RETURN v_row;
END
$$;

CREATE OR REPLACE FUNCTION public.assign_forum_community_moderator(p_community_id uuid, p_user_id uuid)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_created_by uuid;
  v_campus text;
  v_target_campus text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Only the community owner or an administrator can add moderators'; END IF;
  SELECT fc.created_by, fc.campus_code INTO v_created_by, v_campus FROM public.forum_communities fc WHERE fc.id = p_community_id;
  IF NOT FOUND OR NOT (v_created_by = auth.uid() OR public.can_admin_campus(v_campus)) THEN
    RAISE EXCEPTION 'Only the community owner or an administrator can add moderators';
  END IF;

  SELECT p.campus_code INTO v_target_campus FROM public.profiles p WHERE p.id = p_user_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'The selected user no longer exists'; END IF;
  -- a campus space is moderated by that campus' members (GLOBAL spaces by anyone)
  IF v_campus IS NOT NULL AND v_campus <> 'GLOBAL' AND v_target_campus IS DISTINCT FROM v_campus AND v_target_campus IS DISTINCT FROM 'GLOBAL'
     AND NOT public.auth_is_super_admin() THEN
    RAISE EXCEPTION 'Moderators of a campus space must belong to that campus';
  END IF;

  INSERT INTO public.forum_community_moderators (community_id, user_id, added_by)
  VALUES (p_community_id, p_user_id, auth.uid())
  ON CONFLICT (community_id, user_id) DO NOTHING;
END;
$$;

CREATE OR REPLACE FUNCTION public.unassign_forum_community_moderator(p_community_id uuid, p_user_id uuid)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_created_by uuid;
  v_campus text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Only the community owner or an administrator can remove moderators'; END IF;
  SELECT fc.created_by, fc.campus_code INTO v_created_by, v_campus FROM public.forum_communities fc WHERE fc.id = p_community_id;
  IF NOT FOUND OR NOT (v_created_by = auth.uid() OR public.can_admin_campus(v_campus)) THEN
    RAISE EXCEPTION 'Only the community owner or an administrator can remove moderators';
  END IF;
  DELETE FROM public.forum_community_moderators WHERE community_id = p_community_id AND user_id = p_user_id;
END;
$$;

-- suspend_user_account(): authority comes from can_admin_campus(<target campus>) only. A campus-less / GLOBAL
-- staff member or an admin without a real campus has NO authority (it used to be "GLOBAL staff may moderate
-- everyone" and "NULL = NULL" for admins).
CREATE OR REPLACE FUNCTION public.suspend_user_account(p_target_user_id uuid, p_reason text DEFAULT 'Moderation policy violation')
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_caller uuid := auth.uid();
  v_caller_role text;
  v_caller_admin_role text;
  v_caller_email text;
  v_caller_suspended boolean;
  v_target_role text;
  v_target_admin_role text;
  v_target_campus text;
  v_target_email text;
  v_target_suspended boolean;
  v_reason text;
  v_other_admins int;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Authentication required.' USING ERRCODE = '28000'; END IF;
  IF p_target_user_id IS NULL THEN RAISE EXCEPTION 'Target user is required.'; END IF;
  IF v_caller = p_target_user_id THEN RAISE EXCEPTION 'You cannot suspend your own account.' USING ERRCODE = '42501'; END IF;

  SELECT role::text, admin_role, LOWER(COALESCE(email, '')), COALESCE(is_suspended, false)
    INTO v_caller_role, v_caller_admin_role, v_caller_email, v_caller_suspended
    FROM public.profiles WHERE id = v_caller;

  IF v_caller_role IS NULL OR v_caller_suspended THEN
    RAISE EXCEPTION 'Insufficient permissions to suspend user accounts.' USING ERRCODE = '42501';
  END IF;

  SELECT role::text, admin_role, campus_code, LOWER(COALESCE(email, '')), COALESCE(is_suspended, false)
    INTO v_target_role, v_target_admin_role, v_target_campus, v_target_email, v_target_suspended
    FROM public.profiles WHERE id = p_target_user_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Target user not found.'; END IF;

  IF v_target_email = 'inememmanuel@gmail.com' THEN
    RAISE EXCEPTION 'The primary root administrator cannot be suspended.' USING ERRCODE = '42501';
  END IF;

  IF public.auth_is_super_admin() THEN
    IF v_target_role = 'admin' AND NOT v_target_suspended THEN
      PERFORM pg_advisory_xact_lock(hashtext('lioris.last_active_admin'));
      SELECT count(*) INTO v_other_admins
        FROM public.profiles p
       WHERE p.id <> p_target_user_id AND p.role::text = 'admin' AND NOT COALESCE(p.is_suspended, false);
      IF v_other_admins = 0 THEN
        RAISE EXCEPTION 'Cannot suspend the last active administrator.' USING ERRCODE = '42501';
      END IF;
    END IF;
  ELSIF v_caller_role = 'admin' THEN
    IF v_target_role = 'admin' OR v_target_admin_role = 'super_admin' THEN
      RAISE EXCEPTION 'Campus Admins cannot suspend administrator accounts.' USING ERRCODE = '42501';
    END IF;
    IF NOT public.can_admin_campus(v_target_campus) THEN
      RAISE EXCEPTION 'Campus Admins cannot moderate users outside their registered campus node.' USING ERRCODE = '42501';
    END IF;
  ELSIF v_caller_role = 'staff' THEN
    IF v_target_role NOT IN ('student', 'alumni') THEN
      RAISE EXCEPTION 'Staff cannot suspend admin or staff accounts.' USING ERRCODE = '42501';
    END IF;
    IF NOT public.can_admin_campus(v_target_campus) THEN
      RAISE EXCEPTION 'Staff cannot moderate users outside their registered campus node.' USING ERRCODE = '42501';
    END IF;
  ELSE
    RAISE EXCEPTION 'Insufficient permissions to suspend user accounts.' USING ERRCODE = '42501';
  END IF;

  IF v_target_suspended THEN
    RETURN jsonb_build_object('success', true, 'message', 'User account is already suspended.');
  END IF;

  v_reason := left(COALESCE(NULLIF(btrim(p_reason), ''), 'Moderation policy violation'), 500);

  PERFORM set_config('lioris.audit_skip', 'is_suspended', true);
  UPDATE public.profiles SET is_suspended = true, suspension_reason = v_reason WHERE id = p_target_user_id;
  PERFORM set_config('lioris.audit_skip', '', true);

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  VALUES (v_caller, 'user_suspended', 'user', p_target_user_id,
          jsonb_build_object('summary', 'Account suspended via suspend_user_account()', 'reason', v_reason,
                             'actorRole', v_caller_role, 'targetRole', v_target_role,
                             'targetCampus', v_target_campus, 'source', 'suspend_user_account'));

  RETURN jsonb_build_object(
    'success', true,
    'message', CASE WHEN public.auth_is_super_admin() THEN 'User account permanently suspended by Super Admin.'
                    WHEN v_caller_role = 'admin' THEN 'User account permanently suspended by Campus Admin.'
                    ELSE 'User account suspended by Campus Staff.' END);
END;
$$;

-- admin_delete_chat_message(): Super Admin anywhere; a Campus Admin / staff member ONLY when the sender and
-- every member of the channel belong to their campus (a cross-campus DM is never reachable this way).
CREATE OR REPLACE FUNCTION public.admin_delete_chat_message(p_message_id uuid)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_sender uuid;
  v_channel uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF COALESCE(public.auth_profile_role(), '') NOT IN ('admin', 'staff') THEN
    RAISE EXCEPTION 'not_allowed: moderator-only action';
  END IF;

  SELECT sender_id, channel_id INTO v_sender, v_channel FROM public.chat_messages WHERE id = p_message_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found: message does not exist'; END IF;

  IF NOT public.auth_is_super_admin() THEN
    IF NOT public.can_admin_campus((SELECT p.campus_code FROM public.profiles p WHERE p.id = v_sender))
       OR EXISTS (
         SELECT 1 FROM public.chat_channel_members m
         LEFT JOIN public.profiles p ON p.id = m.user_id
         WHERE m.channel_id = v_channel AND NOT public.can_admin_campus(p.campus_code)
       ) THEN
      RAISE EXCEPTION 'not_allowed: this conversation includes members outside your campus';
    END IF;
  END IF;

  DELETE FROM public.chat_messages WHERE id = p_message_id;
END
$$;

-- ----------------------------------------------------------------------------
-- 11. Takedown abuse
-- ----------------------------------------------------------------------------
-- Any signed-in account could hide any resource instantly by filing an "owner_removal" claim. Now:
--   * the filer must be verified and onboarded;
--   * only the UPLOADER's own removal request takes effect on the spot; everyone else's claim is queued as
--     'pending' for a reviewer and does not change what other people can see;
--   * at most one instant hide per resource per day and 50 instant hides per day platform-wide;
--   * only the admins responsible for the resource's campus (and Super Admins) are alerted.
CREATE OR REPLACE FUNCTION public.submit_takedown_request(
  p_resource_id uuid, p_claim_type text, p_claimant_name text, p_claimant_email text,
  p_claimant_role text, p_details text, p_good_faith boolean
)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_uid         uuid := auth.uid();
  v_res         public.resources%ROWTYPE;
  v_name        text := btrim(coalesce(p_claimant_name, ''));
  v_email       text := btrim(coalesce(p_claimant_email, ''));
  v_details     text := btrim(coalesce(p_details, ''));
  v_rights_claim boolean := p_claim_type IN ('owner_removal', 'agent_removal');
  v_hide        boolean := false;
  v_id          uuid;
  v_admin       uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'You need to be signed in to submit a request.' USING ERRCODE = '28000';
  END IF;
  IF NOT public.is_profile_verified(v_uid)
     OR NOT COALESCE((SELECT p.onboarding_complete FROM public.profiles p WHERE p.id = v_uid), false) THEN
    RAISE EXCEPTION 'Verify your account and finish onboarding before filing a takedown request.' USING ERRCODE = '42501';
  END IF;
  IF p_claim_type NOT IN ('owner_removal', 'agent_removal', 'third_party_copyright', 'inappropriate', 'inaccurate') THEN
    RAISE EXCEPTION 'Unknown request type.' USING ERRCODE = '22023';
  END IF;
  IF char_length(v_name) < 2 OR char_length(v_name) > 120 THEN
    RAISE EXCEPTION 'Please enter your full name.' USING ERRCODE = '22023';
  END IF;
  IF v_email !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' OR char_length(v_email) > 254 THEN
    RAISE EXCEPTION 'Please enter a valid contact email address.' USING ERRCODE = '22023';
  END IF;
  IF char_length(v_details) < 10 OR char_length(v_details) > 2000 THEN
    RAISE EXCEPTION 'Please describe your request in 10 to 2000 characters.' USING ERRCODE = '22023';
  END IF;
  IF p_claim_type IN ('owner_removal', 'agent_removal', 'third_party_copyright') AND p_good_faith IS NOT TRUE THEN
    RAISE EXCEPTION 'You must confirm the statement before submitting a copyright request.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_res FROM public.resources WHERE id = p_resource_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'That resource no longer exists.' USING ERRCODE = 'P0002';
  END IF;

  IF (SELECT count(*) FROM public.resource_takedown_requests
        WHERE reporter_id = v_uid AND created_at > now() - interval '24 hours') >= 10 THEN
    RAISE EXCEPTION 'You have sent too many requests today. Please try again tomorrow.' USING ERRCODE = '54000';
  END IF;
  IF EXISTS (SELECT 1 FROM public.resource_takedown_requests
              WHERE reporter_id = v_uid AND resource_id = p_resource_id AND status = 'pending') THEN
    RAISE EXCEPTION 'You already have a request open for this resource.' USING ERRCODE = '23505';
  END IF;

  -- Instant effect only for the uploader withdrawing their own file, inside the daily caps.
  v_hide := v_rights_claim AND p_good_faith IS TRUE AND v_res.uploader_id IS NOT DISTINCT FROM v_uid
            AND (SELECT count(*) FROM public.resource_takedown_requests
                  WHERE resource_id = v_res.id AND auto_hidden AND created_at > now() - interval '24 hours') < 1
            AND (SELECT count(*) FROM public.resource_takedown_requests
                  WHERE auto_hidden AND created_at > now() - interval '24 hours') < 50;

  INSERT INTO public.resource_takedown_requests
    (resource_id, resource_title, resource_course, resource_uploader, resource_file_url, reporter_id,
     claim_type, claimant_name, claimant_email, claimant_role, details, good_faith, auto_hidden)
  VALUES
    (v_res.id, v_res.title, v_res.course_code, v_res.uploader_id, v_res.file_url, v_uid,
     p_claim_type, v_name, v_email, nullif(btrim(coalesce(p_claimant_role, '')), ''), v_details,
     coalesce(p_good_faith, false), v_hide)
  RETURNING id INTO v_id;

  IF v_hide THEN
    PERFORM set_config('lioris.takedown_action', 'on', true);
    UPDATE public.resources SET is_approved = false, takedown_status = 'disabled' WHERE id = v_res.id;
    PERFORM set_config('lioris.takedown_action', 'off', true);
  END IF;

  FOR v_admin IN
    SELECT p.id FROM public.profiles p
    WHERE p.role = 'admin' AND coalesce(p.is_suspended, false) = false
      AND (p.admin_role = 'super_admin' OR (p.campus_code IS NOT NULL AND p.campus_code = v_res.campus_code))
  LOOP
    INSERT INTO public.notifications (recipient_id, sender_id, title, body, type, action_url, is_read)
    VALUES (v_admin, v_uid,
            CASE WHEN v_hide THEN 'Copyright takedown: resource hidden' ELSE 'New resource report' END,
            '"' || left(v_res.title, 120) || '" - ' || replace(p_claim_type, '_', ' ') || '. Review it in Takedown Requests.',
            'system', '/notifications', false);
  END LOOP;

  RETURN jsonb_build_object('id', v_id, 'auto_hidden', v_hide);
END
$$;

-- record_user_activity(): analytics must not trust a caller-supplied campus (it let anybody pour rows into any
-- campus' dashboard) and is no longer reachable signed-out.
CREATE OR REPLACE FUNCTION public.record_user_activity(
  p_event_type text, p_name text, p_campus_code text DEFAULT NULL, p_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_campus TEXT;
BEGIN
  IF v_uid IS NULL THEN RETURN; END IF;
  SELECT campus_code INTO v_campus FROM public.profiles WHERE id = v_uid;
  IF p_campus_code IS NOT NULL AND p_campus_code <> '' AND public.auth_is_super_admin()
     AND EXISTS (SELECT 1 FROM public.campuses c WHERE c.code = p_campus_code) THEN
    v_campus := p_campus_code;
  END IF;

  INSERT INTO public.analytics_events (user_id, event_type, name, campus_code, metadata, created_at)
  VALUES (v_uid, left(COALESCE(p_event_type, 'event'), 40), left(COALESCE(p_name, ''), 200), COALESCE(v_campus, 'GLOBAL'),
          CASE WHEN pg_column_size(COALESCE(p_metadata, '{}'::jsonb)) > 4000 THEN '{}'::jsonb ELSE COALESCE(p_metadata, '{}'::jsonb) END,
          NOW());

  IF p_event_type = 'session_start' THEN
    UPDATE public.profiles SET last_active_at = NOW(), last_login_at = NOW() WHERE id = v_uid;
  ELSE
    UPDATE public.profiles SET last_active_at = NOW() WHERE id = v_uid;
  END IF;
END;
$$;

-- open_giving_page(): needs a signed-in member, and the campaign must be visible to them.
CREATE OR REPLACE FUNCTION public.open_giving_page(p_campaign uuid)
RETURNS text
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_campaign RECORD;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_available: Sign in to open a giving page.'; END IF;
  IF NOT public.donations_enabled() THEN
    RAISE EXCEPTION 'donations_disabled: Giving is not open yet.';
  END IF;
  SELECT * INTO v_campaign FROM public.giving_campaigns WHERE id = p_campaign;
  IF v_campaign IS NULL OR v_campaign.review_status <> 'approved' OR v_campaign.is_closed
     OR NOT (v_campaign.campus_code IS NULL OR v_campaign.campus_code = 'GLOBAL'
             OR v_campaign.campus_code = public.auth_campus_access()
             OR public.can_admin_campus(v_campaign.campus_code)) THEN
    RAISE EXCEPTION 'not_available: This campaign is not currently accepting gifts.';
  END IF;

  INSERT INTO public.giving_campaign_clicks (campaign_id, user_id) VALUES (p_campaign, auth.uid());
  RETURN v_campaign.giving_url;
END;
$$;

-- ----------------------------------------------------------------------------
-- 6. Counters: forged likes / comments / downloads / upvotes / applications
-- ----------------------------------------------------------------------------
-- The legitimate writers are SECURITY DEFINER triggers / RPCs (they run as the table owner, or nested inside
-- another trigger). A direct client write (role authenticated / anon) is reset to 0 on INSERT and to the old
-- value on UPDATE unless the caller is the service role or a Super Admin.
CREATE OR REPLACE FUNCTION public.guard_counter_columns()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
DECLARE
  c text;
BEGIN
  IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;                       -- nested: a counter-maintenance trigger
  IF current_user NOT IN ('authenticated', 'anon') THEN RETURN NEW; END IF; -- definer RPC / owner / service connection
  IF auth.uid() IS NULL OR COALESCE(auth.role(), '') = 'service_role' THEN RETURN NEW; END IF;
  IF public.auth_is_super_admin() THEN RETURN NEW; END IF;

  FOREACH c IN ARRAY TG_ARGV LOOP
    IF TG_OP = 'INSERT' THEN
      NEW := jsonb_populate_record(NEW, jsonb_build_object(c, 0));
    ELSE
      NEW := jsonb_populate_record(NEW, jsonb_build_object(c, to_jsonb(OLD) -> c));
    END IF;
  END LOOP;
  RETURN NEW;
END;
$$;

DO $cnt$
BEGIN
  IF to_regclass('public.posts') IS NOT NULL THEN
    DROP TRIGGER IF EXISTS trg_guard_counters ON public.posts;
    CREATE TRIGGER trg_guard_counters BEFORE INSERT OR UPDATE ON public.posts
      FOR EACH ROW EXECUTE FUNCTION public.guard_counter_columns('likes_count', 'comments_count');
  END IF;
  IF to_regclass('public.resources') IS NOT NULL THEN
    DROP TRIGGER IF EXISTS trg_guard_counters ON public.resources;
    CREATE TRIGGER trg_guard_counters BEFORE INSERT OR UPDATE ON public.resources
      FOR EACH ROW EXECUTE FUNCTION public.guard_counter_columns('downloads_count', 'upvotes_count');
  END IF;
  IF to_regclass('public.jobs') IS NOT NULL THEN
    DROP TRIGGER IF EXISTS trg_guard_counters ON public.jobs;
    CREATE TRIGGER trg_guard_counters BEFORE INSERT OR UPDATE ON public.jobs
      FOR EACH ROW EXECUTE FUNCTION public.guard_counter_columns('applications_count');
  END IF;
END
$cnt$;

-- ----------------------------------------------------------------------------
-- 5. Campus / visibility immutability + the campus-wall INSERT bypass
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.guard_campus_scope_columns()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
  IF current_user NOT IN ('authenticated', 'anon') THEN RETURN NEW; END IF;   -- definer RPC / owner / service connection
  IF auth.uid() IS NULL OR COALESCE(auth.role(), '') = 'service_role' THEN RETURN NEW; END IF;
  IF public.auth_is_super_admin() THEN RETURN NEW; END IF;

  NEW := jsonb_populate_record(NEW, jsonb_build_object('campus_code', to_jsonb(OLD) -> 'campus_code'));
  IF TG_TABLE_NAME IN ('posts', 'events')
     AND COALESCE(public.auth_profile_role(), '') NOT IN ('admin', 'staff') THEN
    NEW := jsonb_populate_record(NEW, jsonb_build_object('visibility_scope', to_jsonb(OLD) -> 'visibility_scope'));
  END IF;
  RETURN NEW;
END;
$$;

DO $imm$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['posts', 'events', 'marketplace_listings', 'study_groups', 'announcements', 'jobs', 'giving_campaigns'] LOOP
    IF to_regclass('public.' || t) IS NULL THEN CONTINUE; END IF;
    EXECUTE format('DROP TRIGGER IF EXISTS trg_guard_campus_scope ON public.%I', t);
    EXECUTE format('CREATE TRIGGER trg_guard_campus_scope BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_campus_scope_columns()', t);
  END LOOP;
END
$imm$;

-- Permissive INSERT policies are ORed, so a policy without a campus check made the checked one pointless.
DO $ins$
BEGIN
  IF to_regclass('public.posts') IS NOT NULL THEN
    DROP POLICY IF EXISTS "Verified users can create posts" ON public.posts;
    CREATE POLICY "Verified users can create posts" ON public.posts
      FOR INSERT TO authenticated
      WITH CHECK (
        auth.uid() = author_id
        AND public.is_profile_verified(auth.uid())
        AND (
          visibility_scope = 'global'
          OR campus_code IS NULL OR campus_code = 'GLOBAL'
          OR campus_code = public.auth_campus_access()
          OR public.auth_profile_role() IN ('admin', 'staff')
        )
      );
  END IF;

  IF to_regclass('public.marketplace_listings') IS NOT NULL THEN
    DROP POLICY IF EXISTS "Students, staff and admin can create marketplace listings" ON public.marketplace_listings;
    CREATE POLICY "Students, staff and admin can create marketplace listings" ON public.marketplace_listings
      FOR INSERT TO authenticated
      WITH CHECK (
        auth.uid() = seller_id
        AND NOT COALESCE((SELECT p.is_suspended FROM public.profiles p WHERE p.id = auth.uid()), false)
        AND (
          public.auth_profile_role() IN ('admin', 'staff')
          OR (public.auth_profile_role() = 'student'
              AND (campus_code IS NULL OR campus_code = 'GLOBAL' OR campus_code = public.auth_profile_campus()))
        )
      );
    DROP POLICY IF EXISTS "Verified students, staff and admin can create marketplace listings" ON public.marketplace_listings;
    CREATE POLICY "Verified students, staff and admin can create marketplace listings" ON public.marketplace_listings
      FOR INSERT TO authenticated
      WITH CHECK (
        auth.uid() = seller_id
        AND public.is_profile_verified(auth.uid())
        AND EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = auth.uid() AND p.role IN ('student', 'staff', 'admin'))
        AND (
          campus_code IS NULL OR campus_code = 'GLOBAL'
          OR campus_code = public.auth_campus_access()
          OR public.auth_profile_role() IN ('admin', 'staff')
        )
      );
  END IF;

  IF to_regclass('public.study_groups') IS NOT NULL THEN
    DROP POLICY IF EXISTS "Verified users can create study groups" ON public.study_groups;
    CREATE POLICY "Verified users can create study groups" ON public.study_groups
      FOR INSERT TO authenticated
      WITH CHECK (
        auth.uid() = creator_id
        AND public.is_profile_verified(auth.uid())
        AND (
          campus_code IS NULL OR campus_code = 'GLOBAL'
          OR campus_code = public.auth_campus_access()
          OR public.auth_profile_role() IN ('admin', 'staff')
        )
      );
  END IF;

  IF to_regclass('public.events') IS NOT NULL THEN
    DROP POLICY IF EXISTS "Verified users can create events" ON public.events;
    CREATE POLICY "Verified users can create events" ON public.events
      FOR INSERT TO authenticated
      WITH CHECK (
        auth.uid() = creator_id
        AND status = 'pending_approval'
        AND public.is_profile_verified(auth.uid())
        AND (
          campus_code IS NULL OR campus_code = 'GLOBAL'
          OR campus_code = public.auth_campus_access()
          OR public.auth_profile_role() IN ('admin', 'staff')
        )
      );
  END IF;

  IF to_regclass('public.jobs') IS NOT NULL THEN
    DROP POLICY IF EXISTS "Alumni, staff and admin can create jobs" ON public.jobs;
    CREATE POLICY "Alumni, staff and admin can create jobs" ON public.jobs
      FOR INSERT TO authenticated
      WITH CHECK (
        auth.uid() = poster_id
        AND public.is_profile_verified(auth.uid())
        AND public.has_role_permission('can_post_jobs')
        AND EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = auth.uid() AND p.role IN ('alumni', 'staff', 'admin'))
        AND (
          campus_code IS NULL OR campus_code::text = 'GLOBAL'
          OR campus_code::text = public.auth_campus_access()
          OR public.auth_profile_role() IN ('admin', 'staff')
        )
      );
  END IF;

  IF to_regclass('public.giving_campaigns') IS NOT NULL THEN
    DROP POLICY IF EXISTS "A member proposes a giving campaign, held for review" ON public.giving_campaigns;
    CREATE POLICY "A member proposes a giving campaign, held for review" ON public.giving_campaigns
      FOR INSERT TO authenticated
      WITH CHECK (
        auth.uid() = creator_id
        AND public.is_profile_verified(auth.uid())
        AND (
          campus_code IS NULL OR campus_code = 'GLOBAL'
          OR campus_code = public.auth_campus_access()
          OR public.auth_profile_role() IN ('admin', 'staff')
        )
      );
  END IF;
END
$ins$;

-- 20261029 regression: the restrictive UPDATE policy's WITH CHECK accepted "owner = me OR campus = mine", so a
-- scoped admin could move one of their OWN rows to another campus. The new row must now sit on the admin's own
-- campus (USING keeps the owner clause so they can still open and edit their own rows).
DO $upd$
DECLARE
  t text;
  v_owner text;
  v_cols text[];
  c text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'analytics_events', 'announcements', 'events', 'forum_communities', 'giving_campaigns', 'jobs',
    'marketplace_listings', 'portal_links', 'posts', 'study_groups'
  ] LOOP
    IF to_regclass('public.' || t) IS NULL THEN CONTINUE; END IF;
    SELECT array_agg(column_name::text) INTO v_cols FROM information_schema.columns WHERE table_schema = 'public' AND table_name = t;
    IF NOT ('campus_code' = ANY (v_cols)) THEN CONTINUE; END IF;
    v_owner := 'NULL::uuid';
    FOREACH c IN ARRAY ARRAY['author_id', 'creator_id', 'seller_id', 'poster_id', 'uploader_id', 'user_id'] LOOP
      IF c = ANY (v_cols) THEN v_owner := quote_ident(c); EXIT; END IF;
    END LOOP;

    EXECUTE format('DROP POLICY IF EXISTS scope_privileged_update ON public.%I', t);
    EXECUTE format($f$CREATE POLICY scope_privileged_update ON public.%I AS RESTRICTIVE FOR UPDATE TO authenticated
      USING ((SELECT NOT public.is_scoped_privileged()) OR COALESCE(%s = auth.uid(), false) OR campus_code = (SELECT public.auth_profile_campus()))
      WITH CHECK ((SELECT NOT public.is_scoped_privileged()) OR campus_code = (SELECT public.auth_profile_campus()))$f$,
      t, v_owner);
  END LOOP;
END
$upd$;

-- ----------------------------------------------------------------------------
-- 2. Chat, notifications, connections, blocks, mentorships: only a Super Admin keeps the override
-- ----------------------------------------------------------------------------
DO $drop$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM (VALUES
      ('chat_messages',        'Chat messages viewable only by channel members'),
      ('chat_messages',        'Senders and admins can delete messages'),
      ('chat_messages',        'Senders and channel members can update message status'),
      ('chat_channels',        'Admins can manage chat channels'),
      ('chat_channels',        'Users can view channels they belong to'),
      ('chat_channel_members', 'Admins can remove members from chat channels'),
      ('chat_channel_members', 'Channel members viewable by channel participants'),
      ('chat_channel_members', 'Members or admins can add members to channels'),
      ('chat_channel_members', 'chat_channel_members_insert'),
      ('notifications',        'Users can delete own notifications'),
      ('notifications',        'Users can update own notification read state'),
      ('notifications',        'Users can view own notifications'),
      ('notifications',        'notifications_insert_authenticated'),
      ('notifications',        'notifications_insert_checked'),
      ('connections',          'Connections viewable by participants or admin'),
      ('connections',          'Participants can delete connections'),
      ('connections',          'Recipient can respond to connection requests'),
      ('user_blocks',          'Admins have full access to user blocks'),
      ('mentorships',          'Admins manage mentorships'),
      ('mentorships',          'Mentorships viewable by student, mentor, or admin'),
      ('mentorship_feedback',  'mentorship_feedback_select')
    ) AS x(t, pol)
  LOOP
    IF to_regclass('public.' || r.t) IS NOT NULL THEN
      EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', r.pol, r.t);
    END IF;
  END LOOP;
END
$drop$;

DO $chat$
BEGIN
  IF to_regclass('public.chat_messages') IS NOT NULL THEN
    CREATE POLICY "Chat messages viewable only by channel members" ON public.chat_messages
      FOR SELECT TO authenticated USING (public.is_channel_member(channel_id) OR public.auth_is_super_admin());
    CREATE POLICY "Senders and admins can delete messages" ON public.chat_messages
      FOR DELETE TO authenticated USING (auth.uid() = sender_id OR public.auth_is_super_admin());
    CREATE POLICY "Senders and channel members can update message status" ON public.chat_messages
      FOR UPDATE TO authenticated USING (auth.uid() = sender_id OR public.is_channel_member(channel_id) OR public.auth_is_super_admin());
  END IF;
  IF to_regclass('public.chat_channels') IS NOT NULL THEN
    CREATE POLICY "Admins can manage chat channels" ON public.chat_channels
      FOR ALL TO authenticated USING (public.auth_is_super_admin()) WITH CHECK (public.auth_is_super_admin());
    CREATE POLICY "Users can view channels they belong to" ON public.chat_channels
      FOR SELECT TO authenticated USING (public.is_channel_member(id) OR public.auth_is_super_admin());
  END IF;
  IF to_regclass('public.chat_channel_members') IS NOT NULL THEN
    CREATE POLICY "Admins can remove members from chat channels" ON public.chat_channel_members
      FOR DELETE TO authenticated USING (public.auth_is_super_admin());
    CREATE POLICY "Channel members viewable by channel participants" ON public.chat_channel_members
      FOR SELECT TO authenticated
      USING (user_id = auth.uid() OR public.is_channel_member(channel_id) OR public.auth_is_super_admin());
  END IF;
END
$chat$;

-- 8. Forced group membership. ONE insert policy (20261101 and 20261102 each left one, ORed together, and the
--    later one let anybody add themselves to ANY channel by id). Rules, evaluated by a definer helper so the
--    channel row is visible even to a non-member:
--      * nobody can add a user who blocked them / whom they blocked;
--      * you may re-assert your own membership (the client upserts it before sending);
--      * only the channel's CREATOR adds other people; a direct message never holds more than two people;
--        in a group channel the added member must share the creator's campus (or either side is GLOBAL);
--      * self-service joining is limited to system (creator-less) group channels on your own campus / GLOBAL;
--      * Super Admin: unrestricted. A Campus Admin has NO way into a conversation they are not part of.
CREATE OR REPLACE FUNCTION public.can_add_channel_member(p_channel uuid, p_user uuid)
RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_actor_campus text;
  v_target_campus text;
  c record;
  v_members int;
BEGIN
  IF v_actor IS NULL OR p_user IS NULL THEN RETURN false; END IF;
  SELECT p.campus_code INTO v_actor_campus FROM public.profiles p WHERE p.id = v_actor AND NOT COALESCE(p.is_suspended, false);
  IF NOT FOUND THEN RETURN false; END IF;
  IF public.auth_is_super_admin() THEN RETURN true; END IF;

  SELECT ch.id, ch.created_by, COALESCE(ch.is_direct_message, false) AS is_dm, ch.campus_code INTO c
    FROM public.chat_channels ch WHERE ch.id = p_channel;
  IF NOT FOUND THEN RETURN false; END IF;

  IF p_user <> v_actor AND public.users_have_block(v_actor, p_user) THEN RETURN false; END IF;

  IF p_user = v_actor THEN
    IF EXISTS (SELECT 1 FROM public.chat_channel_members m WHERE m.channel_id = p_channel AND m.user_id = v_actor) THEN RETURN true; END IF;
    IF c.created_by = v_actor THEN RETURN true; END IF;
    RETURN NOT c.is_dm AND c.created_by IS NULL
           AND (c.campus_code IS NULL OR c.campus_code = 'GLOBAL' OR c.campus_code = public.auth_campus_access());
  END IF;

  -- adding somebody else: creator only
  IF c.created_by IS DISTINCT FROM v_actor THEN RETURN false; END IF;
  IF EXISTS (SELECT 1 FROM public.chat_channel_members m WHERE m.channel_id = p_channel AND m.user_id = p_user) THEN RETURN true; END IF;

  IF c.is_dm THEN
    SELECT count(*) INTO v_members FROM public.chat_channel_members m WHERE m.channel_id = p_channel;
    RETURN v_members < 2;
  END IF;

  SELECT p.campus_code INTO v_target_campus FROM public.profiles p WHERE p.id = p_user;
  RETURN v_target_campus IS NOT NULL
         AND (v_target_campus = v_actor_campus OR v_target_campus = 'GLOBAL' OR v_actor_campus = 'GLOBAL')
         AND (c.campus_code IS NULL OR c.campus_code = 'GLOBAL' OR c.campus_code = v_target_campus OR v_target_campus = 'GLOBAL');
END;
$$;

DO $cm$
BEGIN
  IF to_regclass('public.chat_channel_members') IS NOT NULL AND to_regclass('public.chat_channels') IS NOT NULL THEN
    CREATE POLICY "chat_channel_members_insert" ON public.chat_channel_members
      FOR INSERT TO authenticated
      WITH CHECK (public.can_add_channel_member(channel_id, user_id));
  END IF;
END
$cm$;

DO $notif$
BEGIN
  IF to_regclass('public.notifications') IS NOT NULL THEN
    CREATE POLICY "Users can view own notifications" ON public.notifications
      FOR SELECT TO authenticated USING (auth.uid() = recipient_id OR public.auth_is_super_admin());
    CREATE POLICY "Users can update own notification read state" ON public.notifications
      FOR UPDATE TO authenticated
      USING (auth.uid() = recipient_id OR public.auth_is_super_admin())
      WITH CHECK (auth.uid() = recipient_id OR public.auth_is_super_admin());
    CREATE POLICY "Users can delete own notifications" ON public.notifications
      FOR DELETE TO authenticated USING (auth.uid() = recipient_id OR public.auth_is_super_admin());
  END IF;
  IF to_regclass('public.connections') IS NOT NULL THEN
    CREATE POLICY "Connections viewable by participants or admin" ON public.connections
      FOR SELECT TO authenticated USING (auth.uid() IN (requester_id, recipient_id) OR public.auth_is_super_admin());
    CREATE POLICY "Participants can delete connections" ON public.connections
      FOR DELETE TO authenticated USING (auth.uid() IN (requester_id, recipient_id) OR public.auth_is_super_admin());
    CREATE POLICY "Recipient can respond to connection requests" ON public.connections
      FOR UPDATE TO authenticated
      USING ((auth.uid() = recipient_id AND status = 'pending') OR public.auth_is_super_admin())
      WITH CHECK ((auth.uid() = recipient_id AND status IN ('accepted', 'declined')) OR public.auth_is_super_admin());
  END IF;
  IF to_regclass('public.user_blocks') IS NOT NULL THEN
    CREATE POLICY "Admins have full access to user blocks" ON public.user_blocks
      FOR ALL TO authenticated USING (public.auth_is_super_admin()) WITH CHECK (public.auth_is_super_admin());
  END IF;
  IF to_regclass('public.mentorships') IS NOT NULL THEN
    CREATE POLICY "Admins manage mentorships" ON public.mentorships
      FOR ALL TO authenticated
      USING (public.auth_is_super_admin() OR public.can_admin_campus(public.campus_of(student_id)))
      WITH CHECK (public.auth_is_super_admin() OR public.can_admin_campus(public.campus_of(student_id)));
    CREATE POLICY "Mentorships viewable by student, mentor, or admin" ON public.mentorships
      FOR SELECT TO authenticated
      USING (auth.uid() = student_id OR auth.uid() = mentor_id OR public.can_admin_campus(public.campus_of(student_id)));
  END IF;
  IF to_regclass('public.mentorship_feedback') IS NOT NULL AND to_regclass('public.mentorships') IS NOT NULL THEN
    CREATE POLICY "mentorship_feedback_select" ON public.mentorship_feedback
      FOR SELECT TO authenticated
      USING (from_user = auth.uid() OR to_user = auth.uid()
             OR EXISTS (SELECT 1 FROM public.mentorships m
                        WHERE m.id = mentorship_feedback.mentorship_id
                          AND public.can_admin_campus(public.campus_of(m.student_id))));
  END IF;
END
$notif$;

-- ----------------------------------------------------------------------------
-- 7. Notification spam / spoofing
-- ----------------------------------------------------------------------------
-- The client really does insert peer notifications itself (connection request / accepted, call invite,
-- "you were mentioned", moderator and admin messages, announcement fan-out), so the table keeps its INSERT
-- policy, but it is now constrained:
--   * sender_id is always the caller (a BEFORE INSERT trigger rewrites it - incl. admins, incl. NULL);
--   * action_url must be a relative in-app path;
--   * students / alumni: type 'message' or 'system', recipients on the same campus (or GLOBAL), or a person
--     they share a chat / connection with, never someone with a block either way; 120 per hour;
--   * admin / staff: recipients on their own campus (or GLOBAL members) only; Super Admin: anyone;
--   * notifications created by SECURITY DEFINER code (triggers, RPCs) are not touched.
CREATE TABLE IF NOT EXISTS public.notification_send_log (
  id         bigserial PRIMARY KEY,
  sender_id  uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_notification_send_log_sender ON public.notification_send_log (sender_id, created_at DESC);
ALTER TABLE public.notification_send_log ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.notification_send_log FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.notification_send_log TO service_role;
-- RLS is on and there is deliberately NO policy: members can "read" the table (no 42501 noise in generic table
-- sweeps) but never see a row. Only the SECURITY DEFINER limiter writes to it.
GRANT SELECT ON public.notification_send_log TO authenticated;

CREATE OR REPLACE FUNCTION public.enforce_notification_rate()
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_role text;
  v_n int;
BEGIN
  IF v_uid IS NULL THEN RETURN; END IF;
  SELECT p.role::text INTO v_role FROM public.profiles p WHERE p.id = v_uid;
  IF v_role IN ('admin', 'staff') THEN RETURN; END IF;     -- announcement fan-out; campus-restricted by the policy
  SELECT count(*) INTO v_n FROM public.notification_send_log WHERE sender_id = v_uid AND created_at > now() - interval '1 hour';
  IF v_n >= 120 THEN
    RAISE EXCEPTION 'Rate limit: too many notifications sent - please wait a while' USING ERRCODE = 'P0001';
  END IF;
  INSERT INTO public.notification_send_log (sender_id) VALUES (v_uid);
  DELETE FROM public.notification_send_log WHERE sender_id = v_uid AND created_at < now() - interval '2 hours';
END;
$$;

CREATE OR REPLACE FUNCTION public.can_insert_notification(p_recipient uuid, p_sender uuid, p_type text, p_url text)
RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_role text;
  v_my_campus text;
  v_rec_campus text;
  v_susp boolean;
BEGIN
  IF pg_trigger_depth() > 0 THEN RETURN true; END IF;          -- written by system trigger code, not by a client
  IF v_uid IS NULL OR p_recipient IS NULL THEN RETURN false; END IF;
  IF p_sender IS NOT NULL AND p_sender <> v_uid THEN RETURN false; END IF;
  IF p_url IS NOT NULL AND NOT (p_url ~ '^/[A-Za-z0-9/_().?=&%#:~@+,-]*$' AND p_url !~ '^//' AND length(p_url) <= 300) THEN
    RETURN false;
  END IF;

  SELECT p.role::text, p.campus_code, COALESCE(p.is_suspended, false) INTO v_role, v_my_campus, v_susp
    FROM public.profiles p WHERE p.id = v_uid;
  IF NOT FOUND OR v_susp THEN RETURN false; END IF;
  SELECT p.campus_code INTO v_rec_campus FROM public.profiles p WHERE p.id = p_recipient;
  IF NOT FOUND THEN RETURN false; END IF;

  IF p_recipient = v_uid THEN RETURN true; END IF;
  IF public.users_have_block(v_uid, p_recipient) THEN RETURN false; END IF;

  IF public.auth_is_super_admin() THEN RETURN true; END IF;

  IF v_role IN ('admin', 'staff') AND v_my_campus IS NOT NULL AND v_my_campus <> 'GLOBAL'
     AND (v_rec_campus = v_my_campus OR v_rec_campus = 'GLOBAL') AND public.admin_aal2_ok() THEN
    RETURN true;
  END IF;

  -- peer notifications
  IF p_type IS NULL OR p_type NOT IN ('message', 'system') THEN RETURN false; END IF;
  IF v_my_campus IS NOT DISTINCT FROM v_rec_campus OR v_my_campus = 'GLOBAL' OR v_rec_campus = 'GLOBAL' THEN RETURN true; END IF;
  RETURN EXISTS (SELECT 1 FROM public.chat_channel_members a JOIN public.chat_channel_members b ON a.channel_id = b.channel_id
                  WHERE a.user_id = v_uid AND b.user_id = p_recipient)
      OR EXISTS (SELECT 1 FROM public.connections c
                  WHERE (c.requester_id = v_uid AND c.recipient_id = p_recipient)
                     OR (c.requester_id = p_recipient AND c.recipient_id = v_uid));
END;
$$;

CREATE OR REPLACE FUNCTION public.notifications_guard_insert()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
  IF pg_trigger_depth() > 1 OR current_user NOT IN ('authenticated', 'anon') OR auth.uid() IS NULL
     OR COALESCE(auth.role(), '') = 'service_role' THEN
    RETURN NEW;
  END IF;
  NEW.sender_id := auth.uid();
  NEW.title := left(NEW.title, 200);
  NEW.body := left(NEW.body, 1000);
  PERFORM public.enforce_notification_rate();
  RETURN NEW;
END;
$$;

DO $nt$
BEGIN
  IF to_regclass('public.notifications') IS NOT NULL THEN
    DROP TRIGGER IF EXISTS trg_rate_limit_notifications ON public.notifications;   -- superseded by the log-based limit
    DROP TRIGGER IF EXISTS trg_notifications_guard_insert ON public.notifications;
    CREATE TRIGGER trg_notifications_guard_insert BEFORE INSERT ON public.notifications
      FOR EACH ROW EXECUTE FUNCTION public.notifications_guard_insert();
    CREATE POLICY "notifications_insert_checked" ON public.notifications
      FOR INSERT TO authenticated
      WITH CHECK (public.can_insert_notification(recipient_id, sender_id, type, action_url));
  END IF;
END
$nt$;

-- ----------------------------------------------------------------------------
-- 4. Job applications: résumé ownership, initial state, open jobs only
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.job_open_for_applications(p_job uuid)
RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.jobs j
    WHERE j.id = p_job AND COALESCE(j.is_closed, false) = false AND (j.expires_at IS NULL OR j.expires_at > now())
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.guard_job_application()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
  IF current_user NOT IN ('authenticated', 'anon') OR auth.uid() IS NULL OR COALESCE(auth.role(), '') = 'service_role' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.resume_url IS NOT NULL AND split_part(NEW.resume_url, '/', 1) IS DISTINCT FROM NEW.applicant_id::text THEN
      RAISE EXCEPTION 'The résumé must be a file in your own folder.' USING ERRCODE = '23514';
    END IF;
    IF NOT public.job_open_for_applications(NEW.job_id) THEN
      RAISE EXCEPTION 'This job is closed or has expired.' USING ERRCODE = '23514';
    END IF;
    NEW.status := 'applied';
    NEW.reviewed_at := NULL;
  ELSE
    -- a reviewer changes the status; nobody re-points an application
    NEW.resume_url := OLD.resume_url;
    NEW.applicant_id := OLD.applicant_id;
    NEW.job_id := OLD.job_id;
  END IF;
  RETURN NEW;
END;
$$;

DO $ja$
BEGIN
  IF to_regclass('public.job_applications') IS NOT NULL AND to_regclass('public.jobs') IS NOT NULL THEN
    DROP TRIGGER IF EXISTS trg_guard_job_application ON public.job_applications;
    CREATE TRIGGER trg_guard_job_application BEFORE INSERT OR UPDATE ON public.job_applications
      FOR EACH ROW EXECUTE FUNCTION public.guard_job_application();
  END IF;
END
$ja$;

-- ----------------------------------------------------------------------------
-- 14. role_permissions: the matrix is for signed-in members
-- ----------------------------------------------------------------------------
DO $rp$
BEGIN
  IF to_regclass('public.role_permissions') IS NOT NULL THEN
    DROP POLICY IF EXISTS "Anyone can read role permissions" ON public.role_permissions;
    CREATE POLICY "Anyone can read role permissions" ON public.role_permissions
      FOR SELECT TO authenticated USING (true);
  END IF;
END
$rp$;

-- ----------------------------------------------------------------------------
-- 9 / 15 + resumes. storage.objects policies (owner of that table required)
-- ----------------------------------------------------------------------------
-- verification_doc_locked(): evidence is frozen once a request referencing it has been decided; it stays editable
-- while a pending request references it, or when no request does.
CREATE OR REPLACE FUNCTION public.verification_doc_locked(p_name text)
RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF auth.uid() IS NULL OR split_part(p_name, '/', 1) <> auth.uid()::text THEN RETURN false; END IF;
  RETURN EXISTS (
           SELECT 1 FROM public.verifications v
           WHERE v.status::text <> 'pending'
             AND (public.media_ref_matches(v.id_card_front_url, p_name)
               OR public.media_ref_matches(v.id_card_back_url, p_name)
               OR public.media_ref_matches(v.selfie_url, p_name)))
     AND NOT EXISTS (
           SELECT 1 FROM public.verifications v
           WHERE v.status::text = 'pending'
             AND (public.media_ref_matches(v.id_card_front_url, p_name)
               OR public.media_ref_matches(v.id_card_back_url, p_name)
               OR public.media_ref_matches(v.selfie_url, p_name)));
END;
$$;

DO $st$
BEGIN
  IF to_regclass('storage.objects') IS NULL THEN RETURN; END IF;

  IF to_regclass('public.verifications') IS NOT NULL THEN
    DROP POLICY IF EXISTS "Users and admins can update their verification documents" ON storage.objects;
    CREATE POLICY "Users and admins can update their verification documents" ON storage.objects
      FOR UPDATE TO authenticated
      USING (bucket_id = 'verifications'
             AND (public.auth_is_super_admin()
                  OR ((storage.foldername(name))[1] = auth.uid()::text AND NOT public.verification_doc_locked(name))));
    DROP POLICY IF EXISTS "Users and admins can delete their verification documents" ON storage.objects;
    CREATE POLICY "Users and admins can delete their verification documents" ON storage.objects
      FOR DELETE TO authenticated
      USING (bucket_id = 'verifications'
             AND (public.auth_is_super_admin()
                  OR ((storage.foldername(name))[1] = auth.uid()::text AND NOT public.verification_doc_locked(name))));
  END IF;

  -- A job poster may open a résumé only when the application that references it belongs to that very folder.
  IF to_regclass('public.job_applications') IS NOT NULL AND to_regclass('public.jobs') IS NOT NULL THEN
    DROP POLICY IF EXISTS "Resumes viewable by owner, the job poster, and admins" ON storage.objects;
    CREATE POLICY "Resumes viewable by owner, the job poster, and admins" ON storage.objects
      FOR SELECT TO authenticated USING (
        bucket_id = 'resumes' AND (
          auth.uid()::text = (storage.foldername(name))[1]
          OR public.auth_is_super_admin()
          OR public.can_admin_object_owner(name)
          OR EXISTS (
            SELECT 1 FROM public.job_applications ja JOIN public.jobs j ON j.id = ja.job_id
            WHERE ja.resume_url = name
              AND ja.applicant_id::text = (storage.foldername(name))[1]
              AND j.poster_id = auth.uid())
        ));
  END IF;

  -- The avatars bucket stays PUBLIC (profile pictures load by URL, which never consulted this policy); only the
  -- anonymous / authenticated LISTING of every member's folder goes away.
  DROP POLICY IF EXISTS "Avatars are publicly viewable" ON storage.objects;
EXCEPTION WHEN insufficient_privilege THEN
  RAISE WARNING 'Not owner of storage.objects: storage policies were NOT changed (checked again below).';
END
$st$;

-- Fail loudly (instead of a warning nobody reads) when the listing policy is still there although this role
-- could have dropped it. A role that genuinely cannot manage storage.objects only gets the warning: re-run
-- this section from the Supabase SQL editor as the owner role.
DO $chk$
DECLARE
  v_owner oid;
  v_can   boolean := false;
BEGIN
  IF to_regclass('storage.objects') IS NULL THEN RETURN; END IF;
  IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage' AND tablename = 'objects' AND policyname = 'Avatars are publicly viewable') THEN
    SELECT relowner INTO v_owner FROM pg_class WHERE oid = 'storage.objects'::regclass;
    v_can := pg_has_role(current_user, v_owner, 'MEMBER') OR (SELECT rolsuper FROM pg_roles WHERE rolname = current_user);
    IF v_can THEN
      RAISE EXCEPTION 'The "Avatars are publicly viewable" listing policy on storage.objects is still present although % can manage that table.', current_user;
    ELSE
      RAISE WARNING 'The "Avatars are publicly viewable" policy is still present: % cannot manage storage.objects. Drop it as the owner role.', current_user;
    END IF;
  END IF;
END
$chk$;

-- ----------------------------------------------------------------------------
-- 13. SECURITY DEFINER functions: pg_temp must be searched LAST (otherwise a caller can plant a pg_temp object
--     that shadows something the function refers to)
-- ----------------------------------------------------------------------------
DO $sp$
DECLARE
  r record;
  v_cfg text;
BEGIN
  FOR r IN
    SELECT p.oid, p.oid::regprocedure AS sig
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace AND n.nspname = 'public'
    WHERE p.prosecdef
      AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.objid = p.oid AND d.deptype = 'e')
  LOOP
    SELECT c INTO v_cfg FROM pg_proc p2, unnest(COALESCE(p2.proconfig, ARRAY[]::text[])) c
     WHERE p2.oid = r.oid AND c LIKE 'search_path=%' LIMIT 1;
    BEGIN
      -- (a definer function with NO search_path setting at all is left alone: it may rely on the extensions schema)
      IF v_cfg IS NOT NULL AND v_cfg !~* 'pg_temp' THEN
        EXECUTE format('ALTER FUNCTION %s SET search_path = %s, pg_temp', r.sig, substr(v_cfg, length('search_path=') + 1));
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'search_path of % not changed: %', r.sig, SQLERRM;
    END;
  END LOOP;
END
$sp$;

-- ----------------------------------------------------------------------------
-- 1. Schema-wide EXECUTE sweep
-- ----------------------------------------------------------------------------
-- Supabase's default privileges give anon (and PUBLIC) EXECUTE on every function created in `public`; REVOKE ... FROM
-- PUBLIC alone never closed that. Each SECURITY DEFINER function runs with its owner's rights, so every one anon could
-- reach was a way in unless it guarded itself against a NULL auth.uid().
--
-- ANON ALLOW-LIST (SECURITY DEFINER functions that must stay callable before sign-in):
--   check_username_available(text)   sign-up form: is this @handle free?  (src/api/auth.ts)
-- Everything else is authenticated / service_role only. The client's other RPCs are all made by signed-in members
-- (checked: src/, app/, supabase/functions/); the policies that apply to anon only use INVOKER helpers
-- (is_secret_setting_key, ...), which stay executable. SECURITY INVOKER (non-definer) functions keep anon access
-- unchanged, because they run with anon's own rights and cannot escalate.
DO $sweep$
DECLARE
  r record;
BEGIN
  -- 1) preserve what signed-in members and the service role can do today (it may have come only through PUBLIC)
  FOR r IN
    SELECT p.oid::regprocedure AS sig, has_function_privilege('authenticated', p.oid, 'EXECUTE') AS auth_ok
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace AND n.nspname = 'public'
    WHERE p.prokind IN ('f', 'p')
      AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.objid = p.oid AND d.deptype = 'e')
  LOOP
    BEGIN
      IF r.auth_ok THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated', r.sig); END IF;
      EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role', r.sig);
    EXCEPTION WHEN insufficient_privilege THEN
      RAISE WARNING 'cannot adjust grants of % (not owner)', r.sig;
    END;
  END LOOP;

  -- 2) remember the invoker-rights functions anon may keep, then close everything for PUBLIC / anon
  CREATE TEMP TABLE _anon_keep ON COMMIT DROP AS
    SELECT p.oid::regprocedure::text AS sig
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace AND n.nspname = 'public'
    WHERE p.prokind = 'f' AND NOT p.prosecdef AND p.prorettype <> 'trigger'::regtype
      AND has_function_privilege('anon', p.oid, 'EXECUTE')
      AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.objid = p.oid AND d.deptype = 'e');

  FOR r IN
    SELECT p.oid::regprocedure AS sig
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace AND n.nspname = 'public'
    WHERE p.prokind IN ('f', 'p')
      AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.objid = p.oid AND d.deptype = 'e')
  LOOP
    BEGIN
      EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon', r.sig);
    EXCEPTION WHEN insufficient_privilege THEN
      RAISE WARNING 'cannot revoke on % (not owner)', r.sig;
    END;
  END LOOP;

  -- 3) re-open the allow-list + the harmless invoker functions
  FOR r IN SELECT sig FROM _anon_keep LOOP
    BEGIN
      EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO anon', r.sig);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'cannot re-grant anon on %: %', r.sig, SQLERRM;
    END;
  END LOOP;
  IF to_regprocedure('public.check_username_available(text)') IS NOT NULL THEN
    GRANT EXECUTE ON FUNCTION public.check_username_available(text) TO anon;
  END IF;

  -- 4) internal helpers nobody should call as an RPC
  IF to_regprocedure('public.promote_event_waitlist(uuid)') IS NOT NULL THEN
    REVOKE ALL ON FUNCTION public.promote_event_waitlist(uuid) FROM authenticated;
  END IF;
END
$sweep$;

-- Functions created from now on: no PUBLIC / anon EXECUTE (authenticated and service_role keep their default grant).
DO $dp$
BEGIN
  -- PUBLIC's built-in EXECUTE default can only be revoked with the non-schema form of the command (the IN SCHEMA
  -- form removes only grants that were added per schema). It applies to functions this role creates from now on.
  ALTER DEFAULT PRIVILEGES REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
  ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC, anon;
  ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT EXECUTE ON FUNCTIONS TO authenticated, service_role;
EXCEPTION WHEN insufficient_privilege THEN
  RAISE WARNING 'default privileges (current role) not changed';
END
$dp$;
DO $dp2$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'supabase_admin') THEN
    EXECUTE 'ALTER DEFAULT PRIVILEGES FOR ROLE supabase_admin REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC';
    EXECUTE 'ALTER DEFAULT PRIVILEGES FOR ROLE supabase_admin IN SCHEMA public REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC, anon';
    EXECUTE 'ALTER DEFAULT PRIVILEGES FOR ROLE supabase_admin IN SCHEMA public GRANT EXECUTE ON FUNCTIONS TO authenticated, service_role';
  END IF;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'default privileges of supabase_admin not changed: %', SQLERRM;
END
$dp2$;

NOTIFY pgrst, 'reload schema';

INSERT INTO public._manual_migration_log (version) VALUES ('20261106000000') ON CONFLICT (version) DO NOTHING;
COMMIT;

-- ########## 20261107000000_data_lifecycle.sql ##########
-- ============================================================================
-- DATA LIFECYCLE, COMPLIANCE & RETENTION (2026-11)
-- ============================================================================
-- Idempotent. Everything is guarded (to_regclass / to_regprocedure / extension checks), so it
-- applies on a database that lacks pg_cron, pg_net or vault, and re-running changes nothing.
--
--   1  Compliance RPCs now live in migrations (they were only in root SQL files):
--      export_my_data, purge_user_data, record_consent, latest_consent,
--      list_expired_verification_documents (+ new clear_verification_document_paths)
--   2  Erasure: audit_logs keep a SHA-256 hash instead of the raw user id; consent evidence
--      survives as an anonymised proof row (public.consent_proofs); non-FK user columns are covered
--   3  Verification document retention matches the REAL evidence path columns
--   4  Retention purge functions + pg_cron jobs (analytics, push tokens, click logs, moderation
--      queue, unread notifications, verification documents)
--   5  analytics_events: no more WITH CHECK (true); record_user_activity is no longer anon
--   6  claim_push_token(): a device that changes hands is re-parented to the new user
--   7  Missing indexes (query paths + FKs that make profile deletion scan whole tables)
--   8  Campus deletion safety: direct DELETE FROM campuses is refused; admin_delete_campus audits
--   9  Realtime publication: each table added separately
--  10  Sign-up trigger survives a duplicate e-mail row; event-cancel fan-out is non-fatal
--  11  connections: one live (pending/accepted) row per unordered pair
--  12  Storage: only onboarded users may upload to the resources / campus-media buckets
--
-- ---------------------------------------------------------------------------
-- RPC CONTRACT for the purge-expired-verification-documents edge function
-- (service_role only, never callable by anon/authenticated):
--
--   list_expired_verification_documents(p_days int DEFAULT 30, p_limit int DEFAULT 500)
--     RETURNS TABLE (bucket text, path text, verification_id uuid)
--     * matches storage.objects.name (bucket 'verifications') against the evidence columns
--       verifications.id_card_front_url / id_card_back_url / selfie_url (bare path, leading slash,
--       'verifications/' prefix and legacy signed/public URLs are all normalised) and against the
--       legacy '<uid>/<verifications.id>.<ext>' naming;
--     * returns documents of requests DECIDED (approved/rejected) more than p_days ago, plus
--       unreferenced objects older than p_days whose owner has no pending request (orphans:
--       deleted accounts, abandoned uploads). verification_id is NULL for orphans;
--     * p_limit is clamped to 1..5000; the call is idempotent, so run it until it returns 0 rows.
--   clear_verification_document_paths(p_ids uuid[]) RETURNS integer
--     * after the Storage API has deleted the objects, send the NON-NULL verification_id values
--       back; the three path columns of those DECIDED requests are set to NULL (pending
--       requests are never touched). Returns the number of rows cleared.
--   Edge function flow: rpc list -> storage.remove(paths) -> rpc clear(ids of removed rows).
--
-- Cron (section 4) calls the edge function through pg_net with two Vault secrets:
--   select vault.create_secret('https://<project-ref>.supabase.co', 'lioris_project_url');
--   select vault.create_secret('<same value as the CRON_SECRET function secret>', 'lioris_cron_secret');
--   select public.schedule_verification_document_purge();   -- (re)schedules the job
-- ---------------------------------------------------------------------------

BEGIN;
DO $chain$ BEGIN IF NOT EXISTS (SELECT 1 FROM public._manual_migration_log WHERE version = '20261106000000') THEN RAISE EXCEPTION 'Stopped: migration 20261106000000 has not been applied. Fix it and re-run this whole file.'; END IF; END $chain$;

-- ============================================================================
-- 1a. consent_records (root file only so far) + anonymised proof archive
-- ============================================================================
DO $do$
BEGIN
  IF to_regclass('public.consent_records') IS NULL THEN
    CREATE TABLE public.consent_records (
      id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
      user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
      consent_type text NOT NULL,
      version text NOT NULL,
      accepted_at timestamptz NOT NULL DEFAULT now(),
      age_confirmed_18 boolean NOT NULL DEFAULT false,
      source text NOT NULL DEFAULT 'signup',
      created_at timestamptz NOT NULL DEFAULT now()
    );
    CREATE INDEX IF NOT EXISTS idx_consent_records_user ON public.consent_records(user_id);
    ALTER TABLE public.consent_records ENABLE ROW LEVEL SECURITY;
    CREATE POLICY "Users can view own consent records" ON public.consent_records
      FOR SELECT TO authenticated USING (user_id = auth.uid());
    CREATE POLICY "Users can record own consent" ON public.consent_records
      FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid());
    REVOKE ALL ON public.consent_records FROM PUBLIC, anon;
    REVOKE UPDATE, DELETE, TRUNCATE ON public.consent_records FROM authenticated;
    GRANT SELECT, INSERT ON public.consent_records TO authenticated;
    GRANT ALL ON public.consent_records TO service_role;
  END IF;
END
$do$;

-- Erasure deletes consent_records (ON DELETE CASCADE). The legal evidence "this person accepted
-- version X at time T" is kept as a row that cannot be traced back to the person without the
-- original id: {sha256(user id), consent_type, version, accepted_at}. Retention of these proofs
-- is a policy decision (see docs/compliance); they hold no direct identifier.
CREATE TABLE IF NOT EXISTS public.consent_proofs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_hash text NOT NULL CHECK (user_hash ~ '^[0-9a-f]{64}$'),
  consent_type text NOT NULL,
  version text NOT NULL,
  accepted_at timestamptz NOT NULL,
  archived_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_hash, consent_type, version, accepted_at)
);
ALTER TABLE public.consent_proofs ENABLE ROW LEVEL SECURITY;
-- RLS with NO policy: clients can run SELECT (no "permission denied" noise for generic table
-- scans) but always see zero rows; only service_role (BYPASSRLS) reads or writes.
REVOKE ALL ON public.consent_proofs FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.consent_proofs TO authenticated;
GRANT SELECT, INSERT ON public.consent_proofs TO service_role;

-- ============================================================================
-- 1b. consent RPCs (copied from supabase_launch_hardening_2026.sql section 5)
-- ============================================================================
CREATE OR REPLACE FUNCTION public.latest_consent(p_type text DEFAULT 'terms_and_privacy')
RETURNS text
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT c.version
    FROM public.consent_records c
   WHERE c.user_id = auth.uid()
     AND c.consent_type = COALESCE(p_type, 'terms_and_privacy')
   ORDER BY c.accepted_at DESC, c.created_at DESC
   LIMIT 1
$$;

CREATE OR REPLACE FUNCTION public.record_consent(p_version text, p_age_confirmed boolean DEFAULT true)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required.' USING ERRCODE = '28000';
  END IF;
  IF p_version IS NULL OR p_version !~ '^[A-Za-z0-9._-]{1,64}$' THEN
    RAISE EXCEPTION 'Invalid consent version.' USING ERRCODE = '22023';
  END IF;
  IF p_age_confirmed IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'Age confirmation is required.' USING ERRCODE = '22023';
  END IF;
  -- clock_timestamp() (not now()) keeps 'most recent' well-ordered even when two
  -- acceptances happen inside one transaction.
  -- Abuse guard: consent is a once-per-version event; 20 rows/day is plenty.
  IF (SELECT count(*) FROM public.consent_records
       WHERE user_id = v_uid AND created_at > now() - interval '1 day') >= 20 THEN
    RAISE EXCEPTION 'Rate limit: too many consent submissions - please wait a few minutes'
      USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.consent_records (user_id, consent_type, version, accepted_at, age_confirmed_18, source)
  VALUES (v_uid, 'terms_and_privacy', p_version, clock_timestamp(), true, 'reconsent');
END
$$;

-- Supabase grants EXECUTE on new functions to anon explicitly, so anon must be revoked by name.
REVOKE ALL ON FUNCTION public.latest_consent(text)          FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.record_consent(text, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.latest_consent(text)          TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.record_consent(text, boolean) TO authenticated, service_role;

-- ============================================================================
-- 1c. export_my_data (copied from supabase_security_hardening_2026.sql section 11c)
-- ============================================================================
-- (c) export_my_data(): everything that belongs to the caller.
--     Tables/columns are discovered from foreign keys pointing at profiles /
--     auth.users, so tables added later are covered too:
--       * every ON DELETE CASCADE ownership column (posts.author_id, ...),
--         except user_blocks.blocked_id (other people's blocks against you);
--       * plus moderation_queue.reporter_id, forum_communities.created_by,
--         chat_channels.created_by (SET NULL ownership columns).
--     Never included: rows only linked via reviewed_by/approved_by/sender_id
--     etc. (other people's data), verification document URLs, internal
--     support_tickets.admin_notes, chat messages written by other people.
CREATE OR REPLACE FUNCTION public.export_my_data()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_data jsonb := '{}'::jsonb;
  v_truncated jsonb := '{}'::jsonb;
  v_rows jsonb;
  v_where text;
  v_strip text[];
  v_cnt bigint;
  r record;
  c_cap constant int := 20000;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required.' USING ERRCODE = '28000';
  END IF;

  FOR r IN
    SELECT cl.relname::text AS tbl,
           array_agg(DISTINCT a.attname::text ORDER BY a.attname::text) AS cols
      FROM pg_constraint c
      JOIN pg_class cl ON cl.oid = c.conrelid AND cl.relkind = 'r'
      JOIN pg_namespace n ON n.oid = cl.relnamespace AND n.nspname = 'public'
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = c.conkey[1]
     WHERE c.contype = 'f'
       AND array_length(c.conkey, 1) = 1
       AND c.confrelid IN ('public.profiles'::regclass, 'auth.users'::regclass)
       AND cl.relname <> 'audit_logs'
       AND (
            (c.confdeltype = 'c' AND NOT (cl.relname = 'user_blocks' AND a.attname = 'blocked_id'))
         OR (cl.relname = 'moderation_queue' AND a.attname = 'reporter_id')
         OR (cl.relname = 'forum_communities' AND a.attname = 'created_by')
         OR (cl.relname = 'chat_channels' AND a.attname = 'created_by')
       )
     GROUP BY cl.relname
     ORDER BY cl.relname
  LOOP
    SELECT string_agg(format('%I = $1', col), ' OR ') INTO v_where FROM unnest(r.cols) AS col;
    v_strip := CASE r.tbl
      WHEN 'verifications' THEN ARRAY['id_card_front_url', 'id_card_back_url', 'selfie_url', 'reviewed_by']
      WHEN 'support_tickets' THEN ARRAY['admin_notes', 'resolved_by']
      ELSE ARRAY[]::text[]
    END;

    EXECUTE format('SELECT count(*) FROM public.%I WHERE %s', r.tbl, v_where) INTO v_cnt USING v_uid;
    EXECUTE format(
      'SELECT COALESCE(jsonb_agg(to_jsonb(t) - $2), ''[]''::jsonb) FROM (SELECT * FROM public.%I WHERE %s LIMIT %s) t',
      r.tbl, v_where, c_cap)
      INTO v_rows USING v_uid, v_strip;

    v_data := v_data || jsonb_build_object(r.tbl, v_rows);
    IF v_cnt > c_cap THEN
      v_truncated := v_truncated || jsonb_build_object(r.tbl, v_cnt);
    END IF;
  END LOOP;

  -- Actions the user performed (admin/staff) and actions taken on the account.
  v_data := v_data || jsonb_build_object(
    'audit_logs_performed_by_you',
    COALESCE((SELECT jsonb_agg(jsonb_build_object('action', a.action, 'entity_type', a.entity_type,
                                                  'entity_id', a.entity_id, 'created_at', a.created_at)
                               ORDER BY a.created_at DESC)
                FROM (SELECT * FROM public.audit_logs WHERE actor_id = v_uid
                       ORDER BY created_at DESC LIMIT 5000) a), '[]'::jsonb),
    'audit_logs_about_your_account',
    COALESCE((SELECT jsonb_agg(jsonb_build_object('action', a.action, 'created_at', a.created_at)
                               ORDER BY a.created_at DESC)
                FROM (SELECT * FROM public.audit_logs
                       WHERE entity_id = v_uid AND actor_id IS DISTINCT FROM v_uid
                       ORDER BY created_at DESC LIMIT 5000) a), '[]'::jsonb)
  );

  -- Uploaded files: metadata only (paths, sizes), never content.
  BEGIN
    IF to_regclass('storage.objects') IS NOT NULL THEN
      EXECUTE $q$
        SELECT COALESCE(jsonb_agg(jsonb_build_object(
                 'bucket', o.bucket_id, 'path', o.name,
                 'size_bytes', o.metadata->>'size', 'mime_type', o.metadata->>'mimetype',
                 'created_at', o.created_at)), '[]'::jsonb)
          FROM (SELECT * FROM storage.objects
                 WHERE (storage.foldername(name))[1] = $1::text LIMIT 20000) o
      $q$ INTO v_rows USING v_uid;
      v_data := v_data || jsonb_build_object('storage_objects', v_rows);
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_data := v_data || jsonb_build_object('storage_objects', '[]'::jsonb);
  END;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  VALUES (v_uid, 'data_export_requested', 'user', v_uid,
          jsonb_build_object('summary', 'User exported their personal data', 'source', 'export_my_data'));

  RETURN jsonb_build_object(
    'schema_version', 1,
    'exported_at', now(),
    'user_id', v_uid,
    'data', v_data,
    'truncated_tables', v_truncated
  );
END
$$;

REVOKE ALL ON FUNCTION public.export_my_data() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.export_my_data() TO authenticated;

-- ============================================================================
-- 2. audit_logs: controlled anonymisation + purge_user_data
-- ============================================================================
-- audit_logs is append-only for everybody. Erasure needs ONE narrow exception: a SECURITY DEFINER
-- function (current_user is the owner, never anon/authenticated/service_role) may, inside a
-- transaction that set lioris.audit_anonymise = 'on', change ONLY actor_id (to NULL), entity_id
-- (to NULL) and metadata. Every other column must stay identical.
CREATE OR REPLACE FUNCTION public.audit_logs_block_mutation()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF pg_trigger_depth() > 1
       AND OLD.actor_id IS NOT NULL
       AND NEW.actor_id IS NULL
       AND (to_jsonb(NEW) - 'actor_id') = (to_jsonb(OLD) - 'actor_id') THEN
      RETURN NEW;
    END IF;
    IF current_setting('lioris.audit_anonymise', true) = 'on'
       AND current_user NOT IN ('anon', 'authenticated', 'service_role', 'authenticator')
       AND (NEW.actor_id IS NULL OR NEW.actor_id IS NOT DISTINCT FROM OLD.actor_id)
       AND (NEW.entity_id IS NULL OR NEW.entity_id IS NOT DISTINCT FROM OLD.entity_id)
       AND (to_jsonb(NEW) - 'actor_id' - 'entity_id' - 'metadata')
         = (to_jsonb(OLD) - 'actor_id' - 'entity_id' - 'metadata') THEN
      RETURN NEW;
    END IF;
  END IF;
  RAISE EXCEPTION 'audit_logs is append-only (% refused)', TG_OP USING ERRCODE = '42501';
END
$$;

-- purge_user_data(): erasure of everything owned by a user (service_role only).
--   Order used by the delete-account edge functions: 1) this RPC  2) delete storage objects under
--   '<uid>/' in every user bucket (Storage API)  3) auth.admin.deleteUser(uid).
--   * every FK to profiles / auth.users is discovered at run time: ON DELETE CASCADE rows are
--     deleted, ON DELETE SET NULL columns are nulled (analytics_events, giving_campaign_clicks,
--     moderation_queue.reporter_id, ...); restrictive FKs are reported in skipped_restrictive_fks;
--   * non-FK user columns (client_errors.user_id, resource_takedown_requests.resource_uploader)
--     are nulled explicitly;
--   * consent_records are archived as hash-only rows in consent_proofs before they are deleted;
--   * audit_logs rows are KEPT but anonymised: actor_id / entity_id are cleared and the user id
--     (and the actor's display name) in them is replaced by sha256(user id) in metadata;
--   * the purge's own audit row stores the hash, never the raw id.
CREATE OR REPLACE FUNCTION public.purge_user_data(p_user_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  r record;
  v_n bigint;
  v_role text;
  v_email text;
  v_hash text;
  v_deleted jsonb := '{}'::jsonb;
  v_anonymised jsonb := '{}'::jsonb;
  v_skipped jsonb := '[]'::jsonb;
  v_sets text[] := ARRAY[]::text[];
  v_col text;
  v_audit_n bigint := 0;
  v_proofs bigint := 0;
  v_uuid text;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id is required.';
  END IF;
  v_uuid := p_user_id::text;
  v_hash := encode(sha256(convert_to(v_uuid, 'UTF8')), 'hex');

  SELECT role::text, email INTO v_role, v_email FROM public.profiles WHERE id = p_user_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('user_id', p_user_id, 'profile_found', false,
                              'deleted', v_deleted, 'anonymised', v_anonymised,
                              'storage_prefix', v_uuid || '/');
  END IF;
  IF v_role = 'admin' THEN
    RAISE EXCEPTION 'Admin accounts cannot be purged; demote the account first.' USING ERRCODE = '42501';
  END IF;

  -- Consent evidence first: it is deleted by the generic loop below.
  IF to_regclass('public.consent_records') IS NOT NULL AND to_regclass('public.consent_proofs') IS NOT NULL THEN
    INSERT INTO public.consent_proofs (user_hash, consent_type, version, accepted_at)
    SELECT DISTINCT v_hash, c.consent_type, c.version, c.accepted_at
      FROM public.consent_records c WHERE c.user_id = p_user_id
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_proofs = ROW_COUNT;
  END IF;

  FOR r IN
    SELECT DISTINCT cl.relname::text AS tbl, a.attname::text AS col, c.confdeltype AS del
      FROM pg_constraint c
      JOIN pg_class cl ON cl.oid = c.conrelid AND cl.relkind = 'r'
      JOIN pg_namespace n ON n.oid = cl.relnamespace AND n.nspname = 'public'
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = c.conkey[1]
     WHERE c.contype = 'f'
       AND array_length(c.conkey, 1) = 1
       AND c.confrelid IN ('public.profiles'::regclass, 'auth.users'::regclass)
       AND cl.relname NOT IN ('audit_logs', 'profiles')
     ORDER BY 1, 2
  LOOP
    IF r.del = 'c' THEN
      EXECUTE format('DELETE FROM public.%I WHERE %I = $1', r.tbl, r.col) USING p_user_id;
      GET DIAGNOSTICS v_n = ROW_COUNT;
      IF v_n > 0 THEN v_deleted := v_deleted || jsonb_build_object(r.tbl || '.' || r.col, v_n); END IF;
    ELSIF r.del = 'n' THEN
      EXECUTE format('UPDATE public.%I SET %I = NULL WHERE %I = $1', r.tbl, r.col, r.col) USING p_user_id;
      GET DIAGNOSTICS v_n = ROW_COUNT;
      IF v_n > 0 THEN v_anonymised := v_anonymised || jsonb_build_object(r.tbl || '.' || r.col, v_n); END IF;
    ELSE
      v_skipped := v_skipped || to_jsonb(r.tbl || '.' || r.col);
    END IF;
  END LOOP;

  -- User columns with no foreign key (nothing cascades them).
  FOR r IN
    SELECT t.tbl, t.col FROM (VALUES
      ('client_errors', 'user_id'),
      ('resource_takedown_requests', 'resource_uploader')
    ) AS t(tbl, col)
  LOOP
    IF EXISTS (SELECT 1 FROM information_schema.columns c
                WHERE c.table_schema = 'public' AND c.table_name = r.tbl
                  AND c.column_name = r.col AND c.is_nullable = 'YES') THEN
      EXECUTE format('UPDATE public.%I SET %I = NULL WHERE %I = $1', r.tbl, r.col, r.col) USING p_user_id;
      GET DIAGNOSTICS v_n = ROW_COUNT;
      IF v_n > 0 THEN v_anonymised := v_anonymised || jsonb_build_object(r.tbl || '.' || r.col, v_n); END IF;
    END IF;
  END LOOP;

  -- Rows keyed by e-mail instead of user id.
  IF v_email IS NOT NULL THEN
    IF to_regclass('public.waitlist_entries') IS NOT NULL THEN
      DELETE FROM public.waitlist_entries WHERE lower(email) = lower(v_email);
      GET DIAGNOSTICS v_n = ROW_COUNT;
      IF v_n > 0 THEN v_deleted := v_deleted || jsonb_build_object('waitlist_entries.email', v_n); END IF;
    END IF;
    IF to_regclass('public.auth_rate_limits') IS NOT NULL THEN
      DELETE FROM public.auth_rate_limits WHERE identifier = lower(btrim(v_email));
    END IF;
  END IF;

  -- Anonymise the profile row (removed for good by auth.admin.deleteUser).
  FOR v_col IN
    SELECT c.column_name
      FROM information_schema.columns c
     WHERE c.table_schema = 'public' AND c.table_name = 'profiles' AND c.is_nullable = 'YES'
       AND c.column_name = ANY (ARRAY['username', 'bio', 'avatar_url', 'banner_url', 'student_id_number',
                                      'push_token', 'department', 'faculty', 'level', 'matric_number',
                                      'phone', 'phone_number', 'website', 'website_url', 'linkedin_url',
                                      'github_url', 'twitter_url', 'portfolio_url', 'resume_url',
                                      'company', 'job_title', 'location', 'industry', 'graduation_year',
                                      'suspension_reason'])
  LOOP
    v_sets := v_sets || format('%I = NULL', v_col);
  END LOOP;
  EXECUTE format(
    'UPDATE public.profiles SET email = %L, full_name = %L, interests = ''{}''%s WHERE id = $1',
    'deleted+' || v_uuid || '@deleted.invalid', 'Deleted user',
    CASE WHEN array_length(v_sets, 1) IS NULL THEN '' ELSE ', ' || array_to_string(v_sets, ', ') END)
    USING p_user_id;

  -- audit_logs: keep the trail, drop the identity. Done AFTER the profile update so the rows the
  -- profile triggers just wrote are covered too.
  PERFORM set_config('lioris.audit_anonymise', 'on', true);
  UPDATE public.audit_logs a
     SET actor_id = CASE WHEN a.actor_id = p_user_id THEN NULL ELSE a.actor_id END,
         entity_id = CASE WHEN a.entity_id = p_user_id THEN NULL ELSE a.entity_id END,
         metadata = CASE
           WHEN a.metadata IS NULL THEN NULL
           WHEN jsonb_typeof(a.metadata) = 'object' THEN
             regexp_replace(a.metadata::text, v_uuid, v_hash, 'gi')::jsonb
             || CASE WHEN a.actor_id = p_user_id THEN jsonb_build_object('actorIdHash', v_hash) ELSE '{}'::jsonb END
             || CASE WHEN a.entity_id = p_user_id THEN jsonb_build_object('entityIdHash', v_hash) ELSE '{}'::jsonb END
             || CASE WHEN a.actor_id = p_user_id AND a.metadata ? 'actorName'
                     THEN jsonb_build_object('actorName', 'Deleted user') ELSE '{}'::jsonb END
           ELSE regexp_replace(a.metadata::text, v_uuid, v_hash, 'gi')::jsonb
         END
   WHERE a.actor_id = p_user_id
      OR a.entity_id = p_user_id
      OR a.metadata::text ILIKE '%' || v_uuid || '%';
  GET DIAGNOSTICS v_audit_n = ROW_COUNT;
  PERFORM set_config('lioris.audit_anonymise', 'off', true);

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  VALUES (NULL, 'user_data_purged', 'user', NULL,
          jsonb_build_object('deletedUserIdHash', v_hash, 'deleted', v_deleted, 'anonymised', v_anonymised,
                             'auditRowsAnonymised', v_audit_n, 'consentProofsArchived', v_proofs,
                             'source', 'purge_user_data'));

  RETURN jsonb_build_object(
    'user_id', p_user_id,
    'user_id_hash', v_hash,
    'profile_found', true,
    'purged_at', now(),
    'deleted', v_deleted,
    'anonymised', v_anonymised,
    'skipped_restrictive_fks', v_skipped,
    'audit_rows_anonymised', v_audit_n,
    'consent_proofs_archived', v_proofs,
    'profile_anonymised', true,
    'storage_prefix', v_uuid || '/',
    'note', 'Storage objects are NOT touched; delete them via the Storage API, then call auth.admin.deleteUser.'
  );
END
$$;

REVOKE ALL ON FUNCTION public.purge_user_data(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.purge_user_data(uuid) TO service_role;

-- ============================================================================
-- 3. Verification-document retention
-- ============================================================================
-- submit_verification_request() generates its own request id and the client uploads to
-- '<uid>/<client uuid>.<ext>', so the storage file name never equalled verifications.id and the
-- old listing returned nothing. Match on the stored evidence paths instead.
DO $do$
BEGIN
  IF to_regclass('public.verifications') IS NOT NULL
     AND EXISTS (SELECT 1 FROM information_schema.columns
                  WHERE table_schema = 'public' AND table_name = 'verifications'
                    AND column_name = 'id_card_front_url' AND is_nullable = 'NO') THEN
    -- Needed so the path can be cleared after the file is deleted (metadata-only change).
    ALTER TABLE public.verifications ALTER COLUMN id_card_front_url DROP NOT NULL;
  END IF;
END
$do$;

-- Normalises whatever is stored in an evidence column to a storage object name.
CREATE OR REPLACE FUNCTION public.verification_object_name(p text)
RETURNS text
LANGUAGE sql
IMMUTABLE
SET search_path = pg_catalog
AS $$
  SELECT NULLIF(
    CASE
      WHEN p IS NULL THEN NULL
      WHEN btrim(p) ~* '^https?://' THEN regexp_replace(split_part(btrim(p), '?', 1), '^.*/verifications/', '')
      ELSE regexp_replace(regexp_replace(btrim(p), '^/+', ''), '^verifications/', '')
    END, '')
$$;
REVOKE ALL ON FUNCTION public.verification_object_name(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.verification_object_name(text) TO service_role;

DROP FUNCTION IF EXISTS public.list_expired_verification_documents(integer);
CREATE OR REPLACE FUNCTION public.list_expired_verification_documents(p_days int DEFAULT 30, p_limit int DEFAULT 500)
RETURNS TABLE (bucket text, path text, verification_id uuid)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_cutoff timestamptz := now() - make_interval(days => GREATEST(COALESCE(p_days, 30), 1));
  v_limit int := LEAST(GREATEST(COALESCE(p_limit, 500), 1), 5000);
BEGIN
  RETURN QUERY
  WITH refs AS (
    SELECT v.id, v.user_id, v.status::text AS status,
           COALESCE(v.reviewed_at, v.created_at) AS decided_at,
           public.verification_object_name(c.p) AS obj
      FROM public.verifications v
      CROSS JOIN LATERAL (VALUES (v.id_card_front_url), (v.id_card_back_url), (v.selfie_url)) AS c(p)
     WHERE c.p IS NOT NULL
  ),
  objs AS (
    SELECT o.name::text AS name, o.created_at, (storage.foldername(o.name))[1] AS owner_dir
      FROM storage.objects o
     WHERE o.bucket_id = 'verifications'
       AND (storage.foldername(o.name))[1] IS NOT NULL
  ),
  hits AS (
    -- (1) evidence path of a decided request older than the window
    SELECT ob.name, ob.created_at, r.id AS vid
      FROM objs ob JOIN refs r ON r.obj = ob.name
     WHERE r.status IN ('approved', 'rejected') AND r.decided_at < v_cutoff
    UNION
    -- (2) legacy naming '<uid>/<verifications.id>.<ext>' of a decided request
    SELECT ob.name, ob.created_at, v.id
      FROM objs ob
      JOIN public.verifications v
        ON v.user_id::text = ob.owner_dir
       AND split_part(storage.filename(ob.name), '.', 1) = v.id::text
     WHERE v.status::text IN ('approved', 'rejected')
       AND COALESCE(v.reviewed_at, v.created_at) < v_cutoff
    UNION
    -- (3) orphans: referenced by no request, old enough, and the owner has nothing pending
    SELECT ob.name, ob.created_at, NULL::uuid
      FROM objs ob
     WHERE ob.created_at < v_cutoff
       AND NOT EXISTS (SELECT 1 FROM refs r WHERE r.obj = ob.name)
       AND NOT EXISTS (SELECT 1 FROM public.verifications v
                        WHERE split_part(storage.filename(ob.name), '.', 1) = v.id::text
                          AND v.user_id::text = ob.owner_dir)
       AND NOT EXISTS (SELECT 1 FROM public.verifications v
                        WHERE v.user_id::text = ob.owner_dir AND v.status::text = 'pending')
  )
  SELECT DISTINCT ON (h.name) 'verifications'::text, h.name, h.vid
    FROM hits h
   ORDER BY h.name, h.vid NULLS LAST
   LIMIT v_limit;
END
$$;

REVOKE ALL ON FUNCTION public.list_expired_verification_documents(int, int) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.list_expired_verification_documents(int, int) TO service_role;

-- Call after the Storage API removed the objects: forgets the paths of DECIDED requests.
CREATE OR REPLACE FUNCTION public.clear_verification_document_paths(p_ids uuid[])
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_n integer;
BEGIN
  IF p_ids IS NULL OR cardinality(p_ids) = 0 THEN RETURN 0; END IF;
  UPDATE public.verifications
     SET id_card_front_url = NULL, id_card_back_url = NULL, selfie_url = NULL
   WHERE id = ANY (p_ids)
     AND status::text IN ('approved', 'rejected');
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END
$$;

REVOKE ALL ON FUNCTION public.clear_verification_document_paths(uuid[]) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.clear_verification_document_paths(uuid[]) TO service_role;

-- ============================================================================
-- 4. Retention purge functions and cron jobs
-- ============================================================================
-- Each function deletes at most 100000 rows per call (short locks, WAL stays small); the daily job
-- simply catches up over several days after a backlog. All are service_role only and are no-ops
-- when the table or column does not exist.
CREATE OR REPLACE FUNCTION public.log_retention_purge(p_job text, p_deleted bigint, p_detail jsonb DEFAULT '{}'::jsonb)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF COALESCE(p_deleted, 0) > 0 THEN
    INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
    VALUES (NULL, 'retention_purge', 'system', NULL,
            jsonb_build_object('job', p_job, 'deleted', p_deleted, 'source', 'retention_job') || COALESCE(p_detail, '{}'::jsonb));
  END IF;
EXCEPTION WHEN OTHERS THEN
  NULL;  -- logging must never make a purge fail
END
$$;
REVOKE ALL ON FUNCTION public.log_retention_purge(text, bigint, jsonb) FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.purge_old_analytics(p_days integer DEFAULT 90)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_n bigint := 0;
BEGIN
  IF to_regclass('public.analytics_events') IS NULL THEN RETURN 0; END IF;
  WITH d AS (
    SELECT ctid FROM public.analytics_events
     WHERE created_at < now() - make_interval(days => GREATEST(COALESCE(p_days, 90), 1))
     LIMIT 100000
  )
  DELETE FROM public.analytics_events a USING d WHERE a.ctid = d.ctid;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  PERFORM public.log_retention_purge('purge_old_analytics', v_n, jsonb_build_object('older_than_days', p_days));
  RETURN v_n;
END
$$;

CREATE OR REPLACE FUNCTION public.purge_stale_push_tokens(p_days integer DEFAULT 120)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_n bigint := 0;
BEGIN
  IF to_regclass('public.push_tokens') IS NULL
     OR NOT EXISTS (SELECT 1 FROM information_schema.columns
                     WHERE table_schema = 'public' AND table_name = 'push_tokens' AND column_name = 'updated_at') THEN
    RETURN 0;
  END IF;
  WITH d AS (
    SELECT ctid FROM public.push_tokens
     WHERE updated_at < now() - make_interval(days => GREATEST(COALESCE(p_days, 120), 1))
     LIMIT 100000
  )
  DELETE FROM public.push_tokens t USING d WHERE t.ctid = d.ctid;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  PERFORM public.log_retention_purge('purge_stale_push_tokens', v_n, jsonb_build_object('older_than_days', p_days));
  RETURN v_n;
END
$$;

-- Click logs only. resource_downloads is deliberately NOT purged: it is the download counter's source of truth.
CREATE OR REPLACE FUNCTION public.purge_old_click_logs(p_days integer DEFAULT 180)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_n bigint := 0;
  v_total bigint := 0;
  v_cut timestamptz := now() - make_interval(days => GREATEST(COALESCE(p_days, 180), 1));
BEGIN
  IF to_regclass('public.event_payment_clicks') IS NOT NULL THEN
    WITH d AS (SELECT ctid FROM public.event_payment_clicks WHERE last_clicked_at < v_cut LIMIT 100000)
    DELETE FROM public.event_payment_clicks t USING d WHERE t.ctid = d.ctid;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_total := v_total + v_n;
  END IF;
  IF to_regclass('public.giving_campaign_clicks') IS NOT NULL THEN
    WITH d AS (SELECT ctid FROM public.giving_campaign_clicks WHERE created_at < v_cut LIMIT 100000)
    DELETE FROM public.giving_campaign_clicks t USING d WHERE t.ctid = d.ctid;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_total := v_total + v_n;
  END IF;
  PERFORM public.log_retention_purge('purge_old_click_logs', v_total, jsonb_build_object('older_than_days', p_days));
  RETURN v_total;
END
$$;

-- Moderation reports that were resolved more than p_months ago.
CREATE OR REPLACE FUNCTION public.purge_resolved_moderation_queue(p_months integer DEFAULT 12)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_n bigint := 0;
BEGIN
  IF to_regclass('public.moderation_queue') IS NULL THEN RETURN 0; END IF;
  WITH d AS (
    SELECT ctid FROM public.moderation_queue
     WHERE resolved_at IS NOT NULL
       AND resolved_at < now() - make_interval(months => GREATEST(COALESCE(p_months, 12), 1))
     LIMIT 100000
  )
  DELETE FROM public.moderation_queue t USING d WHERE t.ctid = d.ctid;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  PERFORM public.log_retention_purge('purge_resolved_moderation_queue', v_n, jsonb_build_object('older_than_months', p_months));
  RETURN v_n;
END
$$;

-- Notifications nobody ever opened (read ones are handled by purge_viewed_notifications).
CREATE OR REPLACE FUNCTION public.purge_old_unread_notifications(p_days integer DEFAULT 180)
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_n bigint := 0;
BEGIN
  IF to_regclass('public.notifications') IS NULL THEN RETURN 0; END IF;
  WITH d AS (
    SELECT ctid FROM public.notifications
     WHERE NOT is_read
       AND created_at < now() - make_interval(days => GREATEST(COALESCE(p_days, 180), 1))
     LIMIT 100000
  )
  DELETE FROM public.notifications t USING d WHERE t.ctid = d.ctid;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  PERFORM public.log_retention_purge('purge_old_unread_notifications', v_n, jsonb_build_object('older_than_days', p_days));
  RETURN v_n;
END
$$;

REVOKE ALL ON FUNCTION public.purge_old_analytics(integer)                FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.purge_stale_push_tokens(integer)            FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.purge_old_click_logs(integer)               FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.purge_resolved_moderation_queue(integer)    FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.purge_old_unread_notifications(integer)     FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.purge_old_analytics(integer)             TO service_role;
GRANT EXECUTE ON FUNCTION public.purge_stale_push_tokens(integer)         TO service_role;
GRANT EXECUTE ON FUNCTION public.purge_old_click_logs(integer)            TO service_role;
GRANT EXECUTE ON FUNCTION public.purge_resolved_moderation_queue(integer) TO service_role;
GRANT EXECUTE ON FUNCTION public.purge_old_unread_notifications(integer)  TO service_role;

-- 4b. Verification-document purge: pg_cron -> pg_net -> edge function, authenticated by a shared
--     secret kept in Vault. Callable again after the secrets are created (see header).
CREATE OR REPLACE FUNCTION public.schedule_verification_document_purge()
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_secrets int;
  v_cmd text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    RAISE NOTICE 'pg_cron is not installed: the verification-document purge is NOT scheduled. Enable pg_cron, then run: select public.schedule_verification_document_purge();';
    RETURN 'skipped: pg_cron missing';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_net') THEN
    RAISE NOTICE 'pg_net is not installed: the verification-document purge is NOT scheduled. Enable pg_net, then run: select public.schedule_verification_document_purge();';
    RETURN 'skipped: pg_net missing';
  END IF;
  IF to_regclass('vault.decrypted_secrets') IS NULL THEN
    RAISE NOTICE 'Supabase Vault is not available: the verification-document purge is NOT scheduled. Enable supabase_vault, create the secrets below, then run: select public.schedule_verification_document_purge();';
    RETURN 'skipped: vault missing';
  END IF;
  EXECUTE 'SELECT count(*) FROM vault.decrypted_secrets WHERE name = ANY ($1)'
    INTO v_secrets USING ARRAY['lioris_project_url', 'lioris_cron_secret'];
  IF v_secrets < 2 THEN
    RAISE NOTICE 'Vault secrets missing: the verification-document purge is NOT scheduled. Run: select vault.create_secret(''https://<project-ref>.supabase.co'', ''lioris_project_url''); select vault.create_secret(''<CRON_SECRET>'', ''lioris_cron_secret''); select public.schedule_verification_document_purge();';
    RETURN 'skipped: vault secrets missing';
  END IF;

  v_cmd := $cmd$
    SELECT net.http_post(
      url := (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'lioris_project_url')
             || '/functions/v1/purge-expired-verification-documents',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'x-cron-secret', (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'lioris_cron_secret')),
      body := '{}'::jsonb,
      timeout_milliseconds := 30000)
  $cmd$;
  BEGIN
    PERFORM cron.unschedule('lioris_purge_verification_documents');
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  PERFORM cron.schedule('lioris_purge_verification_documents', '7 4 * * *', v_cmd);
  RETURN 'scheduled';
END
$$;
REVOKE ALL ON FUNCTION public.schedule_verification_document_purge() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.schedule_verification_document_purge() TO service_role;

DO $do$
DECLARE
  r record;
BEGIN
  PERFORM public.schedule_verification_document_purge();

  IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    RAISE NOTICE 'pg_cron is not installed: lifecycle retention jobs NOT scheduled';
    RETURN;
  END IF;
  FOR r IN
    SELECT * FROM (VALUES
      ('lioris_purge_analytics',             '12 4 * * *', 'SELECT public.purge_old_analytics(90)',              'public.purge_old_analytics(integer)'),
      ('lioris_purge_stale_push_tokens',     '17 4 * * *', 'SELECT public.purge_stale_push_tokens(120)',         'public.purge_stale_push_tokens(integer)'),
      ('lioris_purge_click_logs',            '22 4 * * *', 'SELECT public.purge_old_click_logs(180)',            'public.purge_old_click_logs(integer)'),
      ('lioris_purge_moderation_queue',      '27 4 * * *', 'SELECT public.purge_resolved_moderation_queue(12)',  'public.purge_resolved_moderation_queue(integer)'),
      ('lioris_purge_unread_notifications',  '32 4 * * *', 'SELECT public.purge_old_unread_notifications(180)',  'public.purge_old_unread_notifications(integer)')
    ) AS j(name, schedule, cmd, fn)
  LOOP
    BEGIN
      IF to_regprocedure(r.fn) IS NULL THEN
        RAISE NOTICE 'function % missing: job % skipped', r.fn, r.name;
        CONTINUE;
      END IF;
      BEGIN
        PERFORM cron.unschedule(r.name);
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
      PERFORM cron.schedule(r.name, r.schedule, r.cmd);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'Could not schedule cron job %: %', r.name, SQLERRM;
    END;
  END LOOP;
END
$do$;

-- ============================================================================
-- 5. Analytics integrity
-- ============================================================================
DO $do$
BEGIN
  IF to_regclass('public.analytics_events') IS NULL THEN
    RAISE NOTICE 'analytics_events missing: section 5 skipped';
    RETURN;
  END IF;

  -- Bounded rows. NOT VALID: enforced for every new row without scanning (or failing on) old data.
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.analytics_events'::regclass AND conname = 'analytics_events_name_len') THEN
    ALTER TABLE public.analytics_events ADD CONSTRAINT analytics_events_name_len CHECK (length(name) <= 64) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.analytics_events'::regclass AND conname = 'analytics_events_type_len') THEN
    ALTER TABLE public.analytics_events ADD CONSTRAINT analytics_events_type_len CHECK (length(event_type) <= 32) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.analytics_events'::regclass AND conname = 'analytics_events_metadata_size') THEN
    ALTER TABLE public.analytics_events ADD CONSTRAINT analytics_events_metadata_size CHECK (metadata IS NULL OR pg_column_size(metadata) <= 2048) NOT VALID;
  END IF;

  DROP POLICY IF EXISTS "Anyone can insert analytics events" ON public.analytics_events;
  DROP POLICY IF EXISTS "Authenticated users insert own analytics events" ON public.analytics_events;
  DROP POLICY IF EXISTS "Anonymous visitors insert anonymous analytics events" ON public.analytics_events;

  IF to_regprocedure('public.auth_profile_campus()') IS NOT NULL THEN
    CREATE POLICY "Authenticated users insert own analytics events" ON public.analytics_events
      FOR INSERT TO authenticated
      WITH CHECK (
        (user_id IS NULL OR user_id = auth.uid())
        AND event_type IN ('page_view', 'feature_use', 'session_start', 'screen_view')
        AND (campus_code IS NULL OR campus_code = 'GLOBAL' OR campus_code = public.auth_profile_campus())
      );
  ELSE
    CREATE POLICY "Authenticated users insert own analytics events" ON public.analytics_events
      FOR INSERT TO authenticated
      WITH CHECK (
        (user_id IS NULL OR user_id = auth.uid())
        AND event_type IN ('page_view', 'feature_use', 'session_start', 'screen_view')
        AND (campus_code IS NULL OR campus_code = 'GLOBAL')
      );
  END IF;
  CREATE POLICY "Anonymous visitors insert anonymous analytics events" ON public.analytics_events
    FOR INSERT TO anon
    WITH CHECK (
      user_id IS NULL
      AND event_type IN ('page_view', 'session_start')
      AND (campus_code IS NULL OR campus_code = 'GLOBAL')
    );
END
$do$;

-- record_user_activity: signed-in callers only, campus comes from the caller's profile (a
-- caller-supplied campus used to let anyone skew another campus' numbers), bounded input and a
-- per-user burst limit. Unknown event types are ignored instead of raising so a client bug cannot
-- break the screen that called it.
CREATE OR REPLACE FUNCTION public.record_user_activity(
    p_event_type TEXT,
    p_name TEXT,
    p_campus_code TEXT DEFAULT NULL,
    p_metadata JSONB DEFAULT '{}'::jsonb
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_uid UUID := auth.uid();
    v_campus TEXT;
    v_name TEXT := left(btrim(COALESCE(p_name, '')), 64);
    v_meta JSONB := COALESCE(p_metadata, '{}'::jsonb);
BEGIN
    IF v_uid IS NULL AND auth.role() IS DISTINCT FROM 'service_role' THEN
        RETURN;
    END IF;
    IF p_event_type IS NULL OR p_event_type NOT IN ('page_view', 'feature_use', 'session_start', 'screen_view') OR v_name = '' THEN
        RETURN;
    END IF;
    IF jsonb_typeof(v_meta) <> 'object' OR pg_column_size(v_meta) > 2048 THEN
        v_meta := '{}'::jsonb;
    END IF;

    IF v_uid IS NOT NULL THEN
        IF (SELECT count(*) FROM public.analytics_events
             WHERE user_id = v_uid AND created_at > now() - interval '1 minute') >= 60 THEN
            RETURN;
        END IF;
        SELECT campus_code INTO v_campus FROM public.profiles WHERE id = v_uid;
    ELSE
        v_campus := NULLIF(btrim(COALESCE(p_campus_code, '')), '');
    END IF;

    INSERT INTO public.analytics_events (user_id, event_type, name, campus_code, metadata, created_at)
    VALUES (v_uid, p_event_type, v_name, COALESCE(v_campus, 'GLOBAL'), v_meta, NOW());

    IF v_uid IS NOT NULL THEN
        IF p_event_type = 'session_start' THEN
            UPDATE public.profiles SET last_active_at = NOW(), last_login_at = NOW() WHERE id = v_uid;
        ELSE
            UPDATE public.profiles SET last_active_at = NOW() WHERE id = v_uid;
        END IF;
    END IF;
END;
$$;

REVOKE ALL ON FUNCTION public.record_user_activity(TEXT, TEXT, TEXT, JSONB) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.record_user_activity(TEXT, TEXT, TEXT, JSONB) TO authenticated, service_role;

-- ============================================================================
-- 6. Push token takeover
-- ============================================================================
-- push_tokens.token is UNIQUE and the INSERT policy is owner-only, so when A's token row survives
-- (A's session had already expired at sign-out) B could not claim it and A's notifications kept
-- landing on B's phone. claim_push_token() upserts the token and re-parents it to the caller.
CREATE OR REPLACE FUNCTION public.claim_push_token(p_token text, p_platform text DEFAULT NULL)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required.' USING ERRCODE = '28000';
  END IF;
  IF p_token IS NULL OR char_length(p_token) NOT BETWEEN 10 AND 512
     OR p_token !~ '^Expo(nent)?PushToken\[[A-Za-z0-9_-]{6,}\]$' THEN
    RAISE EXCEPTION 'Invalid push token.' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.push_tokens AS t (user_id, token, platform)
  VALUES (v_uid, p_token, left(p_platform, 32))
  ON CONFLICT (token) DO UPDATE
    SET user_id = EXCLUDED.user_id,
        platform = COALESCE(EXCLUDED.platform, t.platform),
        updated_at = now();
END
$$;
REVOKE ALL ON FUNCTION public.claim_push_token(text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.claim_push_token(text, text) TO authenticated, service_role;

-- Older clients call register_push_token(); it is now the same operation.
CREATE OR REPLACE FUNCTION public.register_push_token(p_token text, p_platform text DEFAULT NULL)
RETURNS void
LANGUAGE sql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$ SELECT public.claim_push_token(p_token, p_platform) $$;
REVOKE ALL ON FUNCTION public.register_push_token(text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.register_push_token(text, text) TO authenticated, service_role;

-- ============================================================================
-- 7. Missing indexes
-- ============================================================================
-- Plain CREATE INDEX IF NOT EXISTS (these tables are modest). An index is skipped when the table or a
-- column is missing, or when an equivalent non-partial index (same key columns, same order) exists.
DO $do$
DECLARE
  r record;
  v_cols text[];
  v_exists boolean;
BEGIN
  FOR r IN
    SELECT * FROM (VALUES
      ('idx_post_comments_post',               'post_comments',        'post_id',                   NULL),
      ('idx_post_comments_post_created',       'post_comments',        'post_id, created_at',       NULL),
      ('idx_marketplace_listings_campus',      'marketplace_listings', 'campus_code',               NULL),
      ('idx_verifications_campus_status',      'verifications',        'campus_code, status',       NULL),
      ('idx_giving_campaigns_campus',          'giving_campaigns',     'campus_code',               NULL),
      ('idx_study_groups_campus',              'study_groups',         'campus_code',               NULL),
      ('idx_chat_channels_campus',             'chat_channels',        'campus_code',               NULL),
      ('idx_job_alerts_campus',                'job_alerts',           'campus_code',               NULL),
      ('idx_notifications_recipient_created',  'notifications',        'recipient_id, created_at DESC', NULL),
      ('idx_notifications_recipient_unread',   'notifications',        'recipient_id',              'NOT is_read'),
      ('idx_resources_campus_created',         'resources',            'campus_code, created_at DESC', NULL),
      ('idx_events_campus_start',              'events',               'campus_code, start_time',   NULL),
      ('idx_chat_messages_channel_created',    'chat_messages',        'channel_id, created_at DESC', NULL),
      -- user-facing foreign keys that make deleting a profile scan the whole child table
      ('idx_post_likes_user',                  'post_likes',           'user_id',                   NULL),
      ('idx_post_comment_likes_user',          'post_comment_likes',   'user_id',                   NULL),
      ('idx_event_waitlist_user',              'event_waitlist',       'user_id',                   NULL),
      ('idx_resource_downloads_user',          'resource_downloads',   'user_id',                   NULL),
      ('idx_event_payment_clicks_user',        'event_payment_clicks', 'user_id',                   NULL),
      ('idx_giving_campaign_clicks_campaign_user', 'giving_campaign_clicks', 'campaign_id, user_id', NULL),
      ('idx_study_group_posts_author',         'study_group_posts',    'author_id',                 NULL),
      ('idx_giving_campaigns_creator',         'giving_campaigns',     'creator_id',                NULL)
    ) AS i(idx, tbl, cols, pred)
  LOOP
    BEGIN
      IF to_regclass('public.' || r.tbl) IS NULL THEN CONTINUE; END IF;
      v_cols := regexp_split_to_array(regexp_replace(r.cols, '\s+(ASC|DESC)', '', 'gi'), '\s*,\s*');
      IF EXISTS (SELECT 1 FROM unnest(v_cols) c
                  WHERE NOT EXISTS (SELECT 1 FROM information_schema.columns
                                     WHERE table_schema = 'public' AND table_name = r.tbl AND column_name = c)) THEN
        CONTINUE;
      END IF;
      IF r.pred IS NULL THEN
        SELECT EXISTS (
          SELECT 1 FROM pg_index i
           WHERE i.indrelid = ('public.' || r.tbl)::regclass AND i.indpred IS NULL AND i.indisvalid
             AND (SELECT array_agg(a.attname::text ORDER BY k.ord)
                    FROM unnest(i.indkey::int2[]) WITH ORDINALITY k(attnum, ord)
                    JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k.attnum
                   WHERE k.ord <= i.indnkeyatts) = v_cols
        ) INTO v_exists;
        IF v_exists THEN CONTINUE; END IF;
      END IF;
      EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON public.%I (%s)%s',
                     r.idx, r.tbl, r.cols, CASE WHEN r.pred IS NULL THEN '' ELSE ' WHERE ' || r.pred END);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'index % not created: %', r.idx, SQLERRM;
    END;
  END LOOP;
END
$do$;

-- Every remaining single-column FK from a public table to profiles(id) without an index that leads
-- with that column (profile deletion and the erasure RPC scan the child table otherwise).
DO $do$
DECLARE
  r record;
  v_made int := 0;
BEGIN
  FOR r IN
    SELECT cl.relname::text AS tbl, a.attname::text AS col, c.oid AS con
      FROM pg_constraint c
      JOIN pg_class cl ON cl.oid = c.conrelid AND cl.relkind = 'r'
      JOIN pg_namespace n ON n.oid = cl.relnamespace AND n.nspname = 'public'
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = c.conkey[1]
     WHERE c.contype = 'f'
       AND array_length(c.conkey, 1) = 1
       AND c.confrelid = 'public.profiles'::regclass
       AND NOT EXISTS (
         SELECT 1 FROM pg_index i
          WHERE i.indrelid = c.conrelid AND i.indisvalid AND i.indkey[0] = c.conkey[1])
     ORDER BY cl.relname, a.attname
     LIMIT 60
  LOOP
    BEGIN
      EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON public.%I (%I)',
                     left('idx_' || r.tbl || '_' || r.col || '_fk', 63), r.tbl, r.col);
      v_made := v_made + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'FK index on %.% not created: %', r.tbl, r.col, SQLERRM;
    END;
  END LOOP;
  IF v_made > 0 THEN RAISE NOTICE 'created % foreign-key indexes', v_made; END IF;
END
$do$;

-- ============================================================================
-- 8. Campus deletion safety
-- ============================================================================
-- campuses has ON DELETE CASCADE children (posts, events, resources, verifications, ...). A direct
-- DELETE (e.g. a Super Admin through REST) used to wipe them all with no audit trail. Now only
-- admin_delete_campus() can delete a row: it audits first, then sets a transaction-local flag.
CREATE OR REPLACE FUNCTION public.campuses_block_direct_delete()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
  IF TG_OP = 'TRUNCATE' THEN
    RAISE EXCEPTION 'campuses cannot be truncated' USING ERRCODE = '42501';
  END IF;
  IF current_setting('lioris.campus_delete', true) IS DISTINCT FROM 'on' THEN
    RAISE EXCEPTION 'Campuses can only be deleted through admin_delete_campus() (it audits and reassigns members).'
      USING ERRCODE = '42501';
  END IF;
  RETURN OLD;
END
$$;

DO $do$
BEGIN
  IF to_regclass('public.campuses') IS NOT NULL THEN
    DROP TRIGGER IF EXISTS trg_campuses_block_direct_delete ON public.campuses;
    CREATE TRIGGER trg_campuses_block_direct_delete
      BEFORE DELETE ON public.campuses
      FOR EACH ROW EXECUTE FUNCTION public.campuses_block_direct_delete();
    DROP TRIGGER IF EXISTS trg_campuses_block_truncate ON public.campuses;
    CREATE TRIGGER trg_campuses_block_truncate
      BEFORE TRUNCATE ON public.campuses
      FOR EACH STATEMENT EXECUTE FUNCTION public.campuses_block_direct_delete();
  END IF;
END
$do$;

-- Same behaviour as the 20261101000000 version (it supersedes 20261027010000) plus the audit row and the
-- guard flag. Also fixes a latent error there: the demotion CASE cast to public.user_role, a type that
-- does not exist (the column is public.user_role_type), so deleting a campus that still had members failed.
CREATE OR REPLACE FUNCTION public.admin_delete_campus(p_code text, p_members text DEFAULT 'reassign')
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  t        record;
  n        bigint;
  pass     int;
  pending  text[] := '{}';
  failed   text[];
  deleted  jsonb := '{}'::jsonb;
  moved    bigint := 0;
  v_impact jsonb := '{}'::jsonb;
BEGIN
  IF auth.role() <> 'service_role' AND NOT public.auth_is_super_admin() THEN
    RAISE EXCEPTION 'super_admin_required: only a Super Administrator can delete a campus' USING ERRCODE = '42501';
  END IF;

  p_code := upper(btrim(p_code));
  IF p_code IS NULL OR p_code = '' OR p_code = 'GLOBAL' THEN
    RAISE EXCEPTION 'protected_campus: the Global network cannot be deleted';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.campuses WHERE code = p_code) THEN
    RAISE EXCEPTION 'not_found: that campus does not exist';
  END IF;
  IF p_members NOT IN ('reassign', 'block') THEN
    RAISE EXCEPTION 'bad_request: members must be reassign or block';
  END IF;

  SELECT count(*) INTO moved FROM public.profiles WHERE campus_code = p_code;
  IF moved > 0 AND p_members = 'block' THEN
    RAISE EXCEPTION 'has_members: % member(s) still belong to this campus', moved;
  END IF;

  -- Audit BEFORE anything is removed, with the row counts that are about to disappear. It is part
  -- of the same transaction: if the deletion fails, the entry is rolled back with it.
  IF to_regprocedure('public.campus_delete_impact(text)') IS NOT NULL THEN
    v_impact := public.campus_delete_impact(p_code);
  END IF;
  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  VALUES (auth.uid(), 'campus_deleted', 'campus', NULL,
          jsonb_build_object('campusCode', p_code, 'institutionCode', p_code,
                             'membersReassigned', moved, 'removedRows', v_impact,
                             'callerRole', auth.role(),
                             'summary', format('Deleted campus %s (%s member(s) moved to GLOBAL)', p_code, moved)));

  PERFORM set_config('lioris.campus_delete', 'on', true);

  -- Members keep their accounts and land on GLOBAL; Campus Admins of the deleted campus are
  -- demoted to student so they do not retain role='admin' with campus_code='GLOBAL'.
  IF moved > 0 THEN
    UPDATE public.profiles
       SET campus_code = 'GLOBAL',
           role = CASE
             WHEN role::text = 'admin'
                  AND COALESCE(admin_role, 'campus_admin') <> 'super_admin'
                  AND LOWER(COALESCE(email, '')) <> 'inememmanuel@gmail.com'
             THEN 'student'::public.user_role_type
             ELSE role
           END,
           admin_role = CASE
             WHEN role::text = 'admin'
                  AND COALESCE(admin_role, 'campus_admin') <> 'super_admin'
                  AND LOWER(COALESCE(email, '')) <> 'inememmanuel@gmail.com'
             THEN NULL
             ELSE admin_role
           END,
           is_campus_ambassador = false
     WHERE campus_code = p_code;
  END IF;

  FOR t IN
    SELECT c.table_name
    FROM information_schema.columns c
    JOIN information_schema.tables tb
      ON tb.table_schema = c.table_schema AND tb.table_name = c.table_name AND tb.table_type = 'BASE TABLE'
    WHERE c.table_schema = 'public' AND c.column_name = 'campus_code' AND c.table_name <> 'profiles'
    ORDER BY c.table_name
  LOOP
    pending := array_append(pending, t.table_name);
  END LOOP;

  FOR pass IN 1..4 LOOP
    failed := '{}';
    FOR t IN SELECT x AS table_name FROM unnest(pending) x LOOP
      BEGIN
        EXECUTE format('DELETE FROM public.%I WHERE campus_code = $1', t.table_name) USING p_code;
        GET DIAGNOSTICS n = ROW_COUNT;
        IF n > 0 THEN
          deleted := deleted || jsonb_build_object(t.table_name, COALESCE((deleted ->> t.table_name)::bigint, 0) + n);
        END IF;
      EXCEPTION WHEN OTHERS THEN
        failed := array_append(failed, t.table_name);
      END;
    END LOOP;
    pending := failed;
    EXIT WHEN COALESCE(array_length(pending, 1), 0) = 0;
  END LOOP;

  IF COALESCE(array_length(pending, 1), 0) > 0 THEN
    RAISE EXCEPTION 'delete_blocked: could not clear tables: %', array_to_string(pending, ', ');
  END IF;

  DELETE FROM public.campuses WHERE code = p_code;
  PERFORM set_config('lioris.campus_delete', 'off', true);

  RETURN jsonb_build_object('code', p_code, 'members_reassigned', moved, 'deleted', deleted);
END $$;

REVOKE ALL ON FUNCTION public.admin_delete_campus(text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_delete_campus(text, text) TO authenticated, service_role;

-- ============================================================================
-- 9. Realtime publication
-- ============================================================================
-- supabase_schema.sql added every table in ONE statement inside EXCEPTION WHEN OTHERS THEN NULL, so
-- a single already-published table silently added none of the others. One table at a time, a
-- duplicate is ignored; nothing is ever removed from the publication. profiles is deliberately NOT
-- added: realtime ignores column-level privileges, so streaming it would expose e-mail addresses.
DO $do$
DECLARE
  t text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    RAISE NOTICE 'publication supabase_realtime does not exist: realtime tables not configured';
    RETURN;
  END IF;
  FOREACH t IN ARRAY ARRAY[
    'chat_messages', 'chat_channels', 'notifications', 'connections', 'events', 'event_attendees',
    'posts', 'post_comments', 'verifications', 'moderation_queue', 'marketplace_listings',
    'mentorships', 'mentorship_sessions', 'mentorship_updates', 'mentorship_goals',
    'study_group_posts', 'study_group_sessions', 'study_group_members',
    'portal_links', 'announcements'
  ]
  LOOP
    BEGIN
      IF to_regclass('public.' || t) IS NOT NULL THEN
        EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', t);
      END IF;
    EXCEPTION
      WHEN duplicate_object THEN NULL;
      WHEN OTHERS THEN RAISE WARNING 'could not add % to supabase_realtime: %', t, SQLERRM;
    END;
  END LOOP;
END
$do$;

-- ============================================================================
-- 10. Sign-up trigger robustness; non-fatal event fan-out
-- ============================================================================
-- Same function as 20261028000000 (role/campus derivation, age flag, username fallback loop, consent
-- record) with ONE change: a unique violation on the profile INSERT (a stale / differently-cased
-- row already owns the e-mail) no longer aborts sign-up. It retries with a placeholder address so
-- the account exists; the e-mail is reconciled by the e-mail sync / an admin.
CREATE OR REPLACE FUNCTION public.handle_new_user_profile()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
    v_campus text;
    v_role public.user_role_type;
    v_terms_version text;
    v_terms_at timestamptz;
    v_age_raw text;
    v_age boolean;
    v_username text;
    v_try int;
BEGIN
    BEGIN
        v_campus := public.campus_for_email(NEW.email);
    EXCEPTION WHEN OTHERS THEN
        v_campus := NULL;
    END;
    v_campus := COALESCE(v_campus, NULLIF(NEW.raw_user_meta_data->>'campus_code', ''), 'GLOBAL');
    IF v_campus <> 'GLOBAL' AND NOT EXISTS (SELECT 1 FROM public.campuses c WHERE c.code = v_campus AND c.is_active) THEN
        v_campus := 'GLOBAL';
    END IF;

    v_role := CASE
        WHEN NEW.raw_user_meta_data->>'role' = 'alumni' THEN 'alumni'::public.user_role_type
        ELSE 'student'::public.user_role_type
    END;

    BEGIN
        INSERT INTO public.profiles (id, email, full_name, role, campus_code, verification_status)
        VALUES (
            NEW.id,
            NEW.email,
            COALESCE(NULLIF(btrim(NEW.raw_user_meta_data->>'full_name'), ''), split_part(NEW.email, '@', 1)),
            v_role,
            v_campus,
            'unverified'::public.verification_status_type
        )
        ON CONFLICT (id) DO NOTHING;
    EXCEPTION WHEN unique_violation THEN
        -- A stale or differently-cased profile row already owns this e-mail (profiles_email_key).
        -- Sign-up must not fail because of it: create the profile with a placeholder address that
        -- cannot collide, and say so. (A row with this id may also have appeared concurrently.)
        RAISE WARNING 'handle_new_user_profile: e-mail already used by another profile row, using a placeholder for %', NEW.id;
        INSERT INTO public.profiles (id, email, full_name, role, campus_code, verification_status)
        VALUES (
            NEW.id,
            'pending+' || NEW.id::text || '@email-conflict.invalid',
            COALESCE(NULLIF(btrim(NEW.raw_user_meta_data->>'full_name'), ''), split_part(NEW.email, '@', 1)),
            v_role,
            v_campus,
            'unverified'::public.verification_status_type
        )
        ON CONFLICT (id) DO NOTHING;
    END;

    -- Username. A taken, reserved or malformed handle must never make sign-up itself fail, and must never leave
    -- the member with NO handle either (two people can pass the availability check at the same moment, and
    -- the unique index then rejects the second). The second person gets the handle plus a short number and is
    -- told on the next screen; they can change it in Settings.
    v_username := lower(trim(COALESCE(NEW.raw_user_meta_data->>'username', '')));
    IF v_username !~ '^[a-z0-9._]{3,24}$' OR public.is_reserved_username(v_username) THEN
        v_username := left(regexp_replace(lower(split_part(NEW.email, '@', 1)), '[^a-z0-9._]', '', 'g'), 18);
        IF length(v_username) < 3 OR public.is_reserved_username(v_username) THEN
            v_username := 'student';
        END IF;
    END IF;
    v_try := 0;
    LOOP
        BEGIN
            UPDATE public.profiles
               SET username = CASE WHEN v_try = 0 THEN v_username
                                   ELSE left(v_username, 19) || (1000 + floor(random() * 9000))::int END
             WHERE id = NEW.id;
            EXIT;
        EXCEPTION WHEN unique_violation THEN
            v_try := v_try + 1;
            IF v_try > 8 THEN
                EXIT; -- vanishingly unlikely; the member keeps no handle and is asked to pick one
            END IF;
        WHEN OTHERS THEN
            EXIT;
        END;
    END LOOP;

    BEGIN
        v_terms_version := NULLIF(btrim(NEW.raw_user_meta_data->>'terms_version'), '');
        IF v_terms_version IS NOT NULL AND to_regclass('public.consent_records') IS NOT NULL THEN
            BEGIN
                v_terms_at := (NEW.raw_user_meta_data->>'terms_accepted_at')::timestamptz;
            EXCEPTION WHEN OTHERS THEN
                v_terms_at := NULL;
            END;
            v_terms_at := LEAST(COALESCE(v_terms_at, now()), now());

            v_age_raw := lower(COALESCE(NEW.raw_user_meta_data->>'age_eligibility_confirmed', NEW.raw_user_meta_data->>'age_confirmed_18', ''));
            v_age := v_age_raw IN ('true', 't', '1', 'yes');

            INSERT INTO public.consent_records (user_id, consent_type, version, accepted_at, age_confirmed_18, source)
            VALUES (NEW.id, 'terms_and_privacy', left(v_terms_version, 64), v_terms_at, v_age, 'signup');
        END IF;
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'consent record not stored for %: %', NEW.id, SQLERRM;
    END;

    RETURN NEW;
END;
$function$;

-- Event cancellation: one failing notification insert (a deleted recipient, a check violation, a
-- misbehaving notification trigger) used to roll back the organiser's cancellation. Each insert
-- now runs in its own sub-transaction; a failure is logged as a warning and skipped.
CREATE OR REPLACE FUNCTION public.notify_event_cancelled()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  r RECORD;
  v_body TEXT;
BEGIN
  v_body := '"' || NEW.title || '" has been cancelled.';
  IF NEW.cancellation_reason IS NOT NULL AND btrim(NEW.cancellation_reason) <> '' THEN
    v_body := v_body || ' Reason: ' || NEW.cancellation_reason;
  END IF;
  FOR r IN SELECT user_id FROM public.event_attendees WHERE event_id = NEW.id LOOP
    BEGIN
      INSERT INTO public.notifications (recipient_id, title, body, type, action_url, is_read)
      VALUES (r.user_id, 'Event cancelled', v_body, 'event', '/event/' || NEW.id, false);
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'notify_event_cancelled: notification for % skipped: %', r.user_id, SQLERRM;
    END;
  END LOOP;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'notify_event_cancelled failed for event %: %', NEW.id, SQLERRM;
  RETURN NEW;
END $$;

-- ============================================================================
-- 11. connections: one live row per unordered pair
-- ============================================================================
-- The existing unique pair index only covers status = 'pending'; accepted A->B and B->A could both
-- exist. Resolve existing duplicates first (an accepted row wins, otherwise the oldest), then add
-- the canonical-pair index over pending + accepted.
DO $do$
DECLARE
  v_n bigint;
BEGIN
  IF to_regclass('public.connections') IS NULL THEN RETURN; END IF;
  WITH ranked AS (
    SELECT id,
           row_number() OVER (
             PARTITION BY LEAST(requester_id, recipient_id), GREATEST(requester_id, recipient_id)
             ORDER BY (status = 'accepted') DESC, created_at NULLS LAST, id) AS rn
      FROM public.connections
     WHERE status IN ('pending', 'accepted')
  )
  DELETE FROM public.connections c USING ranked r WHERE c.id = r.id AND r.rn > 1;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN RAISE NOTICE 'connections: removed % duplicate pair row(s)', v_n; END IF;

  CREATE UNIQUE INDEX IF NOT EXISTS uq_connections_live_pair
    ON public.connections (LEAST(requester_id, recipient_id), GREATEST(requester_id, recipient_id))
    WHERE status IN ('pending', 'accepted');
END
$do$;

-- ============================================================================
-- 12. Storage: only onboarded users upload to resources / campus-media
-- ============================================================================
-- Avatars keep their own policy ("Authenticated users can upload avatars"), because uploading a
-- profile photo is part of onboarding. Chat attachments live in the resources bucket under
-- '<uid>/', so an onboarded member keeps working; size and mime limits are untouched.
CREATE OR REPLACE FUNCTION public.auth_onboarding_complete()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT COALESCE((SELECT p.onboarding_complete FROM public.profiles p WHERE p.id = auth.uid()), false)
$$;
REVOKE ALL ON FUNCTION public.auth_onboarding_complete() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.auth_onboarding_complete() TO authenticated, service_role;

DO $do$
BEGIN
  DROP POLICY IF EXISTS "Authenticated users can upload public storage objects" ON storage.objects;
  CREATE POLICY "Authenticated users can upload public storage objects" ON storage.objects
    FOR INSERT TO authenticated
    WITH CHECK (
      bucket_id = ANY (ARRAY['resources', 'campus-media'])
      AND (
        public.auth_is_super_admin()
        OR ((storage.foldername(name))[1] = auth.uid()::text
            AND NOT public.auth_is_suspended()
            AND public.auth_onboarding_complete())
      )
    );

  DROP POLICY IF EXISTS "Users and admins can update public storage objects" ON storage.objects;
  CREATE POLICY "Users and admins can update public storage objects" ON storage.objects
    FOR UPDATE TO authenticated
    USING (
      bucket_id = ANY (ARRAY['resources', 'avatars', 'campus-media'])
      AND ((storage.foldername(name))[1] = auth.uid()::text
           OR public.auth_is_super_admin()
           OR public.can_admin_object_owner(name))
    )
    WITH CHECK (
      bucket_id = ANY (ARRAY['resources', 'avatars', 'campus-media'])
      AND (
        public.auth_is_super_admin()
        OR ((storage.foldername(name))[1] = auth.uid()::text
            AND NOT public.auth_is_suspended()
            AND (bucket_id = 'avatars' OR public.auth_onboarding_complete()))
      )
    );
EXCEPTION WHEN insufficient_privilege THEN
  RAISE NOTICE 'Not allowed to manage storage.objects policies from this role: apply the two upload policies in the Dashboard (section 12 of 20261107000000_data_lifecycle.sql).';
END
$do$;

INSERT INTO public._manual_migration_log (version) VALUES ('20261107000000') ON CONFLICT (version) DO NOTHING;
COMMIT;

-- ########## 20261108000000_edge_support.sql ##########
-- ============================================================================
-- 20261108000000  Database support for the edge-function hardening pass
-- ============================================================================
-- Idempotent (CREATE OR REPLACE, guarded) and transactional. Every function here is
-- service_role only: the edge functions call them with the service-role client.
--
--   1. admin_revoke_user_sessions(uuid, timestamptz)
--        The GoTrue admin API's signOut() takes a user's JWT, not a user id, so the
--        old admin-force-signout call could never revoke anything. This deletes the
--        user's rows from auth.refresh_tokens and auth.sessions directly (guarded with
--        to_regclass, so a differently-shaped auth schema degrades to a no-op instead of
--        an error). With p_since only sessions created at/after that moment are
--        revoked (used to end an impersonation without logging the real user out of
--        devices they signed into earlier). NOTE: an already-issued access token (JWT)
--        stays valid until its own expiry (default 1 hour); the refresh token and the
--        session are what is destroyed, so it can not be renewed.
--   2. consume_rate_limit_ex(text, int, int) -> jsonb {allowed, count}
--        Same counter as consume_rate_limit(text, int, int) (which is untouched) but
--        returns the hit count, so the edge limiter can write ONE audit row on the
--        first denial of a window instead of one per denied request.
--   3. bump_client_error(text, int) -> boolean
--        Atomic "occurrences = occurrences + 1" for report-client-error (the old
--        select-then-update lost increments under concurrency).
-- ============================================================================

BEGIN;
DO $chain$ BEGIN IF NOT EXISTS (SELECT 1 FROM public._manual_migration_log WHERE version = '20261107000000') THEN RAISE EXCEPTION 'Stopped: migration 20261107000000 has not been applied. Fix it and re-run this whole file.'; END IF; END $chain$;

-- ---------------------------------------------------------------------------
-- 1. admin_revoke_user_sessions
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.admin_revoke_user_sessions(p_user_id uuid, p_since timestamptz DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_tokens   bigint := 0;
  v_sessions bigint := 0;
  v_n        bigint;
  v_tok_has_session boolean := false;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION 'p_user_id is required.';
  END IF;

  IF to_regclass('auth.refresh_tokens') IS NOT NULL THEN
    SELECT EXISTS (
      SELECT 1 FROM pg_attribute
       WHERE attrelid = 'auth.refresh_tokens'::regclass AND attname = 'session_id' AND NOT attisdropped
    ) INTO v_tok_has_session;

    IF p_since IS NULL THEN
      DELETE FROM auth.refresh_tokens WHERE user_id::text = p_user_id::text;
    ELSIF v_tok_has_session AND to_regclass('auth.sessions') IS NOT NULL THEN
      DELETE FROM auth.refresh_tokens
       WHERE user_id::text = p_user_id::text
         AND session_id IN (SELECT s.id FROM auth.sessions s WHERE s.user_id = p_user_id AND s.created_at >= p_since);
    ELSE
      DELETE FROM auth.refresh_tokens WHERE user_id::text = p_user_id::text AND created_at >= p_since;
    END IF;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_tokens := v_n;
  END IF;

  IF to_regclass('auth.sessions') IS NOT NULL THEN
    IF p_since IS NULL THEN
      DELETE FROM auth.sessions WHERE user_id = p_user_id;
    ELSE
      DELETE FROM auth.sessions WHERE user_id = p_user_id AND created_at >= p_since;
    END IF;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_sessions := v_n;
  END IF;

  RETURN jsonb_build_object('user_id', p_user_id, 'refresh_tokens', v_tokens, 'sessions', v_sessions);
END
$$;

REVOKE ALL ON FUNCTION public.admin_revoke_user_sessions(uuid, timestamptz) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.admin_revoke_user_sessions(uuid, timestamptz) TO service_role;

-- ---------------------------------------------------------------------------
-- 2. consume_rate_limit_ex: counter + hit count (new name; the old signature is unchanged)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.api_rate_limits (
  key text PRIMARY KEY,
  window_start timestamptz NOT NULL,
  count int NOT NULL
);
ALTER TABLE public.api_rate_limits ENABLE ROW LEVEL SECURITY;  -- no policies on purpose

CREATE OR REPLACE FUNCTION public.consume_rate_limit_ex(p_key text, p_limit int, p_window_seconds int)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_count int;
BEGIN
  IF p_key IS NULL OR btrim(p_key) = '' OR length(p_key) > 256 THEN
    RAISE EXCEPTION 'invalid rate limit key';
  END IF;
  IF p_window_seconds IS NULL OR p_window_seconds <= 0 THEN
    RAISE EXCEPTION 'p_window_seconds must be positive';
  END IF;
  IF p_limit IS NULL OR p_limit <= 0 THEN
    RETURN jsonb_build_object('allowed', false, 'count', 0);
  END IF;

  INSERT INTO public.api_rate_limits AS r (key, window_start, count)
  VALUES (p_key, now(), 1)
  ON CONFLICT (key) DO UPDATE
    SET window_start = CASE WHEN r.window_start + make_interval(secs => p_window_seconds) <= now()
                            THEN now() ELSE r.window_start END,
        count        = CASE WHEN r.window_start + make_interval(secs => p_window_seconds) <= now()
                            THEN 1 ELSE LEAST(r.count + 1, 2000000000) END
  RETURNING r.count INTO v_count;

  RETURN jsonb_build_object('allowed', v_count <= p_limit, 'count', v_count);
END
$$;

REVOKE ALL ON FUNCTION public.consume_rate_limit_ex(text, int, int) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.consume_rate_limit_ex(text, int, int) TO service_role;

-- ---------------------------------------------------------------------------
-- 3. bump_client_error: atomic occurrences + 1 on the newest row of a fingerprint
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.bump_client_error(p_fingerprint text, p_window_seconds int DEFAULT 3600)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_id uuid;
BEGIN
  IF p_fingerprint IS NULL OR btrim(p_fingerprint) = '' OR to_regclass('public.client_errors') IS NULL THEN
    RETURN false;
  END IF;

  -- FOR UPDATE (not SKIP LOCKED): a concurrent bump waits for the row instead of
  -- falling through to a duplicate insert.
  SELECT id INTO v_id
    FROM public.client_errors
   WHERE fingerprint = p_fingerprint
     AND last_seen_at >= now() - make_interval(secs => GREATEST(COALESCE(p_window_seconds, 3600), 1))
   ORDER BY last_seen_at DESC
   LIMIT 1
   FOR UPDATE;
  IF v_id IS NULL THEN
    RETURN false;
  END IF;

  UPDATE public.client_errors
     SET occurrences = LEAST(occurrences + 1, 2000000000), last_seen_at = now()
   WHERE id = v_id;
  RETURN true;
END
$$;

REVOKE ALL ON FUNCTION public.bump_client_error(text, int) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.bump_client_error(text, int) TO service_role;

INSERT INTO public._manual_migration_log (version) VALUES ('20261108000000') ON CONFLICT (version) DO NOTHING;
COMMIT;

-- ########## 20261109000000_admin_workflow_hardening.sql ##########
-- ============================================================================
-- LIORIS - ADMIN / STAFF / ALUMNI WORKFLOW HARDENING
-- ============================================================================
-- Runs after 20261105000000, so every function it replaces is the LATEST definition.
--
--   S1  jobs: an edit of an approved posting by its (non-admin) poster re-queues it;
--       a rejected posting gets rejected_at so it leaves the review queue (C6)
--   S2  giving campaigns: confirmed_total is admin-only, owners report reported_total;
--       admin_review_giving_campaign / admin_update_giving_total record the actor,
--       enforce campus scope, require a pending review, and audit inside SQL
--   S3  paid events: admin_apply_payment_review rejects stale / repeated decisions,
--       enforces campus scope for the actor (GLOBAL / NULL = Super Admin only)
--   S4  unsuspend_user_account() and admin_verify_user() RPCs (scope + audit inside)
--   S5  admin_broadcast_notification(): server-side fan-out with a real recipient count,
--       audit row in the same transaction, per-caller rate limit; notifications get an
--       announcement_id link so deleting an announcement removes its notifications
--   S6  audit_logs: BEFORE INSERT trigger stamps metadata.targetCampus so DB-trigger rows
--       become visible to the right campus admin (still append-only)
--   S7  moderation_queue: reporters cannot pre-set status / assignee / campus
--   C8  admin_active_users_count(): campus-scoped "active now" for the dashboards
--
-- Idempotent, one transaction. Edge functions admin-review-giving-campaign and
-- admin-review-paid-event must be redeployed together with this migration (their RPC
-- signatures gained p_actor / p_expected_* arguments).
-- ============================================================================

BEGIN;
DO $chain$ BEGIN IF NOT EXISTS (SELECT 1 FROM public._manual_migration_log WHERE version = '20261108000000') THEN RAISE EXCEPTION 'Stopped: migration 20261108000000 has not been applied. Fix it and re-run this whole file.'; END IF; END $chain$;

DO $do$
BEGIN
  IF to_regclass('public.profiles') IS NULL OR to_regclass('public.audit_logs') IS NULL THEN
    RAISE EXCEPTION 'profiles / audit_logs missing. Apply the base schema first.';
  END IF;
END
$do$;

-- ----------------------------------------------------------------------------
-- 0. Actor helpers for functions called by edge functions as service_role
--    (auth.uid() is NULL there, so authority is judged from the passed actor).
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.lioris_actor_is_super(p_actor uuid)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT COALESCE((
    SELECT p.role::text = 'admin'
       AND NOT COALESCE(p.is_suspended, false)
       AND (p.admin_role = 'super_admin' OR lower(COALESCE(p.email, '')) = 'inememmanuel@gmail.com')
    FROM public.profiles p WHERE p.id = p_actor
  ), false);
$$;

-- Super Admin: any campus. Campus Admin: only their own real campus; a GLOBAL / NULL
-- campus row (and a GLOBAL / NULL admin) never matches, so those are Super Admin only.
CREATE OR REPLACE FUNCTION public.lioris_actor_can_admin_campus(p_actor uuid, p_campus text)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT public.lioris_actor_is_super(p_actor)
      OR COALESCE((
        SELECT p.role::text = 'admin'
           AND NOT COALESCE(p.is_suspended, false)
           AND p.campus_code IS NOT NULL
           AND p.campus_code <> 'GLOBAL'
           AND p_campus IS NOT NULL
           AND p.campus_code = p_campus
        FROM public.profiles p WHERE p.id = p_actor
      ), false);
$$;

REVOKE ALL ON FUNCTION public.lioris_actor_is_super(uuid) FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.lioris_actor_can_admin_campus(uuid, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.lioris_actor_is_super(uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.lioris_actor_can_admin_campus(uuid, text) TO service_role;

-- ----------------------------------------------------------------------------
-- S1 / C6. jobs: re-review on edit; rejected_at keeps rejected postings out of the queue
-- ----------------------------------------------------------------------------
DO $do$
BEGIN
  IF to_regclass('public.jobs') IS NOT NULL THEN
    ALTER TABLE public.jobs ADD COLUMN IF NOT EXISTS rejected_at TIMESTAMPTZ;
    -- already-rejected postings (reason recorded, never approved) leave the queue
    UPDATE public.jobs
       SET rejected_at = COALESCE(approved_at, created_at, now())
     WHERE is_approved = false AND rejection_reason IS NOT NULL AND rejected_at IS NULL;
  END IF;
END
$do$;

CREATE OR REPLACE FUNCTION public.enforce_job_moderation()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
    v_role text;
    v_content_changed boolean;
BEGIN
    IF auth.uid() IS NULL THEN RETURN NEW; END IF;
    SELECT role::text INTO v_role FROM public.profiles WHERE id = auth.uid();

    IF TG_OP = 'INSERT' THEN
        IF v_role IN ('admin', 'staff') THEN RETURN NEW; END IF;
        NEW.is_approved := false;
        NEW.approved_by := NULL;
        NEW.approved_at := NULL;
        NEW.rejection_reason := NULL;
        NEW.rejected_at := NULL;
        RETURN NEW;
    END IF;

    v_content_changed :=
        NEW.title IS DISTINCT FROM OLD.title
        OR NEW.company IS DISTINCT FROM OLD.company
        OR NEW.description IS DISTINCT FROM OLD.description
        OR NEW.apply_url IS DISTINCT FROM OLD.apply_url
        OR NEW.accepts_in_app_applications IS DISTINCT FROM OLD.accepts_in_app_applications
        OR NEW.location IS DISTINCT FROM OLD.location
        OR NEW.salary IS DISTINCT FROM OLD.salary
        OR NEW.is_remote IS DISTINCT FROM OLD.is_remote;

    IF v_role = 'admin' THEN RETURN NEW; END IF;
    -- Staff moderate other people's postings freely; a staff member editing the content
    -- of their OWN approved posting goes back through review like everyone else.
    IF v_role = 'staff' AND NOT (v_content_changed AND OLD.is_approved AND OLD.poster_id = auth.uid()) THEN
        RETURN NEW;
    END IF;

    NEW.is_approved := OLD.is_approved;
    NEW.approved_by := OLD.approved_by;
    NEW.approved_at := OLD.approved_at;
    NEW.rejection_reason := OLD.rejection_reason;
    NEW.rejected_at := OLD.rejected_at;

    IF v_content_changed THEN
        IF OLD.is_approved THEN
            NEW.is_approved := false;
            NEW.approved_by := NULL;
            NEW.approved_at := NULL;
        ELSIF OLD.rejected_at IS NOT NULL OR OLD.rejection_reason IS NOT NULL THEN
            -- the poster fixed a rejected posting: it is a fresh submission for the queue
            NEW.rejected_at := NULL;
            NEW.rejection_reason := NULL;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

DO $do$
BEGIN
  IF to_regclass('public.jobs') IS NOT NULL THEN
    DROP TRIGGER IF EXISTS trg_enforce_job_moderation ON public.jobs;
    CREATE TRIGGER trg_enforce_job_moderation
      BEFORE INSERT OR UPDATE ON public.jobs
      FOR EACH ROW EXECUTE FUNCTION public.enforce_job_moderation();
  END IF;
END
$do$;

-- ----------------------------------------------------------------------------
-- S2. giving campaigns
-- ----------------------------------------------------------------------------
ALTER TABLE public.giving_campaigns
  ADD COLUMN IF NOT EXISTS reported_total NUMERIC(12, 2) NOT NULL DEFAULT 0;
DO $do$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'giving_campaigns_reported_total_nonneg') THEN
    ALTER TABLE public.giving_campaigns
      ADD CONSTRAINT giving_campaigns_reported_total_nonneg CHECK (reported_total >= 0);
  END IF;
END
$do$;
COMMENT ON COLUMN public.giving_campaigns.reported_total IS
  'Running total as REPORTED by the campaign organiser (unverified). confirmed_total is admin-only.';
COMMENT ON COLUMN public.giving_campaigns.confirmed_total IS
  'Total confirmed by an administrator. Owners cannot write it; they report reported_total.';

-- Totals owners typed into confirmed_total before this split are really organiser claims.
UPDATE public.giving_campaigns SET reported_total = confirmed_total
 WHERE reported_total = 0 AND confirmed_total > 0;

CREATE OR REPLACE FUNCTION public.enforce_giving_campaign_moderation()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
    v_role text;
BEGIN
    IF auth.uid() IS NULL THEN RETURN NEW; END IF;
    SELECT role::text INTO v_role FROM public.profiles WHERE id = auth.uid();
    IF v_role = 'admin' THEN RETURN NEW; END IF;

    IF NEW.reported_total IS NULL OR NEW.reported_total < 0 THEN
        RAISE EXCEPTION 'invalid_reported_total: The reported total must be zero or a positive amount.';
    END IF;

    IF TG_OP = 'INSERT' THEN
        NEW.review_status := 'pending';
        NEW.reviewed_by := NULL;
        NEW.reviewed_at := NULL;
        NEW.review_note := NULL;
        NEW.confirmed_total := 0;
    ELSE
        IF NEW.review_status IS DISTINCT FROM OLD.review_status
           OR NEW.reviewed_by IS DISTINCT FROM OLD.reviewed_by THEN
            NEW.review_status := OLD.review_status;
            NEW.reviewed_by := OLD.reviewed_by;
            NEW.reviewed_at := OLD.reviewed_at;
        END IF;

        -- confirmed_total is admin-only: an owner's value is silently kept at OLD.
        NEW.confirmed_total := OLD.confirmed_total;

        IF OLD.review_status = 'approved' AND (
            NEW.title IS DISTINCT FROM OLD.title
            OR NEW.description IS DISTINCT FROM OLD.description
            OR NEW.goal_amount IS DISTINCT FROM OLD.goal_amount
            OR NEW.giving_url IS DISTINCT FROM OLD.giving_url
            OR NEW.cover_image_url IS DISTINCT FROM OLD.cover_image_url
            OR NEW.campus_code IS DISTINCT FROM OLD.campus_code
        ) THEN
            NEW.review_status := 'pending';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

DROP FUNCTION IF EXISTS public.admin_review_giving_campaign(uuid, boolean, text);
CREATE OR REPLACE FUNCTION public.admin_review_giving_campaign(
    p_campaign uuid, p_approve boolean, p_note text DEFAULT NULL,
    p_actor uuid DEFAULT NULL, p_allow_rereview boolean DEFAULT false
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
    c public.giving_campaigns%ROWTYPE;
    v_note text := NULLIF(btrim(COALESCE(p_note, '')), '');
    v_status text;
    v_rows int;
BEGIN
    IF p_actor IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.profiles WHERE id = p_actor AND role::text = 'admin' AND NOT COALESCE(is_suspended, false)
    ) THEN
        RAISE EXCEPTION 'not_allowed: Only an active administrator can review a giving campaign.';
    END IF;

    SELECT * INTO c FROM public.giving_campaigns WHERE id = p_campaign FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'not_found: That giving campaign does not exist.'; END IF;

    IF NOT public.lioris_actor_can_admin_campus(p_actor, c.campus_code) THEN
        RAISE EXCEPTION 'not_allowed: Campus Admins can only review campaigns of their own campus; global campaigns are for Super Admins.';
    END IF;

    IF c.review_status <> 'pending'
       AND NOT (COALESCE(p_allow_rereview, false) AND public.lioris_actor_is_super(p_actor)) THEN
        RAISE EXCEPTION 'already_reviewed: This campaign was already % (re-review is a Super Admin action).', c.review_status;
    END IF;

    IF NOT p_approve THEN
        IF v_note IS NULL OR char_length(v_note) < 5 THEN
            RAISE EXCEPTION 'note_required: A rejection needs a short reason (5+ characters).';
        END IF;
    END IF;
    v_status := CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END;

    UPDATE public.giving_campaigns
       SET review_status = v_status, reviewed_by = p_actor, reviewed_at = now(), review_note = v_note
     WHERE id = p_campaign;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows = 0 THEN RAISE EXCEPTION 'not_found: Nothing was updated; the campaign no longer exists.'; END IF;

    INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
    VALUES (p_actor,
            CASE WHEN p_approve THEN 'giving_campaign_approved' ELSE 'giving_campaign_rejected' END,
            'giving_campaign', p_campaign,
            jsonb_build_object('summary', format('%s giving campaign "%s"', CASE WHEN p_approve THEN 'Approved' ELSE 'Rejected' END, c.title),
                               'reason', v_note, 'previousStatus', c.review_status,
                               'institutionCode', c.campus_code, 'targetIdRaw', p_campaign::text));

    RETURN jsonb_build_object('campaign_id', p_campaign, 'review_status', v_status);
END;
$$;
REVOKE ALL ON FUNCTION public.admin_review_giving_campaign(uuid, boolean, text, uuid, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.admin_review_giving_campaign(uuid, boolean, text, uuid, boolean) TO service_role;

DROP FUNCTION IF EXISTS public.admin_update_giving_total(uuid, numeric);
CREATE OR REPLACE FUNCTION public.admin_update_giving_total(
    p_campaign uuid, p_confirmed_total numeric, p_actor uuid DEFAULT NULL
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
    c public.giving_campaigns%ROWTYPE;
BEGIN
    IF p_actor IS NULL OR NOT EXISTS (
        SELECT 1 FROM public.profiles WHERE id = p_actor AND role::text = 'admin' AND NOT COALESCE(is_suspended, false)
    ) THEN
        RAISE EXCEPTION 'not_allowed: Only an active administrator can confirm a total.';
    END IF;
    IF p_confirmed_total IS NULL OR p_confirmed_total < 0 OR p_confirmed_total > 1000000000 THEN
        RAISE EXCEPTION 'invalid_total: The confirmed total must be a non-negative amount.';
    END IF;
    SELECT * INTO c FROM public.giving_campaigns WHERE id = p_campaign FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'not_found: That giving campaign does not exist.'; END IF;
    IF NOT public.lioris_actor_can_admin_campus(p_actor, c.campus_code) THEN
        RAISE EXCEPTION 'not_allowed: Campus Admins can only update campaigns of their own campus.';
    END IF;

    UPDATE public.giving_campaigns SET confirmed_total = p_confirmed_total WHERE id = p_campaign;

    INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
    VALUES (p_actor, 'giving_total_confirmed', 'giving_campaign', p_campaign,
            jsonb_build_object('summary', format('Confirmed total for "%s" set to %s', c.title, p_confirmed_total),
                               'old', c.confirmed_total, 'new', p_confirmed_total,
                               'institutionCode', c.campus_code, 'targetIdRaw', p_campaign::text));
    RETURN jsonb_build_object('campaign_id', p_campaign, 'confirmed_total', p_confirmed_total);
END;
$$;
REVOKE ALL ON FUNCTION public.admin_update_giving_total(uuid, numeric, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.admin_update_giving_total(uuid, numeric, uuid) TO service_role;

-- ----------------------------------------------------------------------------
-- S3. paid events: admin_apply_payment_review
-- ----------------------------------------------------------------------------
DO $do$
BEGIN
  IF to_regprocedure('public.admin_apply_payment_review(uuid, uuid, text, text, boolean, boolean)') IS NOT NULL THEN
    DROP FUNCTION public.admin_apply_payment_review(uuid, uuid, text, text, boolean, boolean);
  END IF;
END
$do$;

CREATE OR REPLACE FUNCTION public.admin_apply_payment_review(
  p_event uuid, p_actor uuid, p_decision text, p_note text DEFAULT NULL,
  p_override_link_check boolean DEFAULT false, p_publish boolean DEFAULT false,
  p_expected_payment_url text DEFAULT NULL, p_expected_updated_at timestamptz DEFAULT NULL,
  p_allow_rereview boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  e public.events%ROWTYPE;
  d public.event_payment_details%ROWTYPE;
  v_note text := NULLIF(btrim(COALESCE(p_note, '')), '');
  v_status text;
  v_host text;
  v_prev text;
BEGIN
  IF p_actor IS NULL OR NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = p_actor AND role::text = 'admin' AND COALESCE(is_suspended, false) = false) THEN
    RAISE EXCEPTION 'not_allowed';
  END IF;
  IF p_decision NOT IN ('approve', 'reject') THEN RAISE EXCEPTION 'invalid_input: decision must be approve or reject.'; END IF;
  SELECT * INTO e FROM public.events WHERE id = p_event FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found'; END IF;
  IF NOT public.lioris_actor_can_admin_campus(p_actor, e.campus_code) THEN
    RAISE EXCEPTION 'not_allowed: Campus Admins can only review events of their own campus; global events are for Super Admins.';
  END IF;
  IF e.ticket_type <> 'paid' THEN RAISE EXCEPTION 'not_paid: This event is free.'; END IF;

  v_prev := e.payment_review_status;
  IF v_prev <> 'pending' AND NOT (COALESCE(p_allow_rereview, false) AND public.lioris_actor_is_super(p_actor)) THEN
    RAISE EXCEPTION 'already_reviewed: This payment review is already % (reload the desk; re-review is a Super Admin action).', v_prev;
  END IF;

  SELECT * INTO d FROM public.event_payment_details WHERE event_id = p_event FOR UPDATE;
  IF p_expected_payment_url IS NOT NULL AND d.payment_url IS DISTINCT FROM p_expected_payment_url THEN
    RAISE EXCEPTION 'stale_review: The organiser changed the payment link since you opened this review. Reload and review again.';
  END IF;
  IF p_expected_updated_at IS NOT NULL AND d.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'stale_review: The payment details changed since you opened this review. Reload and review again.';
  END IF;

  IF p_decision = 'reject' THEN
    IF v_note IS NULL OR length(v_note) < 5 THEN RAISE EXCEPTION 'note_required: Tell the organiser why the payment details were not approved.'; END IF;
    v_status := 'rejected';
  ELSE
    IF e.payment_method IN ('online', 'both') THEN
      IF d.payment_url IS NULL THEN RAISE EXCEPTION 'payment_link_required: The organiser has not added a payment link.'; END IF;
      IF NOT p_override_link_check THEN
        IF d.link_check IS NULL OR d.link_check ->> 'url' IS DISTINCT FROM d.payment_url THEN
          RAISE EXCEPTION 'link_not_checked: Run the link check on the current payment link first.';
        END IF;
        IF d.link_check ->> 'status' = 'failed' THEN
          RAISE EXCEPTION 'link_check_failed: The payment link failed its check. Ask the organiser for a working link, or override with a note.';
        END IF;
      ELSIF v_note IS NULL OR length(v_note) < 5 THEN
        RAISE EXCEPTION 'note_required: Say why you are approving without a passing link check.';
      END IF;
    END IF;
    IF e.payment_method IN ('at_venue', 'both') AND (d.instructions IS NULL OR length(d.instructions) < 5) THEN
      RAISE EXCEPTION 'instructions_required: The organiser has not said how people pay at the venue.';
    END IF;
    v_status := 'approved';
  END IF;

  PERFORM set_config('lioris.paid_internal', '1', true);
  UPDATE public.events
     SET payment_review_status = v_status, payment_reviewed_by = p_actor, payment_reviewed_at = now(), payment_review_note = v_note,
         status = CASE WHEN p_publish AND v_status = 'approved' AND status::text = 'pending_approval' THEN 'upcoming'::event_status_type ELSE status END
   WHERE id = p_event
   RETURNING * INTO e;
  PERFORM set_config('lioris.paid_internal', '0', true);

  v_host := lower(substring(d.payment_url FROM '^https://([^/?#]*)'));
  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  VALUES (p_actor,
          CASE WHEN v_status = 'approved' THEN 'event_payment_approved' ELSE 'event_payment_rejected' END,
          'event', p_event,
          jsonb_build_object('summary', format('%s payment details for "%s" (NGN %s, %s)', CASE WHEN v_status = 'approved' THEN 'Approved' ELSE 'Rejected' END, e.title, e.ticket_price, e.payment_method),
                             'reason', v_note, 'linkHost', v_host, 'override', p_override_link_check, 'published', p_publish,
                             'previousStatus', v_prev, 'institutionCode', e.campus_code,
                             'targetIdRaw', p_event::text, 'actorRole', 'admin'));

  PERFORM public.event_paid_notify(e.creator_id,
    CASE WHEN v_status = 'approved' THEN 'Payment details approved' ELSE 'Payment details need changes' END,
    CASE WHEN v_status = 'approved'
         THEN format('Students can now see how to pay for "%s".', e.title)
         ELSE format('"%s": %s', e.title, v_note) END,
    '/events/' || p_event::text);

  RETURN jsonb_build_object('event_id', e.id, 'payment_review_status', e.payment_review_status, 'status', e.status::text);
END $$;

REVOKE ALL ON FUNCTION public.admin_apply_payment_review(uuid, uuid, text, text, boolean, boolean, text, timestamptz, boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.admin_apply_payment_review(uuid, uuid, text, text, boolean, boolean, text, timestamptz, boolean) TO service_role;

-- ----------------------------------------------------------------------------
-- S4. unsuspend_user_account / admin_verify_user
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.unsuspend_user_account(p_user_id uuid, p_reason text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_caller_role text;
  v_caller_susp boolean;
  v_t public.profiles%ROWTYPE;
  v_reason text := left(NULLIF(btrim(COALESCE(p_reason, '')), ''), 500);
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Authentication required.' USING ERRCODE = '28000'; END IF;
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'Target user is required.'; END IF;
  SELECT role::text, COALESCE(is_suspended, false) INTO v_caller_role, v_caller_susp FROM public.profiles WHERE id = v_uid;
  IF v_caller_role IS NULL OR v_caller_role NOT IN ('admin', 'staff') OR v_caller_susp THEN
    RAISE EXCEPTION 'Insufficient permissions to unsuspend user accounts.' USING ERRCODE = '42501';
  END IF;
  IF v_uid = p_user_id THEN RAISE EXCEPTION 'You cannot change the suspension of your own account.' USING ERRCODE = '42501'; END IF;

  SELECT * INTO v_t FROM public.profiles WHERE id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Target user not found.'; END IF;

  IF NOT public.can_admin_campus(v_t.campus_code) THEN
    RAISE EXCEPTION 'You can only unsuspend members of your own campus.' USING ERRCODE = '42501';
  END IF;
  IF (v_t.role::text = 'admin' OR v_t.admin_role = 'super_admin') AND NOT public.auth_is_super_admin() THEN
    RAISE EXCEPTION 'Only a Super Admin can unsuspend an administrator account.' USING ERRCODE = '42501';
  END IF;
  IF v_caller_role = 'staff' AND v_t.role::text IN ('admin', 'staff') THEN
    RAISE EXCEPTION 'Staff cannot unsuspend admin or staff accounts.' USING ERRCODE = '42501';
  END IF;

  IF NOT COALESCE(v_t.is_suspended, false) THEN
    RETURN jsonb_build_object('success', true, 'changed', false, 'message', 'User account is not suspended.');
  END IF;

  PERFORM set_config('lioris.audit_skip', 'is_suspended', true);
  UPDATE public.profiles
     SET is_suspended = false,
         suspension_reason = NULL,
         muted_until = CASE WHEN suspension_reason LIKE '[7-Day Suspension]%' THEN NULL ELSE muted_until END
   WHERE id = p_user_id;
  PERFORM set_config('lioris.audit_skip', '', true);

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  VALUES (v_uid, 'user_unsuspended', 'user', p_user_id,
          jsonb_build_object('summary', 'Account unsuspended via unsuspend_user_account()',
                             'reason', v_reason, 'previousReason', v_t.suspension_reason,
                             'targetRole', v_t.role::text, 'targetCampus', v_t.campus_code,
                             'source', 'unsuspend_user_account'));

  RETURN jsonb_build_object('success', true, 'changed', true, 'message', 'User account unsuspended.');
END;
$$;
REVOKE ALL ON FUNCTION public.unsuspend_user_account(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.unsuspend_user_account(uuid, text) TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.admin_verify_user(p_user_id uuid, p_note text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_t public.profiles%ROWTYPE;
  v_note text := left(NULLIF(btrim(COALESCE(p_note, '')), ''), 500);
  v_closed int := 0;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'invalid_input: target user is required'; END IF;
  IF p_user_id = v_uid THEN RAISE EXCEPTION 'conflict_of_interest: you cannot verify your own account'; END IF;

  SELECT * INTO v_t FROM public.profiles WHERE id = p_user_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found: that member no longer exists'; END IF;

  IF NOT public.can_admin_campus(v_t.campus_code) THEN
    RAISE EXCEPTION 'unauthorized_campus_scope: you can only verify members of your own campus';
  END IF;
  IF NOT public.has_role_permission('can_verify_students') THEN
    RAISE EXCEPTION 'permission_disabled: ID verification is switched off for your role';
  END IF;
  IF (v_t.role::text = 'admin' OR v_t.admin_role = 'super_admin') AND NOT public.auth_is_super_admin() THEN
    RAISE EXCEPTION 'unauthorized_campus_scope: only a Super Admin can change an administrator account';
  END IF;

  IF v_t.verification_status::text = 'verified' THEN
    RETURN jsonb_build_object('user_id', p_user_id, 'verification_status', 'verified', 'changed', false);
  END IF;

  -- resolve any pending request in the same transaction (same shape as review_verification_request)
  UPDATE public.verifications
     SET status = 'approved'::public.moderation_status_type,
         reviewed_by = v_uid,
         reviewed_at = now(),
         rejection_reason = NULL
   WHERE user_id = p_user_id AND status::text = 'pending';
  GET DIAGNOSTICS v_closed = ROW_COUNT;

  PERFORM set_config('lioris.audit_skip', 'verification_status', true);
  UPDATE public.profiles
     SET verification_status = 'verified'::public.verification_status_type
   WHERE id = p_user_id;
  PERFORM set_config('lioris.audit_skip', '', true);

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  VALUES (v_uid, 'user_verified', 'user', p_user_id,
          jsonb_build_object('summary', format('Verified %s directly (%s pending request(s) closed)', COALESCE(v_t.full_name, 'member'), v_closed),
                             'old', v_t.verification_status::text, 'new', 'verified', 'reason', v_note,
                             'targetCampus', v_t.campus_code, 'institutionCode', v_t.campus_code,
                             'source', 'admin_verify_user'));

  RETURN jsonb_build_object('user_id', p_user_id, 'verification_status', 'verified', 'changed', true, 'requests_closed', v_closed);
END;
$$;
REVOKE ALL ON FUNCTION public.admin_verify_user(uuid, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_verify_user(uuid, text) TO authenticated, service_role;

-- ----------------------------------------------------------------------------
-- S5. server-side broadcast
-- ----------------------------------------------------------------------------
DO $do$
BEGIN
  IF to_regclass('public.notifications') IS NOT NULL AND to_regclass('public.announcements') IS NOT NULL THEN
    ALTER TABLE public.notifications
      ADD COLUMN IF NOT EXISTS announcement_id UUID REFERENCES public.announcements(id) ON DELETE CASCADE;
    CREATE INDEX IF NOT EXISTS idx_notifications_announcement ON public.notifications (announcement_id)
      WHERE announcement_id IS NOT NULL;
  END IF;
END
$do$;

CREATE OR REPLACE FUNCTION public.admin_broadcast_notification(
  p_title text, p_body text, p_type text DEFAULT 'system_announcement', p_audience jsonb DEFAULT '{}'::jsonb,
  p_action_url text DEFAULT NULL, p_announcement_id uuid DEFAULT NULL, p_dry_run boolean DEFAULT false)
RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_role text;
  v_susp boolean;
  v_own_campus text;
  v_super boolean;
  v_aud jsonb := CASE WHEN jsonb_typeof(COALESCE(p_audience, '{}'::jsonb)) = 'object' THEN COALESCE(p_audience, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_campus text;
  v_all boolean;
  v_include_global boolean := COALESCE((v_aud ->> 'includeGlobal')::boolean, false);
  v_roles text[];
  v_title text := left(btrim(COALESCE(p_title, '')), 150);
  v_body text := left(btrim(COALESCE(p_body, '')), 1000);
  v_action text := NULLIF(btrim(COALESCE(p_action_url, '')), '');
  v_count integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT role::text, campus_code, COALESCE(is_suspended, false) INTO v_role, v_own_campus, v_susp FROM public.profiles WHERE id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'staff') OR v_susp THEN
    RAISE EXCEPTION 'not_allowed: only active admins and staff can broadcast.';
  END IF;
  IF NOT public.has_role_permission('can_broadcast_announcements') THEN
    RAISE EXCEPTION 'permission_disabled: broadcasting is switched off for your role.';
  END IF;
  IF v_title = '' OR v_body = '' THEN RAISE EXCEPTION 'invalid_input: a title and a message are required.'; END IF;
  IF p_type NOT IN ('system', 'system_announcement', 'announcement', 'event', 'moderation') THEN
    RAISE EXCEPTION 'invalid_input: unsupported notification type.';
  END IF;
  IF v_action IS NOT NULL AND (left(v_action, 1) <> '/' OR left(v_action, 2) = '//') THEN
    RAISE EXCEPTION 'invalid_input: the link must be an in-app path.';
  END IF;

  v_super := public.auth_is_super_admin();
  v_campus := NULLIF(btrim(COALESCE(v_aud ->> 'campus', '')), '');
  v_all := v_campus IS NULL OR upper(v_campus) = 'ALL';
  IF NOT v_super THEN
    IF v_own_campus IS NULL OR v_own_campus = 'GLOBAL' THEN
      RAISE EXCEPTION 'not_allowed: your account has no campus to broadcast to.';
    END IF;
    IF v_campus IS NOT NULL AND upper(v_campus) <> 'ALL' AND v_campus <> v_own_campus THEN
      RAISE EXCEPTION 'not_allowed: you can only broadcast to your own campus.';
    END IF;
    IF v_campus IS NOT NULL AND upper(v_campus) = 'ALL' THEN
      RAISE EXCEPTION 'not_allowed: only a Super Admin can broadcast to every campus.';
    END IF;
    IF NOT public.can_admin_campus(v_own_campus) THEN
      RAISE EXCEPTION 'not_allowed: your campus authority is not active.';
    END IF;
    v_all := false;
    v_campus := v_own_campus;
    v_include_global := false;
  END IF;

  SELECT array_agg(DISTINCT lower(r)) INTO v_roles
    FROM jsonb_array_elements_text(COALESCE(v_aud -> 'roles', '[]'::jsonb)) r
   WHERE lower(r) IN ('student', 'alumni', 'staff', 'admin');
  -- dry run: the same authority checks and recipient filter, but nothing is written and no rate-limit slot is used
  -- (the composer shows "this will reach N people" before the sender confirms)
  IF COALESCE(p_dry_run, false) THEN
    SELECT count(*)::integer INTO v_count
      FROM public.profiles p
      LEFT JOIN public.notification_preferences np ON np.user_id = p.id
     WHERE NOT COALESCE(p.is_suspended, false)
       AND NOT COALESCE(p.is_bot, false)
       AND (to_jsonb(p) ->> 'deactivated_at') IS NULL
       AND (v_all OR p.campus_code = v_campus OR (v_include_global AND p.campus_code = 'GLOBAL'))
       AND (v_roles IS NULL OR p.role::text = ANY (v_roles))
       AND CASE
             WHEN p_type IN ('announcement', 'system_announcement') THEN COALESCE(np.announcements_enabled, true)
             WHEN p_type = 'event' THEN COALESCE(np.events_enabled, true)
             ELSE true
           END;
    RETURN v_count;
  END IF;

  IF NOT public.consume_rate_limit('broadcast:' || v_uid::text, 20, 3600) THEN
    RAISE EXCEPTION 'rate_limited: too many broadcasts. Try again later.';
  END IF;

  INSERT INTO public.notifications (recipient_id, sender_id, title, body, type, action_url, is_read, announcement_id)
  SELECT p.id, v_uid, v_title, v_body, p_type, v_action, false, p_announcement_id
    FROM public.profiles p
    LEFT JOIN public.notification_preferences np ON np.user_id = p.id
   WHERE NOT COALESCE(p.is_suspended, false)
     AND NOT COALESCE(p.is_bot, false)
     AND (to_jsonb(p) ->> 'deactivated_at') IS NULL
     AND (v_all OR p.campus_code = v_campus OR (v_include_global AND p.campus_code = 'GLOBAL'))
     AND (v_roles IS NULL OR p.role::text = ANY (v_roles))
     AND CASE
           WHEN p_type IN ('announcement', 'system_announcement') THEN COALESCE(np.announcements_enabled, true)
           WHEN p_type = 'event' THEN COALESCE(np.events_enabled, true)
           ELSE true
         END;
  GET DIAGNOSTICS v_count = ROW_COUNT;

  INSERT INTO public.audit_logs (actor_id, action, entity_type, entity_id, metadata)
  VALUES (v_uid, 'broadcast_sent', 'notification', p_announcement_id,
          jsonb_build_object('summary', format('Broadcast "%s" to %s recipient(s) (%s)', v_title, v_count, CASE WHEN v_all THEN 'all campuses' ELSE v_campus END),
                             'recipients', v_count, 'audience', v_aud, 'type', p_type,
                             'targetCampus', CASE WHEN v_all THEN NULL ELSE v_campus END,
                             'source', 'admin_broadcast_notification'));
  RETURN v_count;
END;
$$;
REVOKE ALL ON FUNCTION public.admin_broadcast_notification(text, text, text, jsonb, text, uuid, boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_broadcast_notification(text, text, text, jsonb, text, uuid, boolean) TO authenticated;

-- ----------------------------------------------------------------------------
-- S6. audit_logs: stamp metadata.targetCampus (campus admins see what concerns their campus)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.audit_logs_stamp_target_campus()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  v_tbl text;
  v_campus text;
  v_uid uuid;
BEGIN
  IF NEW.metadata IS NULL THEN
    NEW.metadata := '{}'::jsonb;
  ELSIF jsonb_typeof(NEW.metadata) <> 'object' THEN
    NEW.metadata := jsonb_build_object('raw', NEW.metadata);
  END IF;
  IF COALESCE(NULLIF(NEW.metadata ->> 'targetCampus', ''), NULLIF(NEW.metadata ->> 'institutionCode', '')) IS NOT NULL THEN
    RETURN NEW;
  END IF;

  BEGIN
    v_tbl := CASE NEW.entity_type
      WHEN 'user' THEN 'profiles' WHEN 'profile' THEN 'profiles' WHEN 'user_profile' THEN 'profiles'
      WHEN 'event' THEN 'events' WHEN 'post' THEN 'posts' WHEN 'resource' THEN 'resources'
      WHEN 'job' THEN 'jobs' WHEN 'giving_campaign' THEN 'giving_campaigns'
      WHEN 'marketplace_listing' THEN 'marketplace_listings' WHEN 'announcement' THEN 'announcements'
      WHEN 'verification_request' THEN 'verifications' WHEN 'verification' THEN 'verifications'
      ELSE NULL END;
    IF v_tbl IS NOT NULL AND NEW.entity_id IS NOT NULL THEN
      EXECUTE format('SELECT campus_code FROM public.%I WHERE id = $1', v_tbl) INTO v_campus USING NEW.entity_id;
    END IF;
    IF v_campus IS NULL AND NULLIF(NEW.metadata ->> 'targetUserId', '') IS NOT NULL THEN
      v_uid := (NEW.metadata ->> 'targetUserId')::uuid;
      SELECT campus_code INTO v_campus FROM public.profiles WHERE id = v_uid;
    END IF;
    IF v_campus IS NULL THEN
      v_campus := COALESCE(NULLIF(NEW.metadata ->> 'campus_code', ''), NULLIF(NEW.metadata ->> 'campusCode', ''));
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_campus := NULL;   -- an audit row must never fail because its campus could not be resolved
  END;

  IF v_campus IS NOT NULL AND v_campus <> '' THEN
    NEW.metadata := NEW.metadata || jsonb_build_object('targetCampus', v_campus);
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_audit_logs_stamp_target_campus ON public.audit_logs;
CREATE TRIGGER trg_audit_logs_stamp_target_campus
  BEFORE INSERT ON public.audit_logs
  FOR EACH ROW EXECUTE FUNCTION public.audit_logs_stamp_target_campus();

-- ----------------------------------------------------------------------------
-- S7. moderation_queue: a reporter reports, they do not triage
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.lioris_moderation_item_campus(p_item_type text, p_item_id uuid)
RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE v text;
BEGIN
  IF p_item_id IS NULL THEN RETURN NULL; END IF;
  BEGIN
    IF p_item_type = 'post' THEN SELECT campus_code INTO v FROM public.posts WHERE id = p_item_id;
    ELSIF p_item_type = 'event' THEN SELECT campus_code INTO v FROM public.events WHERE id = p_item_id;
    ELSIF p_item_type = 'resource' THEN SELECT campus_code INTO v FROM public.resources WHERE id = p_item_id;
    ELSIF p_item_type = 'marketplace_listing' THEN SELECT campus_code INTO v FROM public.marketplace_listings WHERE id = p_item_id;
    ELSIF p_item_type = 'job' THEN SELECT campus_code INTO v FROM public.jobs WHERE id = p_item_id;
    ELSIF p_item_type IN ('user', 'user_profile') THEN SELECT campus_code INTO v FROM public.profiles WHERE id = p_item_id;
    ELSIF p_item_type = 'pod_post' THEN
      SELECT sg.campus_code INTO v FROM public.study_group_posts sgp
        JOIN public.study_groups sg ON sg.id = sgp.group_id WHERE sgp.id = p_item_id;
    ELSIF p_item_type IN ('comment', 'message') THEN
      SELECT p.campus_code INTO v FROM public.chat_messages cm
        JOIN public.profiles p ON p.id = cm.sender_id WHERE cm.id = p_item_id;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v := NULL;
  END;
  RETURN NULLIF(v, '');
END;
$$;
REVOKE ALL ON FUNCTION public.lioris_moderation_item_campus(text, uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.lioris_moderation_item_campus(text, uuid) TO service_role;

CREATE OR REPLACE FUNCTION public.constrain_moderation_queue_insert()
RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  v_campus text;
BEGIN
  -- service role / migrations / SECURITY DEFINER internals that run without a signed-in user keep control
  IF auth.uid() IS NULL OR auth.role() = 'service_role' THEN RETURN NEW; END IF;

  NEW.status := 'pending';
  NEW.assigned_admin_id := NULL;
  NEW.action_taken := NULL;
  NEW.resolved_at := NULL;
  NEW.reporter_id := auth.uid();

  v_campus := public.lioris_moderation_item_campus(NEW.item_type::text, NEW.item_id);
  IF v_campus IS NULL OR v_campus = 'GLOBAL' THEN
    SELECT campus_code INTO v_campus FROM public.profiles WHERE id = auth.uid();
  END IF;
  NEW.campus_code := COALESCE(NULLIF(v_campus, ''), 'GLOBAL');
  RETURN NEW;
END;
$$;

DO $do$
BEGIN
  IF to_regclass('public.moderation_queue') IS NOT NULL THEN
    DROP TRIGGER IF EXISTS trg_a_moderation_queue_constrain_insert ON public.moderation_queue;
    CREATE TRIGGER trg_a_moderation_queue_constrain_insert
      BEFORE INSERT ON public.moderation_queue
      FOR EACH ROW EXECUTE FUNCTION public.constrain_moderation_queue_insert();
  END IF;
END
$do$;

-- ----------------------------------------------------------------------------
-- C8. admin_active_users_count(): the dashboards' "active now", campus-scoped
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.admin_active_users_count(p_minutes integer DEFAULT 15, p_campus text DEFAULT NULL)
RETURNS integer
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_role text;
  v_campus text;
  v_minutes integer := LEAST(GREATEST(COALESCE(p_minutes, 15), 1), 10080);
  v_n integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT role::text, campus_code INTO v_role, v_campus FROM public.profiles WHERE id = v_uid;
  IF v_role IS NULL OR v_role NOT IN ('admin', 'staff') THEN RAISE EXCEPTION 'not_allowed'; END IF;
  IF public.auth_is_super_admin() THEN
    v_campus := NULLIF(p_campus, '');
    IF v_campus IS NOT NULL AND upper(v_campus) = 'ALL' THEN v_campus := NULL; END IF;
  ELSE
    IF v_campus IS NULL OR v_campus = 'GLOBAL' THEN RETURN 0; END IF;
  END IF;
  SELECT count(*)::integer INTO v_n
    FROM public.profiles p
   WHERE p.last_active_at >= now() - make_interval(mins => v_minutes)
     AND NOT COALESCE(p.is_bot, false)
     AND (v_campus IS NULL OR p.campus_code = v_campus);
  RETURN COALESCE(v_n, 0);
END;
$$;
REVOKE ALL ON FUNCTION public.admin_active_users_count(integer, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_active_users_count(integer, text) TO authenticated;

NOTIFY pgrst, 'reload schema';

